package com.bettermonsterexamine;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/**
 * Locks the four bounded shapes the Bucket API leaves in TEXT/{@code max_hit} fields, using the
 * real strings observed for the issue-#24 monsters (Tormented Demon, Vardorvis, Stranger) plus
 * clean cases (Vorkath, Blue Moon).
 */
public class WikiSanitizerTest
{
	/** Wrap content in the U+007F delimiters of a MediaWiki strip-marker, as Bucket returns it. */
	private static String marker(String inner)
	{
		String del = String.valueOf((char) 0x7f);
		return del + inner + del;
	}

	@Test
	public void plainlistDivUnwrapsToBulletValues()
	{
		// Tormented Demon (#24): one array element wraps a <div class="plainlist"> + * bullets.
		List<String> raw = Collections.singletonList(
			"<div class=\"plainlist \" >\n*31 (auto)\n*45 (special)\n</div>");

		assertEquals(Arrays.asList("31 (auto)", "45 (special)"), WikiSanitizer.maxHitLines(raw));
	}

	@Test
	public void stripMarkersDroppedKeepingTheValue()
	{
		// Vardorvis (#24): a <ref> footnote strip-marker trails the first value; second is clean.
		List<String> raw = Arrays.asList(
			"30-37 (Melee)" + marker("UNIQ--ref-00000049-QINU"),
			"?? (axes)");

		assertEquals(Arrays.asList("30-37 (Melee)", "?? (axes)"), WikiSanitizer.maxHitLines(raw));
	}

	@Test
	public void brSplitsASingleElementIntoLines()
	{
		List<String> raw = Collections.singletonList("16 (Stab)<br/>50 (Dragonfire)");

		assertEquals(Arrays.asList("16 (Stab)", "50 (Dragonfire)"), WikiSanitizer.maxHitLines(raw));
	}

	@Test
	public void cleanMultiValueArrayPassesThrough()
	{
		// Vorkath: already-clean per-style array — unchanged.
		List<String> raw = Arrays.asList("30 (Magic)", "28 (Ranged)", "121 (Dragonfire Bomb/Special)");

		assertEquals(raw, WikiSanitizer.maxHitLines(raw));
	}

	@Test
	public void nullAndEmptyElementsAreSkipped()
	{
		List<String> raw = Arrays.asList("32", null, "", "  ");

		assertEquals(Collections.singletonList("32"), WikiSanitizer.maxHitLines(raw));
		assertEquals(Collections.emptyList(), WikiSanitizer.maxHitLines(null));
	}

	@Test
	public void textStripsWikilinks()
	{
		// Vorkath poisonous = "Yes ([[venom]])"; piped links keep the label.
		assertEquals("Yes (venom)", WikiSanitizer.text("Yes ([[venom]])"));
		assertEquals("b", WikiSanitizer.text("[[a|b]]"));
	}

	@Test
	public void textDropsStripMarkerFromTextField()
	{
		// Stranger (#24): the max-hit description carries a trailing <ref> strip-marker.
		assertEquals("115% of targeted player's max hit",
			WikiSanitizer.text("115% of targeted player's max hit" + marker("UNIQ--ref-0000001A-QINU")));
	}

	@Test
	public void textHandlesNullAndPlainValues()
	{
		assertNull(WikiSanitizer.text(null));
		assertEquals("No", WikiSanitizer.text("No"));
	}
}

package com.bettermonsterexamine;

import java.util.Arrays;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class StatFormatTest
{
	@Test
	public void maxValueParsesPlainValue()
	{
		assertEquals(30, StatFormat.maxValue("30 (Magic)"));
	}

	@Test
	public void maxValueParsesBareNumber()
	{
		assertEquals(32, StatFormat.maxValue("32"));
	}

	@Test
	public void maxValueUsesTheTopOfARange()
	{
		assertEquals(61, StatFormat.maxValue("46-61 (Melee)"));
	}

	@Test
	public void maxValueParsesLargeSpecialValue()
	{
		assertEquals(121, StatFormat.maxValue("121 (Dragonfire Bomb/Special)"));
	}

	@Test
	public void maxValueIgnoresNumbersInTheLabel()
	{
		// Only the value before "(" counts — digits inside the label must not win.
		assertEquals(30, StatFormat.maxValue("30 (hits up to 99 in a thing)"));
	}

	@Test
	public void maxValueReturnsMinusOneWhenNoValue()
	{
		assertEquals(-1, StatFormat.maxValue("—"));
	}

	@Test
	public void bonusIsSigned()
	{
		assertEquals("+5", StatFormat.bonus(5));
		// Zero counts as non-negative, so it carries the + sign (matching the wiki's "+0").
		assertEquals("+0", StatFormat.bonus(0));
		assertEquals("-3", StatFormat.bonus(-3));
	}

	@Test
	public void numIsDashForAbsentLevels()
	{
		assertEquals("—", StatFormat.num(0));
		assertEquals("—", StatFormat.num(-1));
		assertEquals("99", StatFormat.num(99));
	}

	@Test
	public void numberDropsTrailingZero()
	{
		assertEquals("50", StatFormat.number(50.0));
		assertEquals("77.5", StatFormat.number(77.5));
		assertEquals("-50", StatFormat.number(-50.0));
	}

	@Test
	public void attributeNamesMapKnownKeys()
	{
		assertEquals("Draconic, Undead", StatFormat.attributeNames(Arrays.asList("dragon", "undead")));
		assertEquals("Vampyre (tier 2)", StatFormat.attributeNames(Arrays.asList("vampyre2")));
	}

	@Test
	public void joinSkipsBlanksAndNullsWhenEmpty()
	{
		assertEquals("7x7, Draconic", StatFormat.join(", ", "7x7", null, "", "Draconic"));
		assertNull(StatFormat.join(", ", null, ""));
	}
}

package com.bettermonsterexamine;

import java.awt.Color;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class StatColorsTest
{
	@Test
	public void offModeIsAlwaysWhite()
	{
		assertEquals(Color.WHITE, StatColors.resolve(ColourRole.DANGER, HighlightMode.OFF));
		assertEquals(Color.WHITE, StatColors.resolve(ColourRole.GOOD, HighlightMode.OFF));
		assertEquals(Color.WHITE, StatColors.levelColor(HighlightMode.OFF, 100, 50));
	}

	@Test
	public void standardDangerAndGood()
	{
		assertEquals(StatColors.DANGER_RED, StatColors.resolve(ColourRole.DANGER, HighlightMode.STANDARD));
		assertEquals(net.runelite.client.ui.ColorScheme.PROGRESS_COMPLETE_COLOR, StatColors.resolve(ColourRole.GOOD, HighlightMode.STANDARD));
		assertEquals(Color.WHITE, StatColors.resolve(ColourRole.NEUTRAL, HighlightMode.STANDARD));
	}

	@Test
	public void colourBlindUsesOkabeIto()
	{
		assertEquals(StatColors.CB_DANGER, StatColors.resolve(ColourRole.DANGER, HighlightMode.COLOUR_BLIND));
		assertEquals(StatColors.CB_GOOD, StatColors.resolve(ColourRole.GOOD, HighlightMode.COLOUR_BLIND));
	}

	@Test
	public void standardLevelGradientByDifference()
	{
		// Monster far below the player → green; at parity → yellow; far above → red.
		assertEquals(new Color(0x00FF00), StatColors.levelColor(HighlightMode.STANDARD, 100, 50));
		assertEquals(new Color(0xFFFF00), StatColors.levelColor(HighlightMode.STANDARD, 100, 100));
		assertEquals(new Color(0xFF0000), StatColors.levelColor(HighlightMode.STANDARD, 50, 100));
	}

	@Test
	public void unknownPlayerLevelIsWhite()
	{
		assertEquals(Color.WHITE, StatColors.levelColor(HighlightMode.STANDARD, -1, 100));
		assertEquals(Color.WHITE, StatColors.levelColor(HighlightMode.COLOUR_BLIND, -1, 100));
	}

	@Test
	public void colourBlindLevelIsDirectional()
	{
		assertEquals(StatColors.CB_DANGER, StatColors.levelColor(HighlightMode.COLOUR_BLIND, 50, 100));
		assertEquals(StatColors.CB_GOOD, StatColors.levelColor(HighlightMode.COLOUR_BLIND, 100, 50));
		assertEquals(Color.WHITE, StatColors.levelColor(HighlightMode.COLOUR_BLIND, 100, 100));
	}
}

package com.bettermonsterexamine;

import com.google.gson.Gson;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Locks the view-model semantics over the flat Bucket {@link MonsterData} DTO (the regression net
 * for the cutover): max-hit flagging, the affirmative poisonous check, flat-armour/XP-bonus signs,
 * and the immunity flags.
 */
public class MonsterStatsTest
{
	private static final Gson GSON = new Gson();

	private static MonsterData monster(String json)
	{
		return GSON.fromJson(json, MonsterData.class);
	}

	private static MonsterStats stats(MonsterData m)
	{
		return new MonsterStats(m, HighlightMode.STANDARD, 99, 99);
	}

	@Test
	public void maxHitsListsEachValueAndFlagsOverHp()
	{
		MonsterData m = monster("{\"max_hit\":[\"30 (Magic)\",\"28 (Ranged)\",\"121 (Dragonfire Bomb/Special)\"]}");

		List<MonsterStats.MaxHitLine> hits = stats(m).maxHits();

		assertEquals(3, hits.size());
		assertEquals("30 (Magic)", hits.get(0).text());
		assertFalse(hits.get(0).overHp());
		assertTrue("121 exceeds HP 99", hits.get(2).overHp());
	}

	@Test
	public void maxHitsFallsBackToDashWhenAbsent()
	{
		List<MonsterStats.MaxHitLine> hits = stats(monster("{}")).maxHits();

		assertEquals(1, hits.size());
		assertEquals("—", hits.get(0).text());
		assertFalse(hits.get(0).overHp());
	}

	@Test
	public void maxHitsNeverFlaggedWhenHighlightOff()
	{
		MonsterData m = monster("{\"max_hit\":[\"999\"]}");

		MonsterStats s = new MonsterStats(m, HighlightMode.OFF, 99, 99);

		assertFalse(s.maxHits().get(0).overHp());
	}

	@Test
	public void poisonousAffirmativeWithLinkIsSanitisedAndDanger()
	{
		// Bucket carries "Yes ([[venom]])"; the link is stripped and the value flagged danger.
		MonsterStats.StatField pois = stats(monster("{\"poisonous\":\"Yes ([[venom]])\"}")).poisonous();

		assertEquals("Yes (venom)", pois.value());
		assertEquals(ColourRole.DANGER, pois.role());
		assertEquals("Can poison you.", pois.tooltip());
	}

	@Test
	public void poisonousNoIsNeutral()
	{
		MonsterStats.StatField pois = stats(monster("{\"poisonous\":\"No\"}")).poisonous();

		assertEquals(ColourRole.NEUTRAL, pois.role());
		assertNull(pois.tooltip());
	}

	@Test
	public void flatArmourSignDrivesRoleAndIsAbsentWhenZero()
	{
		assertEquals(ColourRole.GOOD, stats(monster("{\"flat_armour\":-4}")).flatArmour().role());
		assertEquals("-4", stats(monster("{\"flat_armour\":-4}")).flatArmour().value());
		assertEquals(ColourRole.DANGER, stats(monster("{\"flat_armour\":10}")).flatArmour().role());
		assertNull(stats(monster("{\"flat_armour\":0}")).flatArmour());
		assertNull(stats(monster("{}")).flatArmour());
	}

	@Test
	public void xpBonusSignsAndOmitsZero()
	{
		assertEquals("+77.5%", stats(monster("{\"experience_bonus\":77.5}")).xpBonus().value());
		assertEquals(ColourRole.GOOD, stats(monster("{\"experience_bonus\":77.5}")).xpBonus().role());
		assertEquals(ColourRole.DANGER, stats(monster("{\"experience_bonus\":-50}")).xpBonus().role());
		assertNull(stats(monster("{\"experience_bonus\":0}")).xpBonus());
		assertNull(stats(monster("{}")).xpBonus());
	}

	@Test
	public void immunitiesResolveFromBucketFlags()
	{
		MonsterData m = monster("{\"cannon_immune\":\"Immune\",\"thrall_immune\":\"Not immune\","
			+ "\"burn_immune\":\"Immune (weak)\"}");

		MonsterStats s = stats(m);

		assertEquals("Immune", s.cannon().value());
		assertEquals(ColourRole.DANGER, s.cannon().role());
		assertNull(s.thrall());
		assertEquals("Immune (weak)", s.burn());
	}

	@Test
	public void slayerMonsterOnlyWhenCategoryPresent()
	{
		assertTrue(stats(monster("{\"slayer_category\":[\"Abyssal demons\"]}")).slayerMonster());
		assertFalse(stats(monster("{\"slayer_level\":85}")).slayerMonster());
		assertFalse(stats(monster("{}")).slayerMonster());
	}

	@Test
	public void slayerRequirementFlagsDangerOnlyWhenPlayerBelow()
	{
		MonsterData m = monster("{\"slayer_category\":[\"Abyssal demons\"],\"slayer_level\":85}");

		// Player at 84 can't damage it yet → danger; at 85 or with unknown level → neutral.
		assertEquals("85", new MonsterStats(m, HighlightMode.STANDARD, 99, 84).slayerRequirement().value());
		assertEquals(ColourRole.DANGER, new MonsterStats(m, HighlightMode.STANDARD, 99, 84).slayerRequirement().role());
		assertEquals(ColourRole.NEUTRAL, new MonsterStats(m, HighlightMode.STANDARD, 99, 85).slayerRequirement().role());
		assertEquals(ColourRole.NEUTRAL, new MonsterStats(m, HighlightMode.STANDARD, 99, -1).slayerRequirement().role());
	}

	@Test
	public void slayerRequirementFloorsAtOneAndStaysNeutral()
	{
		// No listed requirement: the wiki shows level 1, which every player meets.
		MonsterStats.StatField req = new MonsterStats(monster("{\"slayer_category\":[\"Zombies\"]}"),
			HighlightMode.STANDARD, 99, 1).slayerRequirement();

		assertEquals("1", req.value());
		assertEquals(ColourRole.NEUTRAL, req.role());
		assertNull(req.tooltip());
	}

	@Test
	public void slayerXpFormatsAndOmitsZero()
	{
		assertEquals("150", stats(monster("{\"slayer_experience\":150.0}")).slayerXp());
		assertEquals("18.5", stats(monster("{\"slayer_experience\":18.5}")).slayerXp());
		assertNull(stats(monster("{\"slayer_experience\":0}")).slayerXp());
		assertNull(stats(monster("{}")).slayerXp());
	}

	@Test
	public void slayerCategoriesAndMastersAsLists()
	{
		MonsterData m = monster("{\"slayer_category\":[\"Blue dragons\",\"Bosses\"],"
			+ "\"assigned_by\":[\"duradel\",\"nieve\"]}");

		assertEquals(List.of("Blue dragons", "Bosses"), stats(m).slayerCategories());
		assertEquals(List.of("duradel", "nieve"), stats(m).slayerMasters());
		assertTrue(stats(monster("{}")).slayerCategories().isEmpty());
		assertTrue(stats(monster("{}")).slayerMasters().isEmpty());
	}

	@Test
	public void slayerCategoriesCleanWikiMarkupDropJunkAndDedupe()
	{
		// Wikilinks are unwrapped, "No"/"None" placeholders dropped, and duplicates removed in order.
		MonsterData m = monster("{\"slayer_category\":[\"[[Blue dragon|Blue dragons]]\",\"No\",\"None\",\"Bosses\",\"Bosses\"]}");

		assertEquals(List.of("Blue dragons", "Bosses"), stats(m).slayerCategories());
	}

	@Test
	public void slayerMastersNormaliseCaseFoldKonarAndDropJunk()
	{
		// Bucket carries mixed casing, Konar's full name, duplicates and "No"/"None" placeholders.
		MonsterData m = monster("{\"assigned_by\":[\"Duradel\",\"duradel\",\"Konar quo Maten\",\"No\",\"None\"]}");

		assertEquals(List.of("duradel", "konar"), stats(m).slayerMasters());
	}

	@Test
	public void sizeAttributesAndCombatLevelsRender()
	{
		MonsterData m = monster("{\"size\":7,\"attribute\":[\"dragon\",\"undead\"],"
			+ "\"hitpoints\":600,\"attack_level\":255,\"strength_level\":255,\"defence_level\":150,"
			+ "\"magic_level\":255,\"ranged_level\":255}");

		MonsterStats s = stats(m);

		assertEquals("7x7, Draconic, Undead", s.sizeAttr());
		assertEquals(6, s.combatLevels().size());
		assertEquals("600", s.combatLevels().get(0).value());
		assertEquals("255", s.combatLevels().get(2).value());
		assertNull(s.poisonous());
		assertNull(s.xpBonus());
		assertNull(s.cannon());
	}

	/**
	 * Vardorvis: Bucket omits a level it can't type as an integer, so the row arrives with no
	 * strength_level at all and the level came out as a dash. The range the service recovers from
	 * the page takes its place, and the wiki's footnote explains why Defence counts *down*.
	 */
	@Test
	public void aLevelBucketDroppedRendersTheWikiRangeAndItsFootnote()
	{
		MonsterData m = monster("{\"hitpoints\":700,\"attack_level\":280,\"magic_level\":215}");
		String note = "Scales linearly with Vardorvis' remaining HP.";
		m.setLevelRanges(Map.of(
			"strength_level", new InfoboxLevels.LevelText("270-360", note),
			"defence_level", new InfoboxLevels.LevelText("215-145", note)));

		MonsterStats s = stats(m);

		assertEquals("270-360", s.combatLevels().get(2).value());
		assertEquals("215-145", s.combatLevels().get(3).value());
		assertEquals(note, s.combatLevels().get(3).tooltip());
		// Levels Bucket does carry are untouched, and a genuinely absent one still reads as a dash.
		assertEquals("280", s.combatLevels().get(1).value());
		assertEquals("—", s.combatLevels().get(5).value());
	}

	@Test
	public void defenceRollsUseTheMatchingLevel()
	{
		MonsterStats s = stats(monster("{\"defence_level\":20,\"magic_level\":1,"
			+ "\"stab_defence_bonus\":10,\"slash_defence_bonus\":20,\"crush_defence_bonus\":30,"
			+ "\"magic_defence_bonus\":50,\"light_range_defence_bonus\":0,"
			+ "\"standard_range_defence_bonus\":5,\"heavy_range_defence_bonus\":-70}"));

		assertEquals(List.of("2,146", "2,436", "2,726"), s.meleeDefenceRoll());
		assertEquals("Magic rolls off Magic level 1, not Defence", "1,140", s.magicDefenceRoll());
		assertEquals("A bonus below -64 clamps to 0", List.of("1,856", "2,001", "0"), s.rangedDefenceRoll());
	}

	@Test
	public void defenceRollsAbsentWithoutEveryInput()
	{
		MonsterStats s = stats(monster("{\"defence_level\":20,\"stab_defence_bonus\":10}"));

		assertNull(s.meleeDefenceRoll());
		assertNull(s.magicDefenceRoll());
		assertNull(s.rangedDefenceRoll());
	}

	@Test
	public void defenceRollRolesFollowTheChatRanking()
	{
		// Magic wins alone (Magic level 1); Light is the easiest free style, Standard ties with it.
		Map<DefenceRolls.Style, ColourRole> roles = stats(monster("{\"defence_level\":20,\"magic_level\":1,"
			+ "\"stab_defence_bonus\":60,\"slash_defence_bonus\":60,\"crush_defence_bonus\":60,"
			+ "\"magic_defence_bonus\":50,\"light_range_defence_bonus\":0,"
			+ "\"standard_range_defence_bonus\":5,\"heavy_range_defence_bonus\":60}")).defenceRollRoles();

		assertEquals(ColourRole.GOOD, roles.get(DefenceRolls.Style.MAGIC));
		assertEquals(ColourRole.NEXT, roles.get(DefenceRolls.Style.LIGHT));
		assertEquals("Within the tie band, so the same colour", ColourRole.NEXT, roles.get(DefenceRolls.Style.STANDARD));
		assertNull(roles.get(DefenceRolls.Style.STAB));
		assertNull(roles.get(DefenceRolls.Style.HEAVY));
	}

	@Test
	public void defenceRollRolesEmptyWhenNoStyleStandsOut()
	{
		assertTrue(stats(monster("{\"defence_level\":1,\"magic_level\":1,"
			+ "\"stab_defence_bonus\":0,\"slash_defence_bonus\":0,\"crush_defence_bonus\":0,"
			+ "\"magic_defence_bonus\":0,\"light_range_defence_bonus\":0,"
			+ "\"standard_range_defence_bonus\":0,\"heavy_range_defence_bonus\":0}")).defenceRollRoles().isEmpty());
	}
}

package com.bettermonsterexamine;

import com.google.gson.Gson;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import okhttp3.OkHttpClient;

/**
 * Dev-only: renders the in-game {@link MonsterCardOverlay} to PNGs without launching the
 * client, so we can screenshot states that aren't reachable at once in-game. It draws the
 * overlay exactly as the game would (same {@code render(Graphics2D)} path) onto a dark
 * backdrop, then tiles several captioned states side by side:
 *
 * <ul>
 *   <li>{@code overlay_vorkath_tabs.png} — every Vorkath tab (Combat / Aggro / Def / Info)
 *       at once.</li>
 *   <li>{@code overlay_blue_moon_modes.png} — Blue Moon's Info tab in Standard, Colour-blind,
 *       and highlighting-off modes.</li>
 * </ul>
 */
public class OverlayPreview
{
	/** Mirrors MonsterCardOverlay.WIDTH (package-private). */
	private static final int OVERLAY_WIDTH = 184;
	private static final int MARGIN = 18;
	private static final int GAP = 18;
	private static final int CAPTION_H = 26;
	private static final Color BACKDROP = new Color(0x2E2E2E);

	public static void main(String[] args) throws Exception
	{
		System.setProperty("java.awt.headless", "false");
		ScheduledExecutorService exec = Executors.newSingleThreadScheduledExecutor();
		OkHttpClient httpClient = new OkHttpClient();
		MonsterDataService ds = new MonsterDataService(new Gson(), httpClient, exec);
		// dataset loads on a background thread (cache, else a network fetch on first run)
		for (int i = 0; i < 600 && ds.searchNames("a", 1).isEmpty(); i++)
		{
			Thread.sleep(50);
		}

		File outDir = new File("previews");
		outDir.mkdirs();

		MonsterIcons icons = new MonsterIcons();

		// --- Vorkath: every tab at once -------------------------------------------------
		MonsterData vorkath = firstVariant(ds, "Vorkath");
		BetterMonsterExamineConfig standard = config(HighlightMode.STANDARD);
		String[] tabCaptions = {"Combat", "Aggressive", "Defensive", "Info"};
		BufferedImage[] vorkathTabs = new BufferedImage[4];
		for (int tab = 0; tab < 4; tab++)
		{
			vorkathTabs[tab] = renderOverlay(standard, icons, vorkath, tab);
		}
		writeStrip(new File(outDir, "overlay_vorkath_tabs.png"), vorkathTabs, tabCaptions);

		// --- Blue Moon: Info tab across the three highlight modes ------------------------
		MonsterData blueMoon = firstVariant(ds, "Blue Moon");
		HighlightMode[] modes = {HighlightMode.STANDARD, HighlightMode.COLOUR_BLIND, HighlightMode.OFF};
		String[] modeCaptions = {"Standard", "Colour-blind", "No highlighting"};
		BufferedImage[] modeImgs = new BufferedImage[modes.length];
		for (int i = 0; i < modes.length; i++)
		{
			modeImgs[i] = renderOverlay(config(modes[i]), icons, blueMoon, 3);
		}
		writeStrip(new File(outDir, "overlay_blue_moon_modes.png"), modeImgs, modeCaptions);

		System.out.println("OVERLAY PREVIEWS WRITTEN TO " + outDir.getAbsolutePath());
		System.exit(0); // OkHttp's dispatcher keeps non-daemon threads alive
	}

	/** Render one overlay state (monster + tab + highlight mode) to a tightly-cropped image. */
	private static BufferedImage renderOverlay(BetterMonsterExamineConfig cfg, MonsterIcons icons,
		MonsterData monster, int tab) throws Exception
	{
		// Maxed player (126 combat, 99 hp, 99 Slayer) so level colouring and the over-HP max-hit cue render.
		MonsterCardOverlay overlay = new MonsterCardOverlay(cfg, icons, () -> 126, () -> 99, () -> 99);
		overlay.setMonster(monster);
		overlay.setActiveTab(tab);

		// First pass: measure the height the overlay wants for this tab.
		BufferedImage scratch = new BufferedImage(OVERLAY_WIDTH, 2000, BufferedImage.TYPE_INT_ARGB);
		Graphics2D mg = scratch.createGraphics();
		java.awt.Dimension dim = overlay.render(mg);
		mg.dispose();
		int h = dim != null ? dim.height : 200;

		BufferedImage img = new BufferedImage(OVERLAY_WIDTH, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		overlay.render(g);
		g.dispose();
		return img;
	}

	/** Lay images out in a captioned horizontal strip on a dark backdrop, top-aligned. */
	private static void writeStrip(File out, BufferedImage[] imgs, String[] captions) throws Exception
	{
		int tallest = 0;
		int totalW = MARGIN;
		for (BufferedImage img : imgs)
		{
			tallest = Math.max(tallest, img.getHeight());
			totalW += img.getWidth() + GAP;
		}
		totalW = totalW - GAP + MARGIN;
		int totalH = MARGIN + CAPTION_H + tallest + MARGIN;

		BufferedImage canvas = new BufferedImage(totalW, totalH, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = canvas.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(BACKDROP);
		g.fillRect(0, 0, totalW, totalH);

		Font captionFont = new Font(Font.SANS_SERIF, Font.BOLD, 13);
		g.setFont(captionFont);

		int x = MARGIN;
		for (int i = 0; i < imgs.length; i++)
		{
			g.setColor(Color.WHITE);
			int cw = g.getFontMetrics().stringWidth(captions[i]);
			int cx = x + (imgs[i].getWidth() - cw) / 2;
			g.drawString(captions[i], cx, MARGIN + 16);
			g.drawImage(imgs[i], x, MARGIN + CAPTION_H, null);
			x += imgs[i].getWidth() + GAP;
		}
		g.dispose();
		ImageIO.write(canvas, "png", out);
		System.out.println("wrote " + out.getName() + " (" + totalW + "x" + totalH + ")");
	}

	private static MonsterData firstVariant(MonsterDataService ds, String name)
	{
		List<MonsterData> variants = ds.variantsForName(name);
		if (variants.isEmpty())
		{
			throw new IllegalStateException("No dataset variant for " + name);
		}
		return variants.get(0);
	}

	private static BetterMonsterExamineConfig config(HighlightMode mode)
	{
		return new BetterMonsterExamineConfig()
		{
			@Override
			public HighlightMode statHighlighting()
			{
				return mode;
			}
		};
	}
}

package com.bettermonsterexamine.loot;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Exercises {@link DropPageService#parse}, the pure HTML parse of a rendered monster page: each
 * drop-table row (item-col link · quantity · rarity cell) inherits the {@code <h3>/<h4>} section
 * heading above it, and only the Drops section (up to the next {@code <h2>}) is read. The fixture
 * mirrors the live wiki's row layout: [inventory-image][item-col][qty][table-bg rarity][ge][alch].
 */
public class DropPageServiceTest
{
	private static String row(String slug, String name, String qty, String rarityClass, String rarity)
	{
		return "<tr>"
			+ "<td class=\"inventory-image\"><img src=\"x\"></td>"
			+ "<td class=\"item-col\"><a href=\"/w/" + slug + "\">" + name + "</a></td>"
			+ "<td>" + qty + "</td>"
			+ "<td class=\"" + rarityClass + "\">" + rarity + "</td>"
			+ "<td class=\"ge-column\">9,000</td>"
			+ "<td class=\"alch-column\">1</td>"
			+ "</tr>";
	}

	private static final String HTML =
		"<p>Intro paragraph.</p>"
		+ "<h2 id=\"Drops\">Drops</h2>"
		+ "<h4 id=\"Herbs\">Herbs</h4>"
		+ "<table>"
		+ row("Grimy_ranarr_weed", "Grimy ranarr weed", "1", "table-bg-uncommon", "1/43.8")
		+ row("Grimy_avantoe", "Grimy avantoe", "1", "table-bg-uncommon", "1/80.3")
		+ "</table>"
		+ "<h4 id=\"Wilderness_Slayer_Cave_tertiary\">Wilderness Slayer Cave tertiary</h4>"
		+ "<table>"
		+ row("Larran%27s_key", "Larran's key", "1", "table-bg-rare", "1/100&#160;[d 1]")
		+ "</table>"
		+ "<h2 id=\"Store_locations\">Store locations</h2>"
		+ "<table>" + row("Should_not_appear", "x", "1", "table-bg", "1/1") + "</table>";

	@Test
	public void parsesRowsUnderTheirWikiSectionsWithinTheDropsRegion()
	{
		List<DropRow> rows = DropPageService.parse(HTML);

		assertEquals(3, rows.size());

		assertEquals("Grimy ranarr weed", rows.get(0).getItem());
		assertEquals("1", rows.get(0).getQuantity());
		assertEquals("1/43.8", rows.get(0).getRarity());
		assertEquals("Herbs", rows.get(0).getSection());

		assertEquals("Grimy avantoe", rows.get(1).getItem());
		assertEquals("Herbs", rows.get(1).getSection());

		// URL-decoded name, region section, and a footnote marker stripped off the rarity.
		assertEquals("Larran's key", rows.get(2).getItem());
		assertEquals("Wilderness Slayer Cave tertiary", rows.get(2).getSection());
		assertEquals("1/100", rows.get(2).getRarity());
	}

	@Test
	public void stopsAtTheNextH2SoNonDropTablesAreExcluded()
	{
		List<DropRow> rows = DropPageService.parse(HTML);
		assertTrue(rows.stream().noneMatch(r -> "x".equals(r.getItem())));
	}

	@Test
	public void rowsBeforeAnySectionHeadingAreSkipped()
	{
		String html = "<h2 id=\"Drops\">Drops</h2>"
			+ "<table>" + row("Orphan", "Orphan", "1", "table-bg", "1/1") + "</table>";
		assertTrue(DropPageService.parse(html).isEmpty());
	}

	@Test
	public void nullHtmlYieldsNull()
	{
		assertNull(DropPageService.parse(null));
	}

	@Test
	public void pageWithoutADropsSectionYieldsEmpty()
	{
		// No id="Drops" anchor: fail closed rather than scanning the whole page — an unrelated table
		// (here a store list under its own heading) must not be mistaken for drops.
		String html = "<h2 id=\"Store_locations\">Store locations</h2>"
			+ "<h4 id=\"Shop\">Shop</h4>"
			+ "<table>" + row("Some_item", "Some item", "1", "table-bg", "1/1") + "</table>";
		assertTrue(DropPageService.parse(html).isEmpty());
	}

	@Test
	public void combatLevelVariantsSplitDropsAcrossPerLevelSections()
	{
		// Monsters with per-level drop tables (e.g. Giant frog) have no single id="Drops"; each combat
		// level gets its own "Level N drops" <h2> with its own 100%/Tertiary/… subsections. The level
		// becomes the group so the two "100%" tables stay distinct rather than merging into one.
		String html =
			"<h2 id=\"Level_13_drops\">Level 13 drops</h2>"
			+ "<h3 id=\"100%\">100%</h3>"
			+ "<table>" + row("Big_bones", "Big bones", "1", "table-bg-always", "Always") + "</table>"
			+ "<h2 id=\"Level_99_drops\">Level 99 drops</h2>"
			+ "<h3 id=\"100%_2\">100%</h3>"
			+ "<table>" + row("Big_bones", "Big bones", "1", "table-bg-always", "Always") + "</table>"
			+ "<h3 id=\"Weapons\">Weapons</h3>"
			+ "<table>" + row("Mithril_spear", "Mithril spear", "1", "table-bg-uncommon", "1/128") + "</table>"
			+ "<h2 id=\"Changes\">Changes</h2>"
			+ "<table>" + row("Should_not_appear", "x", "1", "table-bg", "1/1") + "</table>";

		List<DropRow> rows = DropPageService.parse(html);

		assertEquals(3, rows.size());
		assertEquals("Level 13 drops", rows.get(0).getGroup());
		assertEquals("100%", rows.get(0).getSection());
		assertEquals("Level 99 drops", rows.get(1).getGroup());
		assertEquals("100%", rows.get(1).getSection());
		assertEquals("Level 99 drops", rows.get(2).getGroup());
		assertEquals("Weapons", rows.get(2).getSection());
		assertEquals("Mithril spear", rows.get(2).getItem());
		assertTrue(rows.stream().noneMatch(r -> "x".equals(r.getItem())));
	}

	@Test
	public void locationSubHeadingsBecomeGroupsSoLikeNamedTablesStayApart()
	{
		// The Cyclops shape: one "Drops" <h2>, <h3> locations, and each location's tables as <h4>s under
		// it. Both locations have a "100%" table; only the basement's "Pre-roll" holds the Dragon
		// defender. Treating <h3> and <h4> as one level merged them and implied every Cyclops drops it.
		String html =
			"<h2 id=\"Drops\">Drops</h2>"
			+ "<h3 id=\"Top\">Warriors' Guild Top Floor</h3>"
			+ "<h4 id=\"100%\">100%</h4>"
			+ "<table>" + row("Big_bones", "Big bones", "1", "table-bg-always", "Always") + "</table>"
			+ "<h4 id=\"Defenders\">Defenders</h4>"
			+ "<table>" + row("Rune_defender", "Rune defender", "1", "table-bg-rare", "2/100") + "</table>"
			+ "<h3 id=\"Basement\">Warriors' Guild Basement</h3>"
			+ "<h4 id=\"100%_2\">100%</h4>"
			+ "<table>" + row("Big_bones", "Big bones", "1", "table-bg-always", "Always") + "</table>"
			+ "<h4 id=\"Pre-roll\">Pre-roll</h4>"
			+ "<table>" + row("Dragon_defender", "Dragon defender", "1", "table-bg-rare", "1/100") + "</table>";

		List<DropRow> rows = DropPageService.parse(html);

		assertEquals(4, rows.size());
		assertEquals("Warriors' Guild Top Floor", rows.get(0).getGroup());
		assertEquals("100%", rows.get(0).getSection());
		assertEquals("Warriors' Guild Top Floor", rows.get(1).getGroup());
		assertEquals("Defenders", rows.get(1).getSection());

		assertEquals("Warriors' Guild Basement", rows.get(2).getGroup());
		assertEquals("100%", rows.get(2).getSection());

		// The one that matters: the Dragon defender is scoped to the basement, not the whole page.
		assertEquals("Dragon defender", rows.get(3).getItem());
		assertEquals("Warriors' Guild Basement", rows.get(3).getGroup());
		assertEquals("Pre-roll", rows.get(3).getSection());
	}

	@Test
	public void anH3WithNoH4UnderItIsTheSectionNotAGroup()
	{
		// The common shape — a plain "Drops" <h2> whose <h3>s are the tables themselves. These must stay
		// ungrouped, or every ordinary monster would grow a spurious band.
		String html =
			"<h2 id=\"Drops\">Drops</h2>"
			+ "<h3 id=\"Herbs\">Herbs</h3>"
			+ "<table>" + row("Grimy_guam_leaf", "Grimy guam leaf", "1", "table-bg-common", "1/30") + "</table>";

		List<DropRow> rows = DropPageService.parse(html);

		assertEquals(1, rows.size());
		assertEquals("", rows.get(0).getGroup());
		assertEquals("Herbs", rows.get(0).getSection());
	}

	@Test
	public void rarityPrefersTheWikisOneOverFormOverTheRawSourceFraction()
	{
		// The live cell shape: the span's text is the raw source fraction, data-drop-oneover is what the
		// wiki actually renders. A Cyclops' Black knife is "16/100" in the source and "1/6.25" on screen.
		String cell = "<td class=\"table-bg-green\" title=\"16%\">"
			+ "<span data-drop-percent=\"16\" data-drop-fraction=\"16/100\" data-drop-oneover=\"1/6.25\">16/100</span>"
			+ "</td>";
		String html = "<h2 id=\"Drops\">Drops</h2>"
			+ "<h3 id=\"Weapons\">Weapons</h3>"
			+ "<table><tr>"
			+ "<td class=\"inventory-image\"><img src=\"x\"></td>"
			+ "<td class=\"item-col\"><a href=\"/w/Black_knife\">Black knife</a></td>"
			+ "<td>4&#8211;13</td>"
			+ cell
			+ "</tr></table>";

		List<DropRow> rows = DropPageService.parse(html);

		assertEquals(1, rows.size());
		assertEquals("1/6.25", rows.get(0).getRarity());
	}

	@Test
	public void compoundRarityKeepsItsStructureAroundTheOneOverValues()
	{
		// A Gem drop table cell: a per-roll rate, then the combined per-kill rate after ';'. Both values
		// are spans; the separator is not. Swapping the values must leave the ';' structure intact, since
		// DropFormat reduces on it to pick the tier colour.
		String cell = "<td class=\"table-bg-rare\">"
			+ "<span data-drop-fraction=\"1/200\" data-drop-oneover=\"1/200\">1/200</span>"
			+ "<span>; </span>"
			+ "<span data-drop-fraction=\"1/101.56\" data-drop-oneover=\"1/101.56\">1/101.56</span>"
			+ "</td>";
		String html = "<h2 id=\"Drops\">Drops</h2>"
			+ "<h3 id=\"Gem_drop_table\">Gem drop table</h3>"
			+ "<table><tr>"
			+ "<td class=\"inventory-image\"><img src=\"x\"></td>"
			+ "<td class=\"item-col\"><a href=\"/w/Uncut_sapphire\">Uncut sapphire</a></td>"
			+ "<td>1</td>"
			+ cell
			+ "</tr></table>";

		List<DropRow> rows = DropPageService.parse(html);

		assertEquals(1, rows.size());
		assertEquals("1/200 ; 1/101.56", rows.get(0).getRarity());
	}

	@Test
	public void cleanStripsTagsAndUnescapesEntities()
	{
		assertEquals("A & B", DropPageService.clean("<b>A</b> &amp; B"));
		assertEquals("2–3", DropPageService.clean("2&#8211;3"));
	}
}

