package com.bettermonsterexamine.loot;

import com.google.gson.Gson;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Exercises {@link ItemIdService}'s parse of the Bucket {@code item_id} response: {@code id} arrives as
 * a string array (take the first, parse to int), the map keys on the item page name, and the first row
 * wins for a repeated name. Mirrors the wire shape of the live API.
 */
public class ItemIdServiceTest
{
	private static final Gson GSON = new Gson();

	private static ItemIdService.BucketResponse response(String json)
	{
		return GSON.fromJson(json, ItemIdService.BucketResponse.class);
	}

	@Test
	public void indexesPageNameToFirstArrayId()
	{
		// Ancient shard (an untradeable ItemManager.search misses) and Coins.
		Map<String, Integer> map = ItemIdService.index(response(
			"{\"bucket\":[{\"page_name\":\"Ancient shard\",\"id\":[\"19677\"]},"
			+ "{\"page_name\":\"Coins\",\"id\":[\"995\"]}]}"));

		assertEquals(Integer.valueOf(19677), map.get("Ancient shard"));
		assertEquals(Integer.valueOf(995), map.get("Coins"));
	}

	@Test
	public void firstRowWinsForARepeatedName()
	{
		Map<String, Integer> map = ItemIdService.index(response(
			"{\"bucket\":[{\"page_name\":\"Dragon dagger\",\"id\":[\"1215\"]},"
			+ "{\"page_name\":\"Dragon dagger\",\"id\":[\"5680\"]}]}"));

		assertEquals(Integer.valueOf(1215), map.get("Dragon dagger"));
	}

	@Test
	public void skipsRowsWithNoUsableId()
	{
		Map<String, Integer> map = ItemIdService.index(response(
			"{\"bucket\":[{\"page_name\":\"NoId\"},"
			+ "{\"page_name\":\"EmptyId\",\"id\":[]},"
			+ "{\"page_name\":\"BadId\",\"id\":[\"nope\"]},"
			+ "{\"id\":[\"1\"]}]}"));

		assertTrue(map.isEmpty());
	}

	@Test
	public void nullOrBucketlessResponseYieldsEmptyMap()
	{
		assertTrue(ItemIdService.index(null).isEmpty());
		assertTrue(ItemIdService.index(response("{\"bucketQuery\":\"…\"}")).isEmpty());
	}

	@Test
	public void parseIdToleratesWhitespaceAndRejectsNonNumbers()
	{
		assertEquals(Integer.valueOf(383), ItemIdService.parseId(" 383 "));
		assertNull(ItemIdService.parseId(null));
		assertNull(ItemIdService.parseId("12a"));
	}
}

package com.bettermonsterexamine.loot;

import java.util.ArrayList;
import java.util.List;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * Locks {@link DropTable#of}: parsed rows group by group then section in the wiki page's order
 * (first-seen), preserving row order within a section, and a blank section falls back to {@code "Other"}.
 * Crucially, like-named sections under <b>different</b> groups stay distinct rather than merging.
 */
public class DropTableTest
{
	private static DropRow row(String item, String section)
	{
		return row(item, "", section);
	}

	private static DropRow row(String item, String group, String section)
	{
		return new DropRow(item, "1", "1/128", group, section);
	}

	@Test
	public void groupsBySectionInFirstSeenOrderPreservingRowOrder()
	{
		List<DropRow> rows = new ArrayList<>();
		rows.add(row("Grimy ranarr weed", "Herbs"));
		rows.add(row("Uncut sapphire", "Gem drop table"));
		rows.add(row("Grimy avantoe", "Herbs"));
		rows.add(row("Ancient shard", "Catacombs tertiary"));

		List<DropTable.Group> groups = DropTable.of(rows).getGroups();

		// No group headings on the page: one unlabelled group holding every section.
		assertEquals(1, groups.size());
		assertEquals("", groups.get(0).getLabel());

		List<DropTable.Section> sections = groups.get(0).getSections();
		assertEquals(3, sections.size());
		// Section order follows first appearance: Herbs, then Gem drop table, then Catacombs.
		assertEquals("Herbs", sections.get(0).getLabel());
		assertEquals("Gem drop table", sections.get(1).getLabel());
		assertEquals("Catacombs tertiary", sections.get(2).getLabel());

		// Rows keep their page order within the section.
		assertEquals(2, sections.get(0).getRows().size());
		assertEquals("Grimy ranarr weed", sections.get(0).getRows().get(0).getItem());
		assertEquals("Grimy avantoe", sections.get(0).getRows().get(1).getItem());
	}

	@Test
	public void likeNamedSectionsInDifferentGroupsStayDistinct()
	{
		// The Cyclops shape: both Warriors' Guild locations have a "100%" table, but they are different
		// tables. Merging them by name is what let the basement-only Dragon defender read as a drop from
		// the top-floor cyclopes too.
		List<DropRow> rows = new ArrayList<>();
		rows.add(row("Big bones", "Warriors' Guild Top Floor", "100%"));
		rows.add(row("Rune defender", "Warriors' Guild Top Floor", "Defenders"));
		rows.add(row("Big bones", "Warriors' Guild Basement", "100%"));
		rows.add(row("Dragon defender", "Warriors' Guild Basement", "Pre-roll"));

		List<DropTable.Group> groups = DropTable.of(rows).getGroups();

		assertEquals(2, groups.size());
		assertEquals("Warriors' Guild Top Floor", groups.get(0).getLabel());
		assertEquals("Warriors' Guild Basement", groups.get(1).getLabel());

		// Each location keeps its own "100%" — one row each, not one merged section of two.
		assertEquals(2, groups.get(0).getSections().size());
		assertEquals("100%", groups.get(0).getSections().get(0).getLabel());
		assertEquals(1, groups.get(0).getSections().get(0).getRows().size());
		assertEquals("Defenders", groups.get(0).getSections().get(1).getLabel());

		assertEquals(2, groups.get(1).getSections().size());
		assertEquals("100%", groups.get(1).getSections().get(0).getLabel());
		assertEquals(1, groups.get(1).getSections().get(0).getRows().size());
		assertEquals("Pre-roll", groups.get(1).getSections().get(1).getLabel());
		assertEquals("Dragon defender", groups.get(1).getSections().get(1).getRows().get(0).getItem());
	}

	@Test
	public void blankSectionFallsBackToOther()
	{
		List<DropRow> rows = new ArrayList<>();
		rows.add(row("Coins", ""));

		List<DropTable.Group> groups = DropTable.of(rows).getGroups();

		assertEquals(1, groups.size());
		assertEquals(1, groups.get(0).getSections().size());
		assertEquals("Other", groups.get(0).getSections().get(0).getLabel());
	}
}

package com.bettermonsterexamine.loot;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * Locks {@link DropFormat}'s pure display shaping: rarity (Always / fraction / plain dash), the wiki
 * quantity string, comma-free compact coin values, and rarity-tier banding. Displayed numbers drop
 * thousands commas and en/em dashes become a plain hyphen.
 */
public class DropFormatTest
{
	private static DropRow row(String quantity, String rarity)
	{
		return new DropRow("Item", quantity, rarity, "", "Other");
	}

	@Test
	public void rarityShowsAlwaysFractionOrPlainDash()
	{
		assertEquals("Always", DropFormat.rarity(row("1", "Always")));
		assertEquals("1/128", DropFormat.rarity(row("1", "1/128")));
		// Thousands commas are dropped from the fraction.
		assertEquals("1/4096", DropFormat.rarity(row("1", "1/4,096")));
		assertEquals("-", DropFormat.rarity(row("1", "")));
		assertEquals("-", DropFormat.rarity(row("1", null)));
	}

	@Test
	public void quantityDropsCommasAndNormalisesDashes()
	{
		assertEquals("60 (noted)", DropFormat.quantity(row("60 (noted)", "1/128")));
		assertEquals("35-55", DropFormat.quantity(row(" 35–55 ", "1/128")));
		assertEquals("1000", DropFormat.quantity(row("1,000", "1/128")));
		assertEquals("", DropFormat.quantity(row("", "1/128")));
	}

	@Test
	public void priceIsCompactCommaFreeAndBlankForZero()
	{
		assertEquals("", DropFormat.price(0));
		assertEquals("450000", DropFormat.price(450_000));
		assertEquals("3.9M", DropFormat.price(3_900_000));
		assertEquals("2M", DropFormat.price(2_000_000));
		assertEquals("2.1B", DropFormat.price(2_100_000_000));
		assertEquals("5B", DropFormat.price(5_000_000_000L));
	}

	@Test
	public void tierOfMapsProbabilityToRarityBands()
	{
		// Always (100%) and unknown/unparseable rarities are common.
		assertEquals(RarityTier.COMMON, DropFormat.tierOf("Always"));
		assertEquals(RarityTier.COMMON, DropFormat.tierOf("-"));
		assertEquals(RarityTier.COMMON, DropFormat.tierOf(null));
		// 1/20 is above the 1/50 threshold -> common; 1/128 -> uncommon.
		assertEquals(RarityTier.COMMON, DropFormat.tierOf("1/20"));
		assertEquals(RarityTier.UNCOMMON, DropFormat.tierOf("1/128"));
		assertEquals(RarityTier.RARE, DropFormat.tierOf("1/1000"));
		// A leading ~ and thousands commas are tolerated; 1/13000 -> ultra rare.
		assertEquals(RarityTier.ULTRA_RARE, DropFormat.tierOf("~1/13,000"));
		// A multi-roll numerator counts: 5/128 ~ 1/26 -> common.
		assertEquals(RarityTier.COMMON, DropFormat.tierOf("5/128"));
	}

	@Test
	public void handlesMultiRollAndCombinedRarityCells()
	{
		// Vorkath's rune javelin cell (× is U+00D7): the DISPLAY keeps the full compound value
		// (commas tidied), but the tier COLOUR uses the combined per-kill rate after ';'.
		String rune = "2 × 1/24,576 ; 1/12,480";
		assertEquals("2 × 1/24576 ; 1/12480", DropFormat.rarity(new DropRow("Item", "50", rune, "", "Other")));
		assertEquals(RarityTier.ULTRA_RARE, DropFormat.tierOf(rune));

		// Adamant javelin: "N × 1/M" with no combined value -> N/M for the tier (~2/1920 = rare).
		assertEquals(RarityTier.RARE, DropFormat.tierOf("2 × 1/1,920"));
	}
}

package com.bettermonsterexamine;

import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class ExamineSummaryQueueTest
{
	@Test
	public void nativeResponseReturnsOneCompactBlockOnce()
	{
		ExamineSummaryQueue queue = new ExamineSummaryQueue();
		queue.add("Vorkath", List.of("Melee", "Ranged", "Element"), 100);

		ExamineSummaryQueue.Examined examined = queue.onNpcExamine("Vanilla examine text.", 101);

		assertEquals("Melee<br>Ranged<br>Element", examined.getBlock());
		assertEquals("Vorkath", examined.getMonsterName());
		assertNull(queue.onNpcExamine("Another native message.", 101));
	}

	@Test
	public void injectedBlockCannotConsumeTheNextNativeResponse()
	{
		ExamineSummaryQueue queue = new ExamineSummaryQueue();
		queue.add("A", List.of("<col=ff4040>Melee:</col> Crush (+0)"), 100);
		String first = queue.onNpcExamine("Vanilla A", 100).getBlock();
		queue.add("B", List.of("Summary B"), 101);

		assertNull(queue.onNpcExamine(first, 101));
		assertEquals("Summary B", queue.onNpcExamine("Vanilla B", 102).getBlock());
	}

	@Test
	public void unknownMonsterKeepsRapidResponsesAligned()
	{
		ExamineSummaryQueue queue = new ExamineSummaryQueue();
		queue.add(null, Collections.emptyList(), 100);
		queue.add("Known", List.of("Known summary"), 100);

		assertNull(queue.onNpcExamine("Unknown monster's text.", 100));
		assertEquals("Known summary", queue.onNpcExamine("Known monster's text.", 101).getBlock());
	}

	@Test
	public void clearingPendingPreventsAStaleResponse()
	{
		ExamineSummaryQueue queue = new ExamineSummaryQueue();
		queue.add("Stale", List.of("Stale summary"), 100);

		queue.clearPending();

		assertNull(queue.onNpcExamine("Later response", 101));
	}

	@Test
	public void missingResponseExpiresBeforeTheNextExamine()
	{
		ExamineSummaryQueue queue = new ExamineSummaryQueue();
		queue.add("Missing", List.of("Missing summary"), 100);

		queue.add("Current", List.of("Current summary"), 106);

		assertEquals("Current summary", queue.onNpcExamine("Current vanilla response", 106).getBlock());
	}
}

