package com.bettermonsterexamine;

import com.google.gson.Gson;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LookupHistoryTest
{
	private static final Gson GSON = new Gson();

	@Test
	public void recordMovesExistingToFrontWithoutDuplicating()
	{
		LookupHistory h = new LookupHistory();
		h.record("Goblin", "");
		h.record("Cow", "");
		h.record("Goblin", "");

		List<LookupHistory.Entry> recent = h.recent();
		assertEquals(2, recent.size());
		assertEquals("Goblin", recent.get(0).name);
		assertEquals("Cow", recent.get(1).name);
	}

	@Test
	public void recordDistinguishesVariantsByVersion()
	{
		LookupHistory h = new LookupHistory();
		h.record("Vorkath", "Post-Quest");
		h.record("Vorkath", "Dragon Slayer II");
		assertEquals(2, h.recent().size());
	}

	@Test
	public void identityIsCaseInsensitive()
	{
		LookupHistory h = new LookupHistory();
		h.record("Goblin", "");
		h.record("goblin", "");
		assertEquals(1, h.recent().size());
		assertTrue(h.isFavorite("ABYSSAL DEMON", "") == false);
	}

	@Test
	public void recentIsCappedNewestFirst()
	{
		LookupHistory h = new LookupHistory();
		for (int i = 0; i < LookupHistory.RECENT_CAP + 5; i++)
		{
			h.record("Monster " + i, "");
		}
		List<LookupHistory.Entry> recent = h.recent();
		assertEquals(LookupHistory.RECENT_CAP, recent.size());
		// Newest first: the last one recorded sits at the head.
		assertEquals("Monster " + (LookupHistory.RECENT_CAP + 4), recent.get(0).name);
		// The five oldest fell off the end.
		assertFalse(h.recent().stream().anyMatch(e -> e.name.equals("Monster 0")));
	}

	@Test
	public void favoriteToggleAndNewestPinnedFirst()
	{
		LookupHistory h = new LookupHistory();
		assertTrue(h.toggleFavorite("Cow", ""));
		assertTrue(h.toggleFavorite("Goblin", ""));
		assertTrue(h.isFavorite("Goblin", ""));

		List<LookupHistory.Entry> favs = h.favorites();
		assertEquals("Goblin", favs.get(0).name);
		assertEquals("Cow", favs.get(1).name);

		// Same call un-favorites.
		assertFalse(h.toggleFavorite("Goblin", ""));
		assertFalse(h.isFavorite("Goblin", ""));
		assertEquals(1, h.favorites().size());
	}

	@Test
	public void favoritesAreUncapped()
	{
		LookupHistory h = new LookupHistory();
		for (int i = 0; i < LookupHistory.RECENT_CAP + 10; i++)
		{
			h.toggleFavorite("Monster " + i, "");
		}
		assertEquals(LookupHistory.RECENT_CAP + 10, h.favorites().size());
	}

	@Test
	public void listsAreIndependentAndClearSeparately()
	{
		LookupHistory h = new LookupHistory();
		h.record("Goblin", "");
		h.toggleFavorite("Goblin", "");

		h.clearRecent();
		assertTrue(h.recent().isEmpty());
		assertTrue(h.isFavorite("Goblin", ""));

		h.record("Cow", "");
		h.clearFavorites();
		assertFalse(h.isFavorite("Goblin", ""));
		assertEquals(1, h.recent().size());
	}

	@Test
	public void removeAllByNameDropsFromBothLists()
	{
		LookupHistory h = new LookupHistory();
		h.record("Old Monster", "A");
		h.record("Old Monster", "B");
		h.toggleFavorite("Old Monster", "A");
		h.record("Cow", "");

		assertTrue(h.removeAllByName("old monster"));
		assertEquals(1, h.recent().size());
		assertEquals("Cow", h.recent().get(0).name);
		assertTrue(h.favorites().isEmpty());
		assertFalse(h.removeAllByName("Nonexistent"));
	}

	@Test
	public void jsonRoundTripPreservesOrderAndState()
	{
		LookupHistory h = new LookupHistory();
		h.record("Cow", "");
		h.record("Vorkath", "Post-Quest");
		h.toggleFavorite("Goblin", "");

		LookupHistory restored = LookupHistory.fromJson(GSON, h.toJson(GSON));
		assertEquals("Vorkath", restored.recent().get(0).name);
		assertEquals("Post-Quest", restored.recent().get(0).version);
		assertEquals("Cow", restored.recent().get(1).name);
		assertTrue(restored.isFavorite("Goblin", ""));
	}

	@Test
	public void garbageJsonDegradesToEmpty()
	{
		assertTrue(LookupHistory.fromJson(GSON, "not json at all {{{").recent().isEmpty());
		assertTrue(LookupHistory.fromJson(GSON, "").favorites().isEmpty());
		assertTrue(LookupHistory.fromJson(GSON, null).recent().isEmpty());
		// Valid JSON of the wrong shape parses to empty lists rather than throwing.
		assertTrue(LookupHistory.fromJson(GSON, "[1,2,3]").recent().isEmpty());
	}

	@Test
	public void fromJsonReappliesCapAndDedup()
	{
		StringBuilder sb = new StringBuilder("{\"recent\":[");
		for (int i = 0; i < LookupHistory.RECENT_CAP + 5; i++)
		{
			if (i > 0)
			{
				sb.append(',');
			}
			sb.append("{\"name\":\"M").append(i).append("\",\"version\":\"\"}");
		}
		// A duplicate of M0 and a blank-name entry that should both be filtered.
		sb.append(",{\"name\":\"M0\",\"version\":\"\"},{\"name\":\"\",\"version\":\"\"}]}");

		LookupHistory h = LookupHistory.fromJson(GSON, sb.toString());
		assertEquals(LookupHistory.RECENT_CAP, h.recent().size());
	}
}

package com.bettermonsterexamine;

import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The wikitext shapes {@link InfoboxLevels} has to recover a level from — driven by Vardorvis, the
 * one monster whose levels Bucket cannot carry (its Strength and Defence are HP-scaling ranges, so
 * the wiki's {@code tonumber()} bucket write drops them and the plugin rendered a dash).
 */
public class InfoboxLevelsTest
{
	/** Vardorvis, trimmed to the parts that matter: three versions, ranged str/def, a shared footnote. */
	private static final String VARDORVIS = String.join("\n",
		"{{Otheruses|the Deadman Mode variant|Vardorvis (Deadman)|def=no}}",
		"{{Infobox Monster",
		"|version1 = Post-quest",
		"|version2 = Awakened",
		"|version3 = Quest",
		"|max hit1 = 32-43 ([[Melee]]){{efn|name=def|Scales linearly with Vardorvis' remaining HP.}}, 35 (axes)",
		"|hitpoints1 = 700",
		"|att1 = 280",
		"|att2 = 420",
		"|att3 = 260",
		"|str1 = 270-<br />360{{efn|name=def}}",
		"|str2 = 391-<br />522{{efn|name=def}}",
		"|str3 = 210-<br />280{{efn|name=def}}",
		"|def1 = 215-<br />145{{efn|name=def}}",
		"|def2 = 268-<br />181{{efn|name=def}}",
		"|def3 = 180-<br />130{{efn|name=def}}",
		"|mage1 = 215",
		"|range = 0",
		"}}");

	@Test
	public void recoversRangedLevelsPerVersion()
	{
		Map<String, Map<String, InfoboxLevels.LevelText>> levels = InfoboxLevels.parse(VARDORVIS);

		assertEquals("270-360", levels.get("post-quest").get("strength_level").getValue());
		assertEquals("215-145", levels.get("post-quest").get("defence_level").getValue());
		assertEquals("391-522", levels.get("awakened").get("strength_level").getValue());
		assertEquals("268-181", levels.get("awakened").get("defence_level").getValue());
		assertEquals("210-280", levels.get("quest").get("strength_level").getValue());
		assertEquals("180-130", levels.get("quest").get("defence_level").getValue());
	}

	/** The wiki's own footnote is what makes a Defence counting *down* legible, so it must come through. */
	@Test
	public void carriesTheFootnoteExplainingTheRange()
	{
		Map<String, Map<String, InfoboxLevels.LevelText>> levels = InfoboxLevels.parse(VARDORVIS);

		assertEquals("Scales linearly with Vardorvis' remaining HP.",
			levels.get("post-quest").get("defence_level").getNote());
		// The note is defined once (on max hit) and referenced by name from every level.
		assertEquals("Scales linearly with Vardorvis' remaining HP.",
			levels.get("awakened").get("strength_level").getNote());
	}

	/** Levels Bucket already carries are not worth recovering — only the ones it dropped. */
	@Test
	public void skipsPlainIntegerLevels()
	{
		Map<String, Map<String, InfoboxLevels.LevelText>> levels = InfoboxLevels.parse(VARDORVIS);

		assertNull(levels.get("post-quest").get("attack_level"));
		assertNull(levels.get("post-quest").get("magic_level"));
		// "|range = 0" is a real 0 the Bucket row carries, not a hole.
		assertNull(levels.get("post-quest").get("ranged_level"));
	}

	/**
	 * A blank level is genuinely unknown on the wiki (Whale, Guard, Reef snake — most of what Bucket
	 * omits). Those must keep rendering as a dash rather than as an empty value.
	 */
	@Test
	public void ignoresBlankLevels()
	{
		Map<String, Map<String, InfoboxLevels.LevelText>> levels = InfoboxLevels.parse(String.join("\n",
			"{{Infobox Monster",
			"|att = 50",
			"|str =",
			"|def = 100",
			"}}"));

		assertNull(levels.getOrDefault("", java.util.Collections.emptyMap()).get("strength_level"));
	}

	/** A page with no versions keys its levels under the single unnamed form. */
	@Test
	public void handlesAnUnversionedInfobox()
	{
		Map<String, Map<String, InfoboxLevels.LevelText>> levels = InfoboxLevels.parse(String.join("\n",
			"{{Infobox Monster",
			"|str = 100-200",
			"}}"));

		assertEquals("100-200", levels.get("").get("strength_level").getValue());
	}

	/** An en/em dash reads badly at panel size, so a range is normalised to a plain hyphen. */
	@Test
	public void normalisesDashesAndDropsThousandsCommas()
	{
		Map<String, Map<String, InfoboxLevels.LevelText>> levels = InfoboxLevels.parse(String.join("\n",
			"{{Infobox Monster",
			"|str = 1,200—1,500",
			"}}"));

		assertEquals("1200-1500", levels.get("").get("strength_level").getValue());
	}

	/** Only the infobox's own parameters count — {{Otheruses|…|def=no}} above it is not a Defence. */
	@Test
	public void ignoresParametersOutsideTheInfobox()
	{
		Map<String, Map<String, InfoboxLevels.LevelText>> levels = InfoboxLevels.parse(VARDORVIS);

		for (Map<String, InfoboxLevels.LevelText> version : levels.values())
		{
			InfoboxLevels.LevelText def = version.get("defence_level");
			assertTrue("def picked up {{Otheruses|def=no}}", def == null || !def.getValue().equals("no"));
		}
	}

	@Test
	public void toleratesAPageWithNoInfobox()
	{
		assertTrue(InfoboxLevels.parse("Just prose.").isEmpty());
		assertTrue(InfoboxLevels.parse(null).isEmpty());
	}
}

package com.bettermonsterexamine;

import com.google.gson.Gson;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ExamineSummaryTest
{
	private static final Gson GSON = new Gson();

	private static MonsterData monster(String json)
	{
		return GSON.fromJson(json, MonsterData.class);
	}

	/** Bonuses in the standard palette, which is all the Weakness line tests need. */
	private static List<String> format(MonsterData m, ExamineSummaryMode mode, boolean transparentChat)
	{
		return ExamineSummary.format(m, mode, transparentChat, false, HighlightMode.STANDARD);
	}

	private static String defences(int defence, int magic, int stab, int slash, int crush,
		int standard, int heavy, int light, int magicBonus)
	{
		return defences(defence, magic, stab, slash, crush, standard, heavy, light, magicBonus, null);
	}

	private static String defences(int defence, int magic, int stab, int slash, int crush,
		int standard, int heavy, int light, int magicBonus, String element)
	{
		return "{\"defence_level\":" + defence + ",\"magic_level\":" + magic
			+ ",\"stab_defence_bonus\":" + stab + ",\"slash_defence_bonus\":" + slash
			+ ",\"crush_defence_bonus\":" + crush + ",\"standard_range_defence_bonus\":" + standard
			+ ",\"heavy_range_defence_bonus\":" + heavy + ",\"light_range_defence_bonus\":" + light
			+ ",\"magic_defence_bonus\":" + magicBonus
			+ (element == null ? "" : ",\"elemental_weakness\":\"" + element + "\",\"elemental_weakness_percent\":50")
			+ "}";
	}

	private static final String ICE_GIANT = "{\"name\":\"Ice giant\",\"defence_level\":40,"
		+ "\"magic_level\":1,\"stab_defence_bonus\":20,"
		+ "\"slash_defence_bonus\":20,\"crush_defence_bonus\":0,\"standard_range_defence_bonus\":40,"
		+ "\"heavy_range_defence_bonus\":20,\"light_range_defence_bonus\":60,"
		+ "\"magic_defence_bonus\":0,"
		+ "\"elemental_weakness\":\"fire\",\"elemental_weakness_percent\":50}";

	@Test
	public void noMonsterOrNoModeProducesNoSummary()
	{
		assertTrue(format(null, ExamineSummaryMode.ALL_DEFENCES, false).isEmpty());
		assertTrue(format(monster("{}"), null, false).isEmpty());
	}

	@Test
	public void allDefencesColoursWhatTheWeaknessLineWouldName()
	{
		// Magic wins alone, so it's green and the easiest free style (Crush) yellow; the element
		// rides beside magic, so the Weakness line has nothing left to say and is dropped.
		assertEquals(List.of(
			"Stab +20  Slash +20  <col=7a5c00>Crush +0</col>",
			"<col=006600>Magic +0</col> (<col=b22800>Fire 50%</col>)  Light +60  Std +40  Heavy +20"),
			format(monster(ICE_GIANT), ExamineSummaryMode.ALL_DEFENCES, false));
	}

	@Test
	public void allDefencesShowsRollsWhenAsked()
	{
		assertEquals(List.of(
			"Stab 4,116  Slash 4,116  <col=7a5c00>Crush 3,136</col>",
			"<col=006600>Magic 640</col> (<col=b22800>Fire 50%</col>)  Light 6,076  Std 5,096  Heavy 4,116"),
			ExamineSummary.format(monster(ICE_GIANT), ExamineSummaryMode.ALL_DEFENCES, false, true,
				HighlightMode.STANDARD));
	}

	@Test
	public void allDefencesHighlightsFollowThePaletteAndChatbox()
	{
		List<String> cb = ExamineSummary.format(monster(ICE_GIANT), ExamineSummaryMode.ALL_DEFENCES, true, false,
			HighlightMode.COLOUR_BLIND);
		assertTrue(cb.get(0).endsWith("<col=f0e442>Crush +0</col>"));
		assertTrue(cb.get(1).startsWith("<col=56b4e9>Magic +0</col>"));

		List<String> off = ExamineSummary.format(monster(ICE_GIANT), ExamineSummaryMode.ALL_DEFENCES, false, false,
			HighlightMode.OFF);
		assertEquals("Stab +20  Slash +20  Crush +0", off.get(0));
		assertTrue("The element keeps its own colour", off.get(1).startsWith("Magic +0 (<col=b22800>Fire 50%</col>)"));
	}

	@Test
	public void allDefencesFallsBackToBonusesWithoutEveryRollInput()
	{
		MonsterData m = monster("{\"stab_defence_bonus\":5}");

		assertEquals("Stab +5  Slash +0  Crush +0",
			ExamineSummary.format(m, ExamineSummaryMode.ALL_DEFENCES, false, true, HighlightMode.STANDARD).get(0));
	}

	@Test
	public void summaryNoLongerCarriesItsOwnNameHeader()
	{
		// The name moved onto the game's own Examine line, so the block starts with the stats.
		List<String> lines = format(monster(ICE_GIANT), ExamineSummaryMode.WEAKNESSES, false);

		assertEquals(1, lines.size());
		assertTrue(lines.get(0).startsWith("Weakness:"));
	}

	/** Magic wins, then the comma names the best style that costs no runes. */
	@Test
	public void magicIsFollowedByTheBestFreeStyle()
	{
		assertEquals(List.of("Weakness: Magic (<col=b22800>Fire</col>), Crush"),
			format(monster(ICE_GIANT), ExamineSummaryMode.WEAKNESSES, false));
	}

	/** The transparent chatbox is dark, so the element takes its lighter shade there. */
	@Test
	public void theElementShadeFollowsTheChatbox()
	{
		assertEquals(List.of("Weakness: Magic (<col=ff7a3d>Fire</col>), Crush"),
			format(monster(ICE_GIANT), ExamineSummaryMode.WEAKNESSES, true));
	}

	/** Each element has its own colour, rather than one colour standing in for all four. */
	@Test
	public void elementsAreColouredApart()
	{
		String water = defences(120, 1, 20, 10, 10, -10, -10, -10, 50, "water");
		String earth = defences(120, 1, 20, 10, 10, -10, -10, -10, 50, "earth");

		assertEquals(List.of("Weakness: Magic (<col=0038b8>Water</col>), Ranged"),
			format(monster(water), ExamineSummaryMode.WEAKNESSES, false));
		assertEquals(List.of("Weakness: Magic (<col=6e3b0e>Earth</col>), Ranged"),
			format(monster(earth), ExamineSummaryMode.WEAKNESSES, false));
	}

	/** When every free style is even there is no second answer to give. */
	@Test
	public void magicStandsAloneWhenFreeStylesAreEven()
	{
		MonsterData m = monster(defences(80, 1, 0, 0, 0, 0, 0, 0, 0));

		assertEquals(List.of("Weakness: Magic"), format(m, ExamineSummaryMode.WEAKNESSES, false));
	}

	/**
	 * A melee answer carries no elemental weakness: the element is a damage multiplier, and
	 * printing it beside a melee recommendation reads as an endorsement of casting.
	 */
	@Test
	public void aNonMagicWinnerDropsTheElement()
	{
		MonsterData m = monster(defences(100, 100, -15, -15, -15, 60, 60, 60, 100, "air"));

		List<String> lines = format(m, ExamineSummaryMode.WEAKNESSES, false);

		assertEquals(List.of("Weakness: Melee"), lines);
		assertFalse(lines.get(0).contains("Air"));
	}

	/** Styles within the tie factor are joined with a slash, and the element still stays off. */
	@Test
	public void aNarrowLeadIsATie()
	{
		MonsterData m = monster(defences(120, 100, 10, 20, 40, 60, 60, 60, 100, "air"));

		assertEquals(List.of("Weakness: Stab/Slash"), format(m, ExamineSummaryMode.WEAKNESSES, false));
	}

	@Test
	public void evenStylesSayNone()
	{
		MonsterData m = monster(defences(50, 50, 0, 0, 0, 0, 0, 0, 0));

		assertEquals(List.of("Weakness: none"), format(m, ExamineSummaryMode.WEAKNESSES, false));
	}

	/** Every roll at zero means nothing can miss, the opposite of "none". */
	@Test
	public void unmissableSaysAnything()
	{
		MonsterData m = monster(defences(0, 1, -100, -100, -100, -100, -100, -100, -100));

		assertEquals(List.of("Weakness: anything"), format(m, ExamineSummaryMode.WEAKNESSES, false));
	}

	/** No defensive data drops the line rather than printing a seven-way tie of zeroes. */
	@Test
	public void aBlankRowGetsNoWeaknessLine()
	{
		List<String> lines = format(monster("{}"), ExamineSummaryMode.ALL_DEFENCES, false);

		assertEquals(List.of("Stab +0  Slash +0  Crush +0", "Magic +0  Light +0  Std +0  Heavy +0"), lines);
		assertTrue(format(monster("{}"), ExamineSummaryMode.WEAKNESSES, false).isEmpty());
	}

	@Test
	public void chatNameEscapesFormattingAndFlattensNewlines()
	{
		assertEquals("Boss <lt>col=ff0000<gt><at>red<lt>/col<gt> form",
			ExamineSummary.chatName("Boss <col=ff0000>@red</col>\nform"));
	}

	@Test
	public void chatNameRejectsWhatCannotBeShown()
	{
		assertNull(ExamineSummary.chatName(null));
		assertNull(ExamineSummary.chatName("   "));
	}

	@Test
	public void modeLabelsAreUserFacing()
	{
		assertEquals("Weaknesses only", ExamineSummaryMode.WEAKNESSES.toString());
		assertEquals("All defences", ExamineSummaryMode.ALL_DEFENCES.toString());
	}
}

package com.bettermonsterexamine;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Golden cases taken from a full run of the cached bestiary, one per band and one per trap.
 */
public class DefenceRollsTest
{
	private static final Gson GSON = new Gson();

	private static MonsterData monster(String json)
	{
		return GSON.fromJson(json, MonsterData.class);
	}

	private static String bonuses(int stab, int slash, int crush, int std, int heavy, int light, int magic)
	{
		return "\"stab_defence_bonus\":" + stab
			+ ",\"slash_defence_bonus\":" + slash
			+ ",\"crush_defence_bonus\":" + crush
			+ ",\"standard_range_defence_bonus\":" + std
			+ ",\"heavy_range_defence_bonus\":" + heavy
			+ ",\"light_range_defence_bonus\":" + light
			+ ",\"magic_defence_bonus\":" + magic;
	}

	/** Fire giant: the highest defence bonus on it is magic, yet magic is by far the easiest to land. */
	@Test
	public void magicLevelBeatsMagicBonus()
	{
		MonsterData m = monster("{\"defence_level\":120,\"magic_level\":1,"
			+ bonuses(20, 10, 10, -10, -10, -10, 50) + "}");

		DefenceRolls.Result r = DefenceRolls.of(m);

		assertEquals(DefenceRolls.Band.RANKED, r.getBand());
		assertEquals("Magic", DefenceRolls.describe(r.getWeakest()));
		assertEquals("Ranged", DefenceRolls.describe(r.getFreeWeakest()));
	}

	@Test
	public void rollsUseTheLevelOfTheirOwnFamily()
	{
		MonsterData m = monster("{\"defence_level\":120,\"magic_level\":1,"
			+ bonuses(20, 10, 10, -10, -10, -10, 50) + "}");

		Map<DefenceRolls.Style, Integer> rolls = DefenceRolls.rolls(m);

		assertEquals(129 * 74, (int) rolls.get(DefenceRolls.Style.SLASH));
		assertEquals(10 * 114, (int) rolls.get(DefenceRolls.Style.MAGIC));
	}

	/** Shellbane gryphon: slash is only 1.14x harder than stab, so the two are named as a tie. */
	@Test
	public void stylesWithinTheTieFactorShareTheAnswer()
	{
		MonsterData m = monster("{\"defence_level\":120,\"magic_level\":100,"
			+ bonuses(10, 20, 40, 60, 60, 60, 100) + "}");

		assertEquals("Stab/Slash", DefenceRolls.describe(DefenceRolls.of(m).getWeakest()));
	}

	/** A free style that wins outright needs no second answer. */
	@Test
	public void aFreeWinnerHasNoFreeFallback()
	{
		MonsterData m = monster("{\"defence_level\":100,\"magic_level\":100,"
			+ bonuses(-15, -15, -15, 60, 60, 60, 100) + "}");

		DefenceRolls.Result r = DefenceRolls.of(m);

		assertEquals("Melee", DefenceRolls.describe(r.getWeakest()));
		assertTrue(r.getFreeWeakest().isEmpty());
	}

	/** Greater demon: when every free style is equally hard, naming one would be arbitrary. */
	@Test
	public void evenFreeStylesLeaveTheFallbackEmpty()
	{
		MonsterData m = monster("{\"defence_level\":80,\"magic_level\":1,"
			+ bonuses(0, 0, 0, 0, 0, 0, 0) + "}");

		DefenceRolls.Result r = DefenceRolls.of(m);

		assertEquals(List.of(DefenceRolls.Style.MAGIC), r.getWeakest());
		assertTrue(r.getFreeWeakest().isEmpty());
	}

	/** Ice demon rolls magic off its Defence level, not its Magic level of 390. */
	@Test
	public void theMagicExceptionListApplies()
	{
		String stats = "\"defence_level\":160,\"magic_level\":390," + bonuses(50, 50, 50, 50, 50, 50, 20);
		MonsterData excepted = monster("{\"page_name\":\"Ice demon\"," + stats + "}");
		MonsterData plain = monster("{\"page_name\":\"Ice giant\"," + stats + "}");

		assertEquals("Magic", DefenceRolls.describe(DefenceRolls.of(excepted).getWeakest()));
		// Without the exception the same numbers bury magic behind every other style.
		assertFalse(DefenceRolls.of(plain).getWeakest().contains(DefenceRolls.Style.MAGIC));
	}

	/** Egg (Tombs of Amascut): every bonus is -100, so every roll clamps to zero. */
	@Test
	public void aBonusBelowMinusSixtyFourCannotInvertTheRanking()
	{
		MonsterData m = monster("{\"defence_level\":0,\"magic_level\":1,"
			+ bonuses(-100, -100, -100, -100, -100, -100, -100) + "}");

		assertEquals(DefenceRolls.Band.CANNOT_MISS, DefenceRolls.of(m).getBand());
	}

	@Test
	public void everyStyleEqualIsEven()
	{
		MonsterData m = monster("{\"defence_level\":50,\"magic_level\":50,"
			+ bonuses(0, 0, 0, 0, 0, 0, 0) + "}");

		assertEquals(DefenceRolls.Band.EVEN, DefenceRolls.of(m).getBand());
	}

	/** A blank row must not read as a seven-way tie of zeroes. */
	@Test
	public void missingBonusesAreNotZero()
	{
		assertEquals(DefenceRolls.Band.NO_DATA, DefenceRolls.of(monster("{}")).getBand());
		assertEquals(DefenceRolls.Band.NO_DATA, DefenceRolls.of(null).getBand());
	}

	/** A Defence level of 0 is real (Egg), so it must not be mistaken for a missing one. */
	@Test
	public void zeroLevelsAreStillData()
	{
		MonsterData m = monster("{\"defence_level\":0,\"magic_level\":0,"
			+ bonuses(0, 0, 0, 0, 0, 0, 0) + "}");

		assertTrue(DefenceRolls.of(m).getBand() != DefenceRolls.Band.NO_DATA);
	}

	@Test
	public void wholeFamiliesCollapseToOneLabel()
	{
		List<DefenceRolls.Style> free = new ArrayList<>(DefenceRolls.allStyles());
		free.remove(DefenceRolls.Style.MAGIC);

		assertEquals("Melee/Ranged", DefenceRolls.describe(free));
	}

	@Test
	public void aPartialFamilyIsNamedStyleByStyle()
	{
		MonsterData m = monster("{\"defence_level\":100,\"magic_level\":100,"
			+ bonuses(0, 0, 50, 50, 50, 50, 50) + "}");

		assertEquals("Stab/Slash", DefenceRolls.describe(DefenceRolls.of(m).getWeakest()));
	}

	@Test
	public void theElementIsCapitalisedAndOptional()
	{
		String stats = "\"defence_level\":120,\"magic_level\":1," + bonuses(20, 10, 10, -10, -10, -10, 50);

		assertEquals("Water", DefenceRolls.of(monster("{" + stats
			+ ",\"elemental_weakness\":\"water\",\"elemental_weakness_percent\":100}")).getElement());
		assertNull(DefenceRolls.of(monster("{" + stats + "}")).getElement());
	}
}

