package com.bettermonsterexamine;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Pure model behind the side panel's Recent + Favorites lists. Holds two ordered lists of
 * {@link Entry} (monster base name + variant version), with dedup/move-to-front, a fixed Recent
 * cap, favourite toggling (newest-pinned first), and lenient JSON (de)serialisation for
 * {@code ConfigManager} persistence. Deliberately Swing-free so it can be unit-tested like
 * {@link MonsterDataService#matchNames}.
 */
class LookupHistory
{
	/** Newest-first Recent cap; older entries fall off the end. */
	static final int RECENT_CAP = 15;

	/**
	 * A looked-up monster: base name + variant version. {@code version} is empty for single-form
	 * monsters. Identity is name + version, compared case-insensitively so a lookup recorded from
	 * the panel, the overlay, or the dataset all dedup to one entry.
	 */
	static final class Entry
	{
		final String name;
		final String version;

		Entry(String name, String version)
		{
			this.name = name == null ? "" : name;
			this.version = version == null ? "" : version;
		}

		boolean matches(String otherName, String otherVersion)
		{
			return name.equalsIgnoreCase(otherName == null ? "" : otherName)
				&& version.equalsIgnoreCase(otherVersion == null ? "" : otherVersion);
		}
	}

	private final List<Entry> recent = new ArrayList<>();
	private final List<Entry> favorites = new ArrayList<>();

	List<Entry> recent()
	{
		return Collections.unmodifiableList(recent);
	}

	List<Entry> favorites()
	{
		return Collections.unmodifiableList(favorites);
	}

	/** Record a lookup: dedup + move-to-front in Recent, capped at {@link #RECENT_CAP}. */
	void record(String name, String version)
	{
		if (name == null || name.isEmpty())
		{
			return;
		}
		remove(recent, name, version);
		recent.add(0, new Entry(name, version));
		while (recent.size() > RECENT_CAP)
		{
			recent.remove(recent.size() - 1);
		}
	}

	boolean isFavorite(String name, String version)
	{
		return indexOf(favorites, name, version) >= 0;
	}

	/** Toggle favourite state; a newly-pinned entry goes to the front. Returns the new state. */
	boolean toggleFavorite(String name, String version)
	{
		if (name == null || name.isEmpty())
		{
			return false;
		}
		int i = indexOf(favorites, name, version);
		if (i >= 0)
		{
			favorites.remove(i);
			return false;
		}
		favorites.add(0, new Entry(name, version));
		return true;
	}

	void clearRecent()
	{
		recent.clear();
	}

	void clearFavorites()
	{
		favorites.clear();
	}

	/** Drop every entry (Recent and Favorites) for a name that no longer resolves. */
	boolean removeAllByName(String name)
	{
		if (name == null)
		{
			return false;
		}
		boolean changed = recent.removeIf(e -> e.name.equalsIgnoreCase(name));
		changed |= favorites.removeIf(e -> e.name.equalsIgnoreCase(name));
		return changed;
	}

	private static void remove(List<Entry> list, String name, String version)
	{
		int i = indexOf(list, name, version);
		if (i >= 0)
		{
			list.remove(i);
		}
	}

	private static int indexOf(List<Entry> list, String name, String version)
	{
		for (int i = 0; i < list.size(); i++)
		{
			if (list.get(i).matches(name, version))
			{
				return i;
			}
		}
		return -1;
	}

	// ---------------------------------------------------------- persistence

	/**
	 * Serialise both lists to a compact JSON string for {@code ConfigManager}. Takes the client's
	 * injected {@code Gson} — the plugin hub rejects fresh {@code new Gson()} instances.
	 */
	String toJson(Gson gson)
	{
		return gson.toJson(new Persisted(recent, favorites));
	}

	/**
	 * Parse from a {@code ConfigManager} string, using the client's injected {@code Gson}. Malformed,
	 * legacy, or empty input degrades to empty lists rather than throwing — this runs during panel
	 * construction on the EDT.
	 */
	static LookupHistory fromJson(Gson gson, String json)
	{
		LookupHistory h = new LookupHistory();
		if (json == null || json.trim().isEmpty())
		{
			return h;
		}
		try
		{
			Persisted p = gson.fromJson(json, Persisted.class);
			if (p != null)
			{
				copyValid(p.recent, h.recent, RECENT_CAP);
				copyValid(p.favorites, h.favorites, Integer.MAX_VALUE);
			}
		}
		catch (JsonSyntaxException e)
		{
			// Garbage in -> empty out; never propagate onto the EDT.
			h.recent.clear();
			h.favorites.clear();
		}
		return h;
	}

	/** Copy parsed entries, skipping blanks/dupes and normalising via the constructor, up to a cap. */
	private static void copyValid(List<Entry> src, List<Entry> dst, int cap)
	{
		if (src == null)
		{
			return;
		}
		for (Entry e : src)
		{
			if (e == null || e.name == null || e.name.isEmpty())
			{
				continue;
			}
			if (indexOf(dst, e.name, e.version) >= 0)
			{
				continue;
			}
			dst.add(new Entry(e.name, e.version));
			if (dst.size() >= cap)
			{
				break;
			}
		}
	}

	/** Gson DTO mirror of the two lists. */
	private static final class Persisted
	{
		private final List<Entry> recent;
		private final List<Entry> favorites;

		Persisted(List<Entry> recent, List<Entry> favorites)
		{
			this.recent = recent;
			this.favorites = favorites;
		}
	}
}

package com.bettermonsterexamine;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Provides the monster dataset, indexed by NPC id and by name. The whole bestiary is fetched in a
 * single uncapped query from the OSRS Wiki <b>Bucket</b> API ({@code infobox_monster}) — the wiki's
 * official structured-data store — and cached under {@code .runelite/better-monster-examine/} so
 * subsequent launches work offline; it refreshes in the background once the cache ages past
 * {@link #MAX_AGE}. All loading happens off the client thread, and accessors safely return empty
 * until it lands.
 */
@Slf4j
@Singleton
public class MonsterDataService
{
	private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT = "better-monster-examine (RuneLite plugin)";
	private static final File CACHE_DIR = new File(RuneLite.RUNELITE_DIR, "better-monster-examine");
	private static final File CACHE_FILE = new File(CACHE_DIR, "bucket-monsters.json");
	private static final File LEVELS_CACHE_FILE = new File(CACHE_DIR, "level-ranges.json");
	private static final Duration MAX_AGE = Duration.ofDays(7);
	/** MediaWiki caps a multi-title query at 50 pages. */
	private static final int TITLES_PER_QUERY = 50;
	private static final Type LEVEL_RANGES_TYPE =
		new TypeToken<Map<String, Map<String, InfoboxLevels.LevelText>>>()
		{
		}.getType();

	/** Bucket fields fetched for every monster — the rendered set plus extras captured for later use. */
	private static final String[] FIELDS = {
		"name", "id", "page_name", "version_anchor", "default_version", "combat_level", "hitpoints", "size",
		"attack_level", "strength_level", "defence_level", "magic_level", "ranged_level",
		"attack_bonus", "strength_bonus", "magic_attack_bonus", "magic_damage_bonus",
		"range_attack_bonus", "range_strength_bonus",
		"stab_attack_bonus", "slash_attack_bonus", "crush_attack_bonus",
		"stab_defence_bonus", "slash_defence_bonus", "crush_defence_bonus", "magic_defence_bonus",
		"range_defence_bonus", "light_range_defence_bonus", "standard_range_defence_bonus",
		"heavy_range_defence_bonus", "flat_armour",
		"attack_style", "attack_speed", "max_hit", "experience_bonus",
		"attribute", "elemental_weakness", "elemental_weakness_percent",
		"examine", "poisonous",
		"cannon_immune", "thrall_immune", "burn_immune", "freeze_resistance",
		"slayer_level", "slayer_experience", "slayer_category", "assigned_by", "uses_skill",
		"image", "league_region", "release_date", "is_members_only",
	};

	private final Gson gson;
	private final OkHttpClient http;

	private volatile Map<Integer, MonsterData> byId = Collections.emptyMap();
	// lower-case base name -> variants, insertion-ordered
	private volatile Map<String, List<MonsterData>> byName = Collections.emptyMap();
	// "name|version anchor" (lower-case) -> the levels Bucket dropped for that variant; see gapFill.
	private volatile Map<String, Map<String, InfoboxLevels.LevelText>> levelRanges = Collections.emptyMap();

	@Inject
	MonsterDataService(Gson gson, OkHttpClient http, ScheduledExecutorService executor)
	{
		this.gson = gson;
		this.http = http;
		executor.execute(this::init);
	}

	/** The wrapper the Bucket API returns: {@code {"bucketQuery": …, "bucket": [ rows ]}}. */
	private static final class BucketResponse
	{
		private List<MonsterData> bucket;
	}

	private void init()
	{
		deleteLegacyCache();
		// Load the gap-filled levels first, so the very first index() already applies them.
		readLevelRanges();

		boolean haveCache = false;
		List<MonsterData> rows = null;
		if (CACHE_FILE.isFile())
		{
			try (Reader r = Files.newBufferedReader(CACHE_FILE.toPath(), StandardCharsets.UTF_8))
			{
				BucketResponse cached = gson.fromJson(r, BucketResponse.class);
				// Only trust a cache that yielded rows; a truncated/empty/old-format file falls
				// through to a fetch rather than masquerading as a valid (and "fresh") dataset.
				if (cached != null && cached.bucket != null && !cached.bucket.isEmpty())
				{
					rows = cached.bucket;
					index(rows);
					haveCache = true;
					log.info("Loaded monster dataset from cache ({} entries)", byId.size());
				}
			}
			catch (Exception e)
			{
				log.debug("Failed to read cached monster dataset", e);
			}
		}

		// Use the cache immediately if it's recent; otherwise (missing or stale) pull a fresh
		// copy. A stale cache still serves until the refresh lands, so we stay usable offline.
		// A cache written before a field was added to FIELDS is stale whatever its age: it parses
		// fine but silently lacks the data the current build reasons over, so the feature that
		// needed the field looks broken until MAX_AGE elapses (#60).
		boolean fresh = haveCache
			&& (System.currentTimeMillis() - CACHE_FILE.lastModified()) < MAX_AGE.toMillis()
			&& hasCurrentFields(rows);
		if (fresh)
		{
			log.debug("Cache hit. Skipping monster data fetch.");
			// A fresh dataset cached before this feature existed has no level ranges beside it;
			// fill them without re-pulling the whole bestiary.
			if (levelRanges.isEmpty())
			{
				gapFill(rows);
			}
		}
		else
		{
			log.debug("{} Fetching monster data.", haveCache ? "Cache stale." : "Cache miss.");
			fetch();
		}
	}

	/**
	 * True when cached rows carry the fields this build expects. Only {@code page_name} is checked:
	 * every Bucket row has a source page, so its total absence means the cache predates the field
	 * being selected. Cheap and self-maintaining — a later field addition just moves this probe.
	 */
	static boolean hasCurrentFields(List<MonsterData> rows)
	{
		return rows != null && rows.stream().anyMatch(m -> m != null && m.getPageName() != null);
	}

	/** Remove the pre-Bucket Weirdgloop dataset left in every upgraded user's cache dir. */
	private static void deleteLegacyCache()
	{
		try
		{
			Files.deleteIfExists(new File(CACHE_DIR, "monsters.json").toPath());
		}
		catch (IOException e)
		{
			log.debug("Failed to remove the legacy monsters.json cache", e);
		}
	}

	private void fetch()
	{
		HttpUrl url = HttpUrl.get(API_URL).newBuilder()
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", buildQuery())
			.build();
		Request req = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Monster dataset fetch failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					if (!res.isSuccessful() || res.body() == null)
					{
						return;
					}
					String json = res.body().string();
					BucketResponse parsed = gson.fromJson(json, BucketResponse.class);
					if (parsed == null || parsed.bucket == null || parsed.bucket.isEmpty())
					{
						log.debug("Monster dataset response carried no rows");
						return;
					}
					// Parse (and publish) before caching so a corrupt download never poisons the cache.
					index(parsed.bucket);
					writeCache(json);
					log.info("Fetched and cached monster dataset ({} entries)", byId.size());
					// The dataset is usable now (the gaps read as a dash, as they always did); the
					// handful of levels Bucket can't carry fill in behind it.
					gapFill(parsed.bucket);
				}
				catch (Exception e)
				{
					log.debug("Monster dataset fetch/parse failed", e);
				}
			}
		});
	}

	/** Build the uncapped {@code select(…).run()} Bucket query over {@code infobox_monster}. */
	private static String buildQuery()
	{
		StringBuilder sel = new StringBuilder();
		for (String f : FIELDS)
		{
			if (sel.length() > 0)
			{
				sel.append(',');
			}
			sel.append('\'').append(f).append('\'');
		}
		return "bucket('infobox_monster').select(" + sel + ").limit(5000).run()";
	}

	private static void writeCache(String json)
	{
		try
		{
			Files.createDirectories(CACHE_DIR.toPath());
			Files.write(CACHE_FILE.toPath(), json.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.debug("Failed to cache monster dataset", e);
		}
	}

	// ---- level gap-fill ------------------------------------------------------
	//
	// Bucket types the five combat levels as INTEGER, so a level the wiki writes as a range never
	// reaches us: the wiki's own module writes it with tonumber(), a range yields nil, and the field
	// is dropped from the row. Vardorvis is the only monster in the bestiary this actually costs
	// (its Strength and Defence scale with remaining HP, e.g. "270-360"), which is why they rendered
	// as a dash. There is no Bucket field to fix, so the values come from the page wikitext instead.
	//
	// Rather than make stats fetch per monster — which would cost the whole layer its offline-first,
	// synchronous render — we only ever look at rows Bucket left a hole in (~50 pages bestiary-wide,
	// the rest of which are genuinely blank on the wiki and rightly stay a dash) and pull those in
	// batched queries, cached and refreshed alongside the dataset itself.

	/** The Bucket row key a parsed page's levels are matched back to: name + version anchor. */
	private static String levelKey(String name, String versionAnchor)
	{
		String anchor = versionAnchor == null ? "" : versionAnchor.trim();
		return name.toLowerCase(Locale.ROOT) + "|" + anchor.toLowerCase(Locale.ROOT);
	}

	/** Fetch + parse the pages whose Bucket rows are missing a level, then re-index with the results. */
	private void gapFill(List<MonsterData> rows)
	{
		if (rows == null)
		{
			return;
		}
		List<String> pages = rows.stream()
			.filter(m -> m != null && m.getName() != null && hasData(m) && m.hasMissingLevel())
			.map(MonsterData::getName)
			.distinct()
			.collect(Collectors.toList());
		if (pages.isEmpty())
		{
			return;
		}

		log.debug("Gap-filling levels from {} wiki page(s)", pages.size());
		Map<String, Map<String, InfoboxLevels.LevelText>> found = new ConcurrentHashMap<>();
		AtomicInteger pending = new AtomicInteger((pages.size() + TITLES_PER_QUERY - 1) / TITLES_PER_QUERY);
		for (int i = 0; i < pages.size(); i += TITLES_PER_QUERY)
		{
			List<String> batch = pages.subList(i, Math.min(i + TITLES_PER_QUERY, pages.size()));
			fetchWikitext(batch, found, () ->
			{
				// Publish once every batch has reported, so the dataset is re-indexed only once.
				if (pending.decrementAndGet() > 0)
				{
					return;
				}
				if (found.isEmpty())
				{
					return;
				}
				this.levelRanges = found;
				writeLevelRanges(found);
				index(rows);
				log.info("Recovered {} monster level(s) the Bucket API cannot carry", found.size());
			});
		}
	}

	/** One batched {@code action=query} for up to 50 pages' wikitext; parses each into {@code found}. */
	private void fetchWikitext(List<String> titles, Map<String, Map<String, InfoboxLevels.LevelText>> found,
		Runnable done)
	{
		HttpUrl url = HttpUrl.get(API_URL).newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("prop", "revisions")
			.addQueryParameter("rvprop", "content")
			.addQueryParameter("rvslots", "main")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("titles", String.join("|", titles))
			.build();
		Request req = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				// The dataset still serves; these levels simply stay a dash until the next refresh.
				log.debug("Level gap-fill fetch failed", e);
				done.run();
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					if (res.isSuccessful() && res.body() != null)
					{
						readWikitext(gson.fromJson(res.body().string(), QueryResponse.class), titles, found);
					}
				}
				catch (Exception e)
				{
					log.debug("Level gap-fill parse failed", e);
				}
				done.run();
			}
		});
	}

	/**
	 * Parse each returned page's infobox and key its levels back to the Bucket rows they belong to.
	 * The monster name we asked for isn't always the title we get back (MediaWiki normalises case and
	 * follows redirects), so the response's own alias lists map our name to the page that answered it.
	 */
	private static void readWikitext(QueryResponse res, List<String> titles,
		Map<String, Map<String, InfoboxLevels.LevelText>> found)
	{
		if (res == null || res.query == null || res.query.pages == null)
		{
			return;
		}

		Map<String, String> alias = new HashMap<>();
		addAliases(alias, res.query.normalized);
		addAliases(alias, res.query.redirects);

		Map<String, String> wikitext = new HashMap<>();
		for (QueryResponse.Page page : res.query.pages)
		{
			String content = page.content();
			if (page.title != null && content != null)
			{
				wikitext.put(page.title.toLowerCase(Locale.ROOT), content);
			}
		}

		for (String name : titles)
		{
			String title = name.toLowerCase(Locale.ROOT);
			// Follow name -> normalised -> redirect target (bounded, so a redirect loop can't hang).
			for (int hop = 0; hop < 4 && alias.containsKey(title); hop++)
			{
				title = alias.get(title);
			}
			String content = wikitext.get(title);
			if (content == null)
			{
				continue;
			}
			for (Map.Entry<String, Map<String, InfoboxLevels.LevelText>> e : InfoboxLevels.parse(content).entrySet())
			{
				found.put(levelKey(name, e.getKey()), e.getValue());
			}
		}
	}

	private static void addAliases(Map<String, String> into, List<QueryResponse.Alias> aliases)
	{
		if (aliases == null)
		{
			return;
		}
		for (QueryResponse.Alias a : aliases)
		{
			if (a.from != null && a.to != null)
			{
				into.put(a.from.toLowerCase(Locale.ROOT), a.to.toLowerCase(Locale.ROOT));
			}
		}
	}

	private void readLevelRanges()
	{
		if (!LEVELS_CACHE_FILE.isFile())
		{
			return;
		}
		try (Reader r = Files.newBufferedReader(LEVELS_CACHE_FILE.toPath(), StandardCharsets.UTF_8))
		{
			Map<String, Map<String, InfoboxLevels.LevelText>> cached = gson.fromJson(r, LEVEL_RANGES_TYPE);
			if (cached != null && !cached.isEmpty())
			{
				this.levelRanges = cached;
			}
		}
		catch (Exception e)
		{
			log.debug("Failed to read cached level ranges", e);
		}
	}

	private void writeLevelRanges(Map<String, Map<String, InfoboxLevels.LevelText>> ranges)
	{
		try
		{
			Files.createDirectories(CACHE_DIR.toPath());
			Files.write(LEVELS_CACHE_FILE.toPath(), gson.toJson(ranges, LEVEL_RANGES_TYPE)
				.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.debug("Failed to cache level ranges", e);
		}
	}

	/** The slice of the MediaWiki {@code action=query} response we need: each page's wikitext. */
	private static final class QueryResponse
	{
		private Query query;

		private static final class Query
		{
			private List<Alias> normalized;
			private List<Alias> redirects;
			private List<Page> pages;
		}

		/** A title MediaWiki rewrote — {@code from} is what we asked for, {@code to} what answered. */
		private static final class Alias
		{
			private String from;
			private String to;
		}

		private static final class Page
		{
			private String title;
			private List<Revision> revisions;

			private String content()
			{
				if (revisions == null || revisions.isEmpty())
				{
					return null;
				}
				Revision rev = revisions.get(0);
				return rev.slots == null || rev.slots.main == null ? null : rev.slots.main.content;
			}
		}

		private static final class Revision
		{
			private Slots slots;
		}

		private static final class Slots
		{
			private Slot main;
		}

		private static final class Slot
		{
			private String content;
		}
	}

	/** Build the id/name indexes from the parsed Bucket rows and publish them atomically. */
	private void index(List<MonsterData> all)
	{
		if (all == null)
		{
			return;
		}

		// Group by name, dropping rows with no combat data (e.g. a Vanguard's non-combat "Moving"
		// pose, which Bucket returns with null stats).
		Map<String, List<MonsterData>> name = new LinkedHashMap<>();
		Map<String, Map<String, InfoboxLevels.LevelText>> ranges = this.levelRanges;
		for (MonsterData m : all)
		{
			if (m == null || m.getName() == null || !hasData(m))
			{
				continue;
			}
			// Hand back the levels Bucket dropped for this variant, if we recovered any.
			Map<String, InfoboxLevels.LevelText> dropped = ranges.get(levelKey(m.getName(), m.getVersionAnchor()));
			m.setLevelRanges(dropped != null ? dropped : Collections.emptyMap());
			name.computeIfAbsent(m.getName().toLowerCase(Locale.ROOT), k -> new ArrayList<>()).add(m);
		}

		// Reduce each name to the variants a player can actually act on, then label what's left.
		for (Map.Entry<String, List<MonsterData>> e : name.entrySet())
		{
			e.setValue(relevantVariants(e.getValue()));
			assignVersions(e.getValue());
		}

		// Index by spawn id (each row may carry several). When ids collide across rows (e.g. Duke
		// Sucellus' shared "Defeated" id), the default form wins, else first-seen.
		Map<Integer, MonsterData> id = new HashMap<>();
		for (List<MonsterData> group : name.values())
		{
			for (MonsterData m : group)
			{
				if (m.getIds() == null)
				{
					continue;
				}
				for (String s : m.getIds())
				{
					Integer idn = MonsterData.parseId(s);
					if (idn == null)
					{
						continue;
					}
					MonsterData existing = id.get(idn);
					if (existing == null || (m.isDefaultVersion() && !existing.isDefaultVersion()))
					{
						id.put(idn, m);
					}
				}
			}
		}

		// Publish atomically once fully built.
		this.byId = id;
		this.byName = name;
		log.debug("Indexed {} monster rows ({} unique names)", all.size(), name.size());
	}

	/**
	 * Reduce a name's rows to the variants worth offering, in dataset order.
	 *
	 * <p>The wiki carries a row per <b>sprite</b>, so a quarter of the bestiary is variants that differ
	 * in nothing the plugin renders: thirteen Hill Giants at level 28, 124 Guards, seventeen Crystal
	 * implings. Those collapse onto one entry by {@link MonsterData#statKey()} (#62). It also keeps
	 * {@code (historical)} pages for forms removed from the game, which are dropped (#63) — but only
	 * when a live sibling remains, since a name whose every row is historical (Barbarian woman) would
	 * otherwise disappear from search entirely, which is worse than showing an outdated form.
	 *
	 * <p>The survivor of a collapse <b>absorbs the others' spawn ids</b>, so right-clicking any of
	 * those spawns still resolves by id rather than falling through to the name+level guess.
	 */
	static List<MonsterData> relevantVariants(List<MonsterData> group)
	{
		List<MonsterData> live = group.stream().filter(m -> !m.isNonLive()).collect(Collectors.toList());
		List<MonsterData> pool = live.isEmpty() ? group : live;

		Map<String, MonsterData> kept = new LinkedHashMap<>();
		for (MonsterData m : pool)
		{
			MonsterData existing = kept.get(m.statKey());
			if (existing == null)
			{
				kept.put(m.statKey(), m);
				continue;
			}
			// Same monster, different sprite. Keep the more canonical row so the surviving label is
			// the one a player would recognise, and carry the loser's ids across.
			if (outranks(m, existing))
			{
				m.absorbIds(existing.getIds());
				kept.put(m.statKey(), m);
			}
			else
			{
				existing.absorbIds(m.getIds());
			}
		}
		return new ArrayList<>(kept.values());
	}

	/** Which of two stat-identical rows should represent them: Bucket's default form, else its own article. */
	private static boolean outranks(MonsterData candidate, MonsterData incumbent)
	{
		if (candidate.isDefaultVersion() != incumbent.isDefaultVersion())
		{
			return candidate.isDefaultVersion();
		}
		return candidate.isOwnPage() && !incumbent.isOwnPage();
	}

	/**
	 * Assign each variant in a name group a unique display {@code version}: the {@code version_anchor}
	 * when it's present and unique, otherwise disambiguated with the combat level (or hitpoints when
	 * the level is unknown) — e.g. {@code "Awake (lvl 758)"} or {@code "Level 100"}. A lone blank
	 * anchor stays "" (the plain "Standard" form).
	 *
	 * <p>A name group can also span <b>pages</b>: an infobox may set a name that isn't its page
	 * title, so a boss article and its quest fight both emit rows named "Shellbane gryphon". Those
	 * rows share a blank anchor and often the same combat level, so the level alone can't separate
	 * them — the row from the monster's own article keeps the plain form and the others are labelled
	 * from their page ("Troubled Tortugans"), which is how the wiki itself tells them apart. Without
	 * this they collided into "Level 235" / "Level 235 #2" — labels found nowhere on the wiki (#60).
	 */
	static void assignVersions(List<MonsterData> group)
	{
		Map<String, Integer> counts = new HashMap<>();
		for (MonsterData m : group)
		{
			counts.merge(baseLabel(m), 1, Integer::sum);
		}
		// Only worth qualifying by page when the group actually spans pages *and* the monster's own
		// article is among them; otherwise every row would gain a label with nothing to contrast against.
		long ownPageRows = group.stream().filter(MonsterData::isOwnPage).count();
		boolean spansPages = ownPageRows > 0
			&& group.stream().anyMatch(m -> !m.pageQualifier().isEmpty());
		Set<String> used = new HashSet<>();
		for (MonsterData m : group)
		{
			String base = baseLabel(m);
			String label;
			if (base.isEmpty())
			{
				if (spansPages)
				{
					// The own article keeps the plain form — but only while it's the lone row from
					// that page, since "" bypasses the uniqueness guard below.
					label = m.isOwnPage()
						? (ownPageRows == 1 ? "" : tier(m))
						: m.pageQualifier();
				}
				else
				{
					label = group.size() == 1 ? "" : tier(m);
				}
			}
			else if (counts.get(base) == 1)
			{
				label = base;
			}
			else if (!m.pageQualifier().isEmpty())
			{
				// Anchors collide across pages too, and there the combat level is no help: the wiki
				// names these "Level 13", so appending the level restated it and the rows fell through
				// to "Level 13 #2"/"#3". The page is what actually distinguishes them (#60).
				label = base + " (" + m.pageQualifier() + ")";
			}
			else if (spansPages && m.isOwnPage())
			{
				// The monster's own article owns the bare anchor; the foreign rows carry a qualifier.
				label = base;
			}
			else
			{
				label = base + " (" + tierShort(m) + ")";
			}
			// Guarantee uniqueness even if level/hitpoints also coincide.
			String unique = label;
			int n = 2;
			while (!unique.isEmpty() && !used.add(unique.toLowerCase(Locale.ROOT)))
			{
				unique = label + " #" + n++;
			}
			m.setVersion(unique);
		}
	}

	private static String baseLabel(MonsterData m)
	{
		return m.getVersionAnchor() == null ? "" : m.getVersionAnchor().trim();
	}

	private static String tier(MonsterData m)
	{
		return m.getLevel() > 0 ? "Level " + m.getLevel() : "HP " + m.getHitpoints();
	}

	private static String tierShort(MonsterData m)
	{
		return m.getLevel() > 0 ? "lvl " + m.getLevel() : "hp " + m.getHitpoints();
	}

	/** True once the dataset has been indexed, so accessors return real data (not async-empty). */
	public boolean isLoaded()
	{
		return !byName.isEmpty();
	}

	public MonsterData getById(int npcId)
	{
		return byId.get(npcId);
	}

	/** All variants sharing the given (live NPC's) base name, in dataset order. */
	public List<MonsterData> variantsForId(int npcId)
	{
		MonsterData m = byId.get(npcId);
		if (m == null)
		{
			return Collections.emptyList();
		}
		return byName.getOrDefault(m.getName().toLowerCase(Locale.ROOT), Collections.singletonList(m));
	}

	public List<MonsterData> variantsForName(String name)
	{
		return byName.getOrDefault(name.toLowerCase(Locale.ROOT), Collections.emptyList());
	}

	/**
	 * The variant to show for a name: the one matching {@code version} (case-insensitive), else
	 * {@link #defaultVariant}. Null when the name has no variants.
	 */
	public MonsterData variant(String name, String version)
	{
		List<MonsterData> variants = variantsForName(name);
		if (variants.isEmpty())
		{
			return null;
		}
		if (version != null && !version.isEmpty())
		{
			for (MonsterData v : variants)
			{
				if (version.equalsIgnoreCase(v.getVersion()))
				{
					return v;
				}
			}
		}
		return defaultVariant(variants);
	}

	/**
	 * Pick a sensible default from a name's variants: the Bucket-flagged default form with data;
	 * else the plain (unlabelled) form with data; else the highest-level variant with data; failing
	 * that, any standard form, else the first. Pure over its argument.
	 *
	 * <p>When the group spans pages, rows from pages that merely reuse the name (a quest fight) are
	 * set aside first: a bare name means the monster's own article, and a foreign row could otherwise
	 * win on combat level (#60). A group entirely from one page is unaffected.
	 */
	static MonsterData defaultVariant(List<MonsterData> variants)
	{
		List<MonsterData> ownPage = variants.stream()
			.filter(m -> m.isOwnPage() && hasData(m))
			.collect(Collectors.toList());
		if (!ownPage.isEmpty() && ownPage.size() < variants.size())
		{
			variants = ownPage;
		}

		for (MonsterData m : variants)
		{
			if (m.isDefaultVersion() && hasData(m))
			{
				return m;
			}
		}
		for (MonsterData m : variants)
		{
			if (isStandard(m) && hasData(m))
			{
				return m;
			}
		}

		MonsterData best = null;
		for (MonsterData m : variants)
		{
			if (hasData(m) && (best == null || m.getLevel() > best.getLevel()))
			{
				best = m;
			}
		}
		if (best != null)
		{
			return best;
		}

		for (MonsterData m : variants)
		{
			if (isStandard(m))
			{
				return m;
			}
		}
		return variants.isEmpty() ? null : variants.get(0);
	}

	/** The version string of the variant whose combat level matches {@code combatLevel}, or null. */
	public String variantVersionForLevel(String name, int combatLevel)
	{
		MonsterData variant = variantForLevel(name, combatLevel);
		return variant == null ? null : variant.getVersion();
	}

	/**
	 * The best variant whose combat level exactly matches the live NPC, or null when none does.
	 * Requiring an exact match is important for name fallback: a cosmetic pet can share a name with
	 * a real monster while having a different NPC id and no combat level.
	 */
	public MonsterData variantForLevel(String name, int combatLevel)
	{
		return variantForLevel(variantsForName(name), combatLevel);
	}

	/** Pure list overload for exact-level selection and regression tests. */
	static MonsterData variantForLevel(List<MonsterData> variants, int combatLevel)
	{
		List<MonsterData> atLevel = variants.stream()
			.filter(v -> v.getLevel() == combatLevel)
			.collect(Collectors.toList());
		if (atLevel.isEmpty())
		{
			return null;
		}
		// Several variants can share a level with genuinely different stats — Alchemical Hydra's four
		// phases at 426, Abyssal Sire, Araxxor — so returning the first match showed whichever row
		// Bucket happened to order first. Reuse the default-variant ranking instead (#62).
		MonsterData best = defaultVariant(atLevel);
		return best != null ? best : atLevel.get(0);
	}

	private static boolean isStandard(MonsterData m)
	{
		return m.getVersion() == null || m.getVersion().isEmpty();
	}

	private static boolean hasData(MonsterData m)
	{
		return m.getHitpoints() > 0 || m.getLevel() > 0;
	}

	/** Distinct base names matching the query, exact-match first, then alphabetical. */
	public List<String> searchNames(String query, int limit)
	{
		List<String> baseNames = byName.values().stream()
			.map(v -> v.get(0).getName())
			.collect(Collectors.toList());
		return matchNames(baseNames, query, limit);
	}

	/**
	 * Rank {@code names} against {@code query}: substring match (case-insensitive), an exact
	 * match floated to the top, the rest alphabetical, capped at {@code limit}. Pure helper so
	 * the ranking can be unit-tested without loading the dataset.
	 */
	static List<String> matchNames(Collection<String> names, String query, int limit)
	{
		String q = query.toLowerCase(Locale.ROOT).trim();
		return names.stream()
			.filter(n -> q.isEmpty() || n.toLowerCase(Locale.ROOT).contains(q))
			.distinct()
			.sorted((a, b) ->
			{
				boolean ea = a.equalsIgnoreCase(q);
				boolean eb = b.equalsIgnoreCase(q);
				if (ea != eb)
				{
					return ea ? -1 : 1;
				}
				return a.compareToIgnoreCase(b);
			})
			.limit(limit)
			.collect(Collectors.toList());
	}
}

package com.bettermonsterexamine;

import java.awt.Color;
import net.runelite.client.ui.ColorScheme;

/**
 * Player-relevant stat colours, shared by the side panel and the in-game overlay so both
 * honour the same {@link HighlightMode} palette. "Danger" marks values that are bad for the
 * player (aggressive, positive flat armour, over-HP max hits); "good" marks values in the
 * player's favour (negative flat armour, an XP bonus); the level colour mirrors the in-game
 * monster-hover gradient.
 */
final class StatColors
{
	/** Red for player-dangerous values. */
	static final Color DANGER_RED = new Color(0xFF4040);

	/** Okabe-Ito orange/blue: colour-blind-distinguishable stand-ins for the red/green cues. */
	static final Color CB_DANGER = new Color(0xE69F00);
	static final Color CB_GOOD = new Color(0x56B4E9);

	/** Okabe-Ito yellow, distinct from both palettes' good/danger, so it serves both. */
	static final Color NEXT_YELLOW = new Color(0xF0E442);

	private StatColors()
	{
	}

	/** Resolve a semantic {@link ColourRole} to a concrete colour for the active mode. */
	static Color resolve(ColourRole role, HighlightMode mode)
	{
		switch (role)
		{
			case DANGER:
				return danger(mode);
			case GOOD:
				return good(mode);
			case NEXT:
				return mode == HighlightMode.OFF ? Color.WHITE : NEXT_YELLOW;
			default:
				return Color.WHITE;
		}
	}

	/** The "danger" highlight colour for the active mode; white when highlighting is off. */
	private static Color danger(HighlightMode mode)
	{
		switch (mode)
		{
			case OFF:
				return Color.WHITE;
			case COLOUR_BLIND:
				return CB_DANGER;
			default:
				return DANGER_RED;
		}
	}

	/** The "good for the player" highlight colour for the active mode; white when off. */
	private static Color good(HighlightMode mode)
	{
		switch (mode)
		{
			case OFF:
				return Color.WHITE;
			case COLOUR_BLIND:
				return CB_GOOD;
			default:
				return ColorScheme.PROGRESS_COMPLETE_COLOR;
		}
	}

	/** Combat-level colour for the active mode: the in-game gradient (Standard) or orange/blue (CB). */
	static Color levelColor(HighlightMode mode, int playerLevel, int npcLevel)
	{
		switch (mode)
		{
			case OFF:
				return Color.WHITE;
			case COLOUR_BLIND:
				if (playerLevel <= 0 || npcLevel == playerLevel)
				{
					return Color.WHITE;
				}
				return npcLevel > playerLevel ? CB_DANGER : CB_GOOD;
			default:
				return combatLevelColor(playerLevel, npcLevel);
		}
	}

	/**
	 * The in-game combat-level colour for the monster hover: green when it's well below the
	 * player, yellow at parity, orange→red as it climbs above, matching RuneScape's bands by
	 * the (player − monster) level difference. White when the player level is unknown.
	 */
	private static Color combatLevelColor(int playerLevel, int npcLevel)
	{
		if (playerLevel <= 0)
		{
			return Color.WHITE;
		}
		int d = playerLevel - npcLevel;
		if (d < -9)
		{
			return new Color(0xFF0000);
		}
		if (d < -6)
		{
			return new Color(0xFF3000);
		}
		if (d < -3)
		{
			return new Color(0xFF7000);
		}
		if (d < 0)
		{
			return new Color(0xFFB000);
		}
		if (d > 9)
		{
			return new Color(0x00FF00);
		}
		if (d > 6)
		{
			return new Color(0x40FF00);
		}
		if (d > 3)
		{
			return new Color(0x80FF00);
		}
		if (d > 0)
		{
			return new Color(0xC0FF00);
		}
		return new Color(0xFFFF00);
	}
}

package com.bettermonsterexamine;

import java.util.Map;
import lombok.Getter;

/**
 * A parsed inbound {@code bettermonsterexamine}/{@code displayMonster} request — the return leg of the
 * Not Enough Runes link, and the entry point for any plugin that wants to open a monster here.
 *
 * <p>Sibling classloaders mean nothing but core types can cross the boundary, so the payload is a
 * {@code Map} of strings and numbers and every read is type-checked rather than cast. Numbers are
 * taken as {@link Number} rather than {@code Integer} so a sender that boxes differently still works.
 *
 * <p>The contract:
 *
 * <table>
 *   <tr><th>key</th><th>type</th><th>required</th></tr>
 *   <tr><td>{@code name}</td><td>String</td><td>unless {@code npcId} is given</td></tr>
 *   <tr><td>{@code level}</td><td>Number</td><td>no — in-game combat level, picks a variant</td></tr>
 *   <tr><td>{@code npcId}</td><td>Number</td><td>no — preferred when present, it beats name matching</td></tr>
 *   <tr><td>{@code tab}</td><td>String</td><td>no — {@code "stats"} (default) or {@code "drops"}</td></tr>
 * </table>
 *
 * <p>Unknown keys are ignored, so the contract can grow without either side having to ship in step.
 */
@Getter
final class MonsterLookupMessage
{
	static final String NAMESPACE = "bettermonsterexamine";
	static final String DISPLAY_MONSTER = "displayMonster";

	private static final String KEY_NAME = "name";
	private static final String KEY_LEVEL = "level";
	private static final String KEY_NPC_ID = "npcId";
	private static final String KEY_TAB = "tab";
	private static final String TAB_DROPS = "drops";

	/** The requested NPC id, or null. Resolves to a variant outright, so it wins over name + level. */
	private final Integer npcId;
	/** The requested monster name, trimmed; null when the request only carried an {@code npcId}. */
	private final String name;
	/** The in-game combat level used to pick a variant, or null to take the default one. */
	private final Integer level;
	/** True when the sender asked for the Drops tab; Stats otherwise. */
	private final boolean drops;

	private MonsterLookupMessage(Integer npcId, String name, Integer level, boolean drops)
	{
		this.npcId = npcId;
		this.name = name;
		this.level = level;
		this.drops = drops;
	}

	/**
	 * Parse a request, or return null when it carries nothing to act on — neither an {@code npcId} nor
	 * a non-blank {@code name}. A wrongly-typed value is treated as absent rather than throwing: a
	 * malformed message from another plugin should be ignored, not crash the event bus.
	 */
	static MonsterLookupMessage of(Map<String, Object> data)
	{
		if (data == null)
		{
			return null;
		}
		Integer npcId = intOrNull(data.get(KEY_NPC_ID));
		String name = data.get(KEY_NAME) instanceof String ? ((String) data.get(KEY_NAME)).trim() : null;
		if (name != null && name.isEmpty())
		{
			name = null;
		}
		if (npcId == null && name == null)
		{
			return null;
		}
		Object tab = data.get(KEY_TAB);
		boolean drops = tab instanceof String && TAB_DROPS.equalsIgnoreCase(((String) tab).trim());
		return new MonsterLookupMessage(npcId, name, intOrNull(data.get(KEY_LEVEL)), drops);
	}

	private static Integer intOrNull(Object value)
	{
		return value instanceof Number ? ((Number) value).intValue() : null;
	}
}

package com.bettermonsterexamine;

import java.awt.Color;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Function;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/** Formatter for the compact combat block appended to a normal NPC Examine response. */
final class ExamineSummary
{
	// Each element in its rune's colour, twice over: the opaque chatbox is light parchment and the
	// transparent one is dark, and no single shade reads on both.
	private static final Color FIRE_OPAQUE = new Color(0xB22800);
	private static final Color FIRE_TRANSPARENT = new Color(0xFF7A3D);
	private static final Color WATER_OPAQUE = new Color(0x0038B8);
	private static final Color WATER_TRANSPARENT = new Color(0x5CA8FF);
	private static final Color EARTH_OPAQUE = new Color(0x6E3B0E);
	private static final Color EARTH_TRANSPARENT = new Color(0xD09A5E);
	private static final Color AIR_OPAQUE = new Color(0x4F5B66);
	private static final Color AIR_TRANSPARENT = new Color(0xB9E6F2);

	// The panel's highlights, with a darker shade for the parchment chatbox. The colour-blind
	// shade is Okabe-Ito blue; yellow is already colour-blind safe, so one shade serves both modes.
	private static final Color GOOD_OPAQUE = new Color(0x006600);
	private static final Color CB_GOOD_OPAQUE = new Color(0x0072B2);
	private static final Color NEXT_OPAQUE = new Color(0x7A5C00);

	private static final String GAP = "  ";

	private ExamineSummary()
	{
	}

	/**
	 * @param transparentChat whether the chatbox is transparent, which picks each colour's shade
	 * @param rolls show defence rolls rather than bonuses, when the monster has every roll input
	 * @param highlight the palette for the styles the Weakness line would name
	 */
	static List<String> format(MonsterData monster, ExamineSummaryMode mode, boolean transparentChat,
		boolean rolls, HighlightMode highlight)
	{
		if (monster == null || mode == null)
		{
			return Collections.emptyList();
		}
		if (mode == ExamineSummaryMode.ALL_DEFENCES)
		{
			return allDefences(monster, transparentChat, rolls && monster.hasDefenceRollInputs(), highlight);
		}

		String weakness = weakness(monster, transparentChat);
		return weakness == null ? Collections.emptyList() : List.of(weakness);
	}

	/**
	 * Every defence in the panel's order, melee then magic and ranged, in place of the Weakness
	 * line: the styles it would name are coloured instead, so it would only repeat them.
	 */
	private static List<String> allDefences(MonsterData monster, boolean transparentChat, boolean rolls,
		HighlightMode highlight)
	{
		Map<DefenceRolls.Style, Integer> values = rolls ? DefenceRolls.rolls(monster) : null;
		Map<DefenceRolls.Style, ColourRole> roles = DefenceRolls.roles(monster);
		Function<DefenceRolls.Style, String> cell = style ->
		{
			String value = rolls ? StatFormat.roll(values.get(style)) : StatFormat.bonus(DefenceRolls.bonus(monster, style));
			String text = shortLabel(style) + ' ' + value;
			Color color = roleColor(roles.get(style), highlight, transparentChat);
			return color == null ? text : ColorUtil.wrapWithColorTag(text, color);
		};

		String magic = cell.apply(DefenceRolls.Style.MAGIC);
		String element = element(monster);
		if (element != null)
		{
			magic += " (" + colored(element + ' ' + monster.getWeaknessPercent() + '%', element, transparentChat) + ')';
		}
		return List.of(
			String.join(GAP, cell.apply(DefenceRolls.Style.STAB), cell.apply(DefenceRolls.Style.SLASH),
				cell.apply(DefenceRolls.Style.CRUSH)),
			String.join(GAP, magic, cell.apply(DefenceRolls.Style.LIGHT), cell.apply(DefenceRolls.Style.STANDARD),
				cell.apply(DefenceRolls.Style.HEAVY)));
	}

	/** "Std" keeps the magic and ranged line from wrapping in a fixed-size chatbox. */
	private static String shortLabel(DefenceRolls.Style style)
	{
		return style == DefenceRolls.Style.STANDARD ? "Std" : style.getLabel();
	}

	/** A highlight in a shade that reads on this chatbox, or null to leave the text plain. */
	private static Color roleColor(ColourRole role, HighlightMode highlight, boolean transparentChat)
	{
		if (role == null || highlight == HighlightMode.OFF)
		{
			return null;
		}
		if (role == ColourRole.NEXT)
		{
			return transparentChat ? StatColors.NEXT_YELLOW : NEXT_OPAQUE;
		}
		if (highlight == HighlightMode.COLOUR_BLIND)
		{
			return transparentChat ? StatColors.CB_GOOD : CB_GOOD_OPAQUE;
		}
		return transparentChat ? StatColors.resolve(ColourRole.GOOD, highlight) : GOOD_OPAQUE;
	}

	/**
	 * The one line that answers "what do I hit this with", ranked by defence roll rather than by
	 * raw bonus — see {@link DefenceRolls}. A comma means "then" and a slash means "tied":
	 * {@code Magic (Water), Ranged} is magic first and ranged as the best style that costs no
	 * runes. Null when the wiki carries no defensive numbers, which drops the line rather than
	 * printing a seven-way tie of zeroes.
	 *
	 * <p>The elemental weakness rides in the magic label and nowhere else: it is a damage
	 * multiplier, not accuracy, so naming it beside a melee or ranged answer would read as an
	 * endorsement of casting on a monster that resists it. It is the only thing coloured.
	 */
	private static String weakness(MonsterData monster, boolean transparentChat)
	{
		DefenceRolls.Result rolls = DefenceRolls.of(monster);
		switch (rolls.getBand())
		{
			case NO_DATA:
				return null;
			case CANNOT_MISS:
				return "Weakness: anything";
			case EVEN:
				return "Weakness: none";
			default:
				break;
		}

		String line = "Weakness: " + styles(rolls.getWeakest(), rolls.getElement(), transparentChat);
		if (!rolls.getFreeWeakest().isEmpty())
		{
			line += ", " + DefenceRolls.describe(rolls.getFreeWeakest());
		}
		return line;
	}

	private static String styles(List<DefenceRolls.Style> styles, String element, boolean transparentChat)
	{
		String described = DefenceRolls.describe(styles);
		if (element == null || !styles.contains(DefenceRolls.Style.MAGIC))
		{
			return described;
		}
		return described.replace("Magic", "Magic (" + colored(Text.escapeJagex(element), element, transparentChat) + ')');
	}

	/**
	 * The monster's name as it can safely go on a chat line: Jagex formatting escaped so a name
	 * containing tags can't recolour the row, and line breaks flattened so it stays one line.
	 * Null when there's nothing usable left, which tells the caller to leave the line alone.
	 */
	static String chatName(String name)
	{
		if (name == null)
		{
			return null;
		}
		String cleaned = name.replace('\r', ' ').replace('\n', ' ').trim();
		return cleaned.isEmpty() ? null : Text.escapeJagex(cleaned);
	}

	/** {@code text} in {@code element}'s colour, or left plain for an element with none. */
	private static String colored(String text, String element, boolean transparentChat)
	{
		Color color = elementColor(element, transparentChat);
		return color == null ? text : ColorUtil.wrapWithColorTag(text, color);
	}

	private static Color elementColor(String element, boolean transparentChat)
	{
		switch (element.toLowerCase(Locale.ROOT))
		{
			case "fire":
				return transparentChat ? FIRE_TRANSPARENT : FIRE_OPAQUE;
			case "water":
				return transparentChat ? WATER_TRANSPARENT : WATER_OPAQUE;
			case "earth":
				return transparentChat ? EARTH_TRANSPARENT : EARTH_OPAQUE;
			case "air":
				return transparentChat ? AIR_TRANSPARENT : AIR_OPAQUE;
			default:
				return null;
		}
	}

	private static String element(MonsterData monster)
	{
		String element = monster.getWeaknessElement();
		return element == null || element.trim().isEmpty()
			? null
			: Text.escapeJagex(StatFormat.cap(element.trim()));
	}
}

package com.bettermonsterexamine;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * Ranks a monster's attack styles by how hard it is to <em>hit</em>, using the OSRS defence roll
 * {@code (level + 9) x (style defence bonus + 64)} — lower is easier.
 *
 * <p>Melee and ranged both roll off the Defence level, so the {@code (level + 9)} term cancels and
 * ranking those six by raw defence bonus alone gives exactly the same order as the roll. Magic is
 * the exception: it rolls off the monster's <b>Magic</b> level. That is why reading the bonuses
 * alone gets the answer wrong on roughly one monster in seven — a Fire giant's {@code +50} magic
 * bonus is the highest defence bonus it has, yet magic is 6x easier to land than anything else
 * because its Magic level is 1.
 *
 * <p>Most of the bestiary is easiest to hit with magic, and magic costs runes, so the result also
 * names the easiest free style whenever magic wins alone.
 *
 * <p>Pure and unit-tested; the renderers shape the {@link Result} into text.
 */
final class DefenceRolls
{
	/** Wiki pages whose magic defence rolls off Defence level rather than Magic level. */
	private static final Set<String> MAGIC_OFF_DEFENCE = Set.of(
		"verzik vitur", "ice demon", "fragment of seren", "baboon brawler", "rabbit (prifddinas)");

	/**
	 * Styles within this factor of the easiest roll count as tied with it. The ratio decides the
	 * answer but is never shown — a bare "1.9x" needs explaining that a chat line can't give.
	 */
	private static final double TIE = 1.25d;

	enum Family
	{
		MELEE, RANGED, MAGIC
	}

	enum Style
	{
		STAB("Stab", Family.MELEE),
		SLASH("Slash", Family.MELEE),
		CRUSH("Crush", Family.MELEE),
		STANDARD("Standard", Family.RANGED),
		HEAVY("Heavy", Family.RANGED),
		LIGHT("Light", Family.RANGED),
		MAGIC("Magic", Family.MAGIC);

		@Getter
		private final String label;
		@Getter
		private final Family family;

		Style(String label, Family family)
		{
			this.label = label;
			this.family = family;
		}
	}

	/**
	 * What the ranking amounts to. {@link #NO_DATA} means the wiki carries no defensive numbers at
	 * all — distinct from every bonus genuinely being zero, which is {@link #CANNOT_MISS}.
	 */
	enum Band
	{
		NO_DATA, CANNOT_MISS, EVEN, RANKED
	}

	@Getter
	static final class Result
	{
		private final Band band;
		/** The easiest styles to land, ties included. Empty unless {@link Band#RANKED}. */
		private final List<Style> weakest;
		/**
		 * The easiest styles that cost no runes, when magic alone is easiest and one free style
		 * stands out from the rest. Empty otherwise — including when every free style is even.
		 */
		private final List<Style> freeWeakest;
		/** Capitalised elemental weakness (a damage multiplier, not accuracy), or null. */
		private final String element;
		private final int elementPercent;

		private Result(Band band, List<Style> weakest, List<Style> freeWeakest, String element, int elementPercent)
		{
			this.band = band;
			this.weakest = weakest;
			this.freeWeakest = freeWeakest;
			this.element = element;
			this.elementPercent = elementPercent;
		}
	}

	private DefenceRolls()
	{
	}

	static Result of(MonsterData monster)
	{
		if (monster == null || !monster.hasDefenceRollInputs())
		{
			return new Result(Band.NO_DATA, List.of(), List.of(), null, 0);
		}

		String element = element(monster);
		int percent = element == null ? 0 : monster.getWeaknessPercent();
		Map<Style, Integer> rolls = rolls(monster);

		if (rolls.values().stream().allMatch(v -> v == 0))
		{
			return new Result(Band.CANNOT_MISS, List.of(), List.of(), element, percent);
		}

		List<Style> weakest = nearest(rolls, allStyles());
		if (weakest.size() == Style.values().length)
		{
			return new Result(Band.EVEN, List.of(), List.of(), element, percent);
		}

		List<Style> freeWeakest = List.of();
		if (weakest.equals(List.of(Style.MAGIC)))
		{
			List<Style> free = new ArrayList<>(allStyles());
			free.remove(Style.MAGIC);
			List<Style> nearestFree = nearest(rolls, free);
			if (nearestFree.size() < free.size())
			{
				freeWeakest = nearestFree;
			}
		}
		return new Result(Band.RANKED, weakest, freeWeakest, element, percent);
	}

	/**
	 * The highlight for each style the Weakness line names: its first answer {@link ColourRole#GOOD},
	 * the free style it names second {@link ColourRole#NEXT}. Unnamed styles are absent.
	 */
	static Map<Style, ColourRole> roles(MonsterData monster)
	{
		Map<Style, ColourRole> roles = new EnumMap<>(Style.class);
		Result result = of(monster);
		if (result.getBand() == Band.RANKED)
		{
			result.getWeakest().forEach(s -> roles.put(s, ColourRole.GOOD));
			result.getFreeWeakest().forEach(s -> roles.put(s, ColourRole.NEXT));
		}
		return roles;
	}

	/** Each style's defence roll. Lower is easier to hit. */
	static Map<Style, Integer> rolls(MonsterData monster)
	{
		int defence = monster.getDefenceLevel();
		int magic = rollsMagicOffDefence(monster.getPageName()) ? defence : monster.getMagicLevel();

		Map<Style, Integer> rolls = new EnumMap<>(Style.class);
		for (Style style : Style.values())
		{
			int level = style.getFamily() == Family.MAGIC ? magic : defence;
			// A bonus below -64 drives the roll negative, which does not mean "even easier" — it
			// means the attacker cannot miss. Clamp, or the ranking inverts.
			rolls.put(style, Math.max(0, (level + 9) * (bonus(monster, style) + 64)));
		}
		return rolls;
	}

	/** The styles among {@code among} whose roll is within {@link #TIE} of the easiest one. */
	private static List<Style> nearest(Map<Style, Integer> rolls, List<Style> among)
	{
		int best = among.stream().mapToInt(rolls::get).min().orElse(0);
		List<Style> out = new ArrayList<>();
		for (Style style : among)
		{
			if (rolls.get(style) <= best * TIE)
			{
				out.add(style);
			}
		}
		return out;
	}

	/**
	 * Collapses a tied set into the shortest honest labels: a whole family that ties becomes
	 * "Melee" or "Ranged" rather than naming all three of its styles.
	 */
	static String describe(List<Style> styles)
	{
		List<String> parts = new ArrayList<>();
		boolean melee = styles.containsAll(family(Family.MELEE));
		boolean ranged = styles.containsAll(family(Family.RANGED));

		if (melee)
		{
			parts.add("Melee");
		}
		if (ranged)
		{
			parts.add("Ranged");
		}
		for (Style style : styles)
		{
			boolean folded = (melee && style.getFamily() == Family.MELEE)
				|| (ranged && style.getFamily() == Family.RANGED);
			if (!folded)
			{
				parts.add(style.getLabel());
			}
		}
		return String.join("/", parts);
	}

	private static List<Style> family(Family family)
	{
		List<Style> out = new ArrayList<>();
		for (Style style : Style.values())
		{
			if (style.getFamily() == family)
			{
				out.add(style);
			}
		}
		return out;
	}

	private static boolean rollsMagicOffDefence(String pageName)
	{
		if (pageName == null)
		{
			return false;
		}
		String page = pageName.toLowerCase(Locale.ROOT);
		return MAGIC_OFF_DEFENCE.stream().anyMatch(page::startsWith);
	}

	private static String element(MonsterData monster)
	{
		String element = monster.getWeaknessElement();
		return element == null || element.trim().isEmpty()
			? null
			: StatFormat.cap(element.trim());
	}

	static int bonus(MonsterData monster, Style style)
	{
		switch (style)
		{
			case STAB:
				return monster.getStabDefenceBonus();
			case SLASH:
				return monster.getSlashDefenceBonus();
			case CRUSH:
				return monster.getCrushDefenceBonus();
			case STANDARD:
				return monster.getStandardRangeDefenceBonus();
			case HEAVY:
				return monster.getHeavyRangeDefenceBonus();
			case LIGHT:
				return monster.getLightRangeDefenceBonus();
			default:
				return monster.getMagicDefenceBonus();
		}
	}

	/** Kept so the styles list reads in a fixed order regardless of map iteration. */
	static List<Style> allStyles()
	{
		return Arrays.asList(Style.values());
	}
}

package com.bettermonsterexamine;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.function.IntSupplier;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * A compact, tabbed in-game overlay modelled on the Monster Examine spell's interface. It
 * draws the monster's stats split across four clickable tabs — Combat, Aggressive, Defensive,
 * Info — directly with {@link Graphics2D} so it reads as a native overlay rather than a blitted
 * panel snapshot. The plugin pushes the selected monster in via {@link #setMonster}.
 *
 * <p>Tab clicks are routed here from the plugin's mouse listener: {@link #tabAt} hit-tests a
 * canvas point against the tab strip (using the bounds the overlay renderer maintains) and
 * {@link #setActiveTab} switches the visible tab.
 */
class MonsterCardOverlay extends Overlay
{
	private static final int WIDTH = 184;
	private static final int PAD = 6;
	/** On-screen size each stat-row icon is scaled to (preserving aspect). */
	private static final int ICON_SIZE = 16;
	/** Minimum gap between an inline label and a right-aligned wrapping value. */
	private static final int LABEL_GAP = 8;
	private static final String[] TAB_LABELS = {"Combat", "Aggro", "Def", "Info"};

	private final BetterMonsterExamineConfig config;
	private final MonsterIcons icons;
	private final IntSupplier playerCombatLevel;
	private final IntSupplier playerHpLevel;
	private final IntSupplier playerSlayerLevel;

	// monster is swapped in from the client thread and read on the render thread; activeTab is
	// written from the mouse (AWT) thread. Volatile is enough — each is an independent
	// reference/int, no compound invariant.
	private volatile MonsterData monster;
	private volatile int activeTab;
	// The tab rectangles and close-button rectangle from the last render, relative to the overlay
	// origin, for hit-testing mouse clicks.
	private volatile Rectangle[] tabBounds;
	private volatile Rectangle closeBounds;

	MonsterCardOverlay(BetterMonsterExamineConfig config, MonsterIcons icons, IntSupplier playerCombatLevel, IntSupplier playerHpLevel, IntSupplier playerSlayerLevel)
	{
		this.config = config;
		this.icons = icons;
		this.playerCombatLevel = playerCombatLevel;
		this.playerHpLevel = playerHpLevel;
		this.playerSlayerLevel = playerSlayerLevel;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Show {@code m} from the first tab. */
	void setMonster(MonsterData m)
	{
		this.monster = m;
		this.activeTab = 0;
	}

	/** Hide the overlay. */
	void clear()
	{
		this.monster = null;
	}

	boolean isShowing()
	{
		return monster != null;
	}

	void setActiveTab(int tab)
	{
		if (monster != null && tab >= 0 && tab < TAB_LABELS.length)
		{
			this.activeTab = tab;
		}
	}

	/** Whether a canvas point is over the close button. */
	boolean closeAt(int canvasX, int canvasY)
	{
		Rectangle bounds = getBounds();
		Rectangle close = closeBounds;
		if (monster == null || bounds == null || close == null)
		{
			return false;
		}
		return close.contains(canvasX - bounds.x, canvasY - bounds.y);
	}

	/** The tab index at a canvas point, or -1 if it isn't over the tab strip. */
	int tabAt(int canvasX, int canvasY)
	{
		Rectangle bounds = getBounds();
		Rectangle[] tabs = tabBounds;
		if (monster == null || bounds == null || tabs == null)
		{
			return -1;
		}
		int lx = canvasX - bounds.x;
		int ly = canvasY - bounds.y;
		for (int i = 0; i < tabs.length; i++)
		{
			if (tabs[i] != null && tabs[i].contains(lx, ly))
			{
				return i;
			}
		}
		return -1;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		MonsterData m = monster;
		if (m == null)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int lineH = fm.getHeight();
		int titleH = lineH + 2;
		int tabH = lineH + 4;
		int contentW = WIDTH - 2 * PAD;

		List<Row> rows = rowsFor(activeTab, m);

		int contentH = 0;
		for (Row r : rows)
		{
			contentH += r.height(fm, contentW, lineH);
		}

		int total = PAD + titleH + tabH + 1 + 3 + contentH + PAD;

		// Background + subtle border.
		g.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		g.fillRect(0, 0, WIDTH, total);
		g.setColor(new Color(0, 0, 0, 120));
		g.drawRect(0, 0, WIDTH - 1, total - 1);

		int y = PAD;
		drawTitle(g, fm, m, y);
		y += titleH;
		drawTabs(g, fm, y, tabH);
		y += tabH + 1 + 3;

		for (Row r : rows)
		{
			y += r.draw(g, fm, PAD, y, contentW, lineH);
		}

		return new Dimension(WIDTH, total);
	}

	private void drawTitle(Graphics2D g, FontMetrics fm, MonsterData m, int y)
	{
		int baseline = y + fm.getAscent();

		// Close (✕) glyph at the far right, drawn as two strokes so it needs no font glyph.
		int cs = fm.getAscent();
		int cx = WIDTH - PAD - cs;
		int cy = y + (fm.getHeight() - cs) / 2;
		g.setColor(new Color(0xFF6060));
		g.drawLine(cx, cy, cx + cs - 1, cy + cs - 1);
		g.drawLine(cx, cy + cs - 1, cx + cs - 1, cy);
		closeBounds = new Rectangle(cx - 3, cy - 3, cs + 6, cs + 6);

		int rightEdge = cx - 6;
		String lvl = m.getLevel() > 0 ? "(lvl-" + m.getLevel() + ")" : "";
		if (!lvl.isEmpty())
		{
			int lvlW = fm.stringWidth(lvl);
			g.setColor(StatColors.levelColor(config.statHighlighting(), playerCombatLevel.getAsInt(), m.getLevel()));
			g.drawString(lvl, rightEdge - lvlW, baseline);
			rightEdge -= lvlW + 6;
		}

		g.setColor(Color.WHITE);
		g.drawString(truncate(fm, m.getName(), rightEdge - PAD), PAD, baseline);
	}

	private void drawTabs(Graphics2D g, FontMetrics fm, int y, int tabH)
	{
		int tabW = WIDTH / TAB_LABELS.length;
		Rectangle[] tabs = new Rectangle[TAB_LABELS.length];
		int active = activeTab;
		for (int i = 0; i < TAB_LABELS.length; i++)
		{
			int tx = i * tabW;
			int tw = i == TAB_LABELS.length - 1 ? WIDTH - tx : tabW;
			tabs[i] = new Rectangle(tx, y, tw, tabH);

			if (i == active)
			{
				g.setColor(ColorScheme.BRAND_ORANGE);
				g.fillRect(tx, y, tw, tabH);
			}
			String label = TAB_LABELS[i];
			int lx = tx + (tw - fm.stringWidth(label)) / 2;
			int baseline = y + (tabH + fm.getAscent() - fm.getDescent()) / 2;
			g.setColor(i == active ? Color.BLACK : ColorScheme.LIGHT_GRAY_COLOR);
			g.drawString(label, lx, baseline);
		}
		tabBounds = tabs;
		g.setColor(ColorScheme.BRAND_ORANGE);
		g.fillRect(0, y + tabH, WIDTH, 1);
	}

	// ------------------------------------------------------------------ tab content

	private List<Row> rowsFor(int tab, MonsterData m)
	{
		HighlightMode mode = config.statHighlighting();
		MonsterStats stats = new MonsterStats(m, mode, playerHpLevel.getAsInt(), playerSlayerLevel.getAsInt());
		List<Row> rows = new ArrayList<>();

		switch (tab)
		{
			case 0:
				combatTab(rows, stats, mode);
				break;
			case 1:
				aggressiveTab(rows, stats, mode);
				break;
			case 2:
				defensiveTab(rows, stats, mode);
				break;
			default:
				infoTab(rows, stats, mode);
				break;
		}

		if (rows.isEmpty())
		{
			rows.add(Row.plain("No data.", ColorScheme.LIGHT_GRAY_COLOR));
		}
		return rows;
	}

	private void combatTab(List<Row> rows, MonsterStats stats, HighlightMode mode)
	{
		Color white = Color.WHITE;
		// The combat level is already shown in the title row, so it's not repeated here.
		// A level Bucket can't carry arrives as a range ("270-360"); the overlay has no tooltips, so
		// the footnote explaining it is panel-only.
		List<MonsterStats.StatField> levels = stats.combatLevels();
		if (!levels.isEmpty())
		{
			rows.add(Row.stat(icons.hitpointsIcon, "Hitpoints", levels.get(0).value(), white));
			rows.add(Row.stat(icons.attackIcon, "Attack", levels.get(1).value(), white));
			rows.add(Row.stat(icons.strengthIcon, "Strength", levels.get(2).value(), white));
			rows.add(Row.stat(icons.defenceIcon, "Defence", levels.get(3).value(), white));
			rows.add(Row.stat(icons.magicIcon, "Magic", levels.get(4).value(), white));
			rows.add(Row.stat(icons.rangedIcon, "Ranged", levels.get(5).value(), white));
		}
		rows.add(Row.kv("Speed", stats.attackSpeed(), white));
		rows.add(Row.kvWrap("Style", stats.attackStyle(), white));

		// Max hits: the view-model splits the wiki list (or dataset fallback) and flags any line
		// over the player's HP; in colour-blind mode it also gets a ⚠ glyph (parity with the panel).
		boolean cb = mode == HighlightMode.COLOUR_BLIND;
		boolean firstMax = true;
		for (MonsterStats.MaxHitLine line : stats.maxHits())
		{
			Color c = StatColors.resolve(line.overHp() ? ColourRole.DANGER : ColourRole.NEUTRAL, mode);
			String text = line.text() + (line.overHp() && cb ? " ⚠" : "");
			// Only the first row is labelled "Max hit"; the rest just list their values.
			rows.add(Row.kv(firstMax ? "Max hit" : "", text, c));
			firstMax = false;
		}
	}

	private void aggressiveTab(List<Row> rows, MonsterStats stats, HighlightMode mode)
	{
		Color white = Color.WHITE;
		MonsterStats.StatField pois = stats.poisonous();
		if (pois != null)
		{
			rows.add(Row.kv("Poisonous", pois.value(), StatColors.resolve(pois.role(), mode)));
		}

		List<String> off = stats.offensiveBonuses();
		if (!off.isEmpty())
		{
			rows.add(Row.stat(icons.attackIcon, "Attack", off.get(0), white));
			rows.add(Row.stat(icons.strengthIcon, "Strength", off.get(1), white));
			rows.add(Row.stat(icons.magicIcon, "Magic", off.get(2), white));
			rows.add(Row.stat(icons.magicDamageIcon, "Magic dmg", off.get(3), white));
			rows.add(Row.stat(icons.rangedIcon, "Ranged", off.get(4), white));
			rows.add(Row.stat(icons.rangedStrengthIcon, "Ranged str", off.get(5), white));
		}
	}

	private void defensiveTab(List<Row> rows, MonsterStats stats, HighlightMode mode)
	{
		Color white = Color.WHITE;
		if (stats.hasDefensive())
		{
			// Rolls only when every input is there, so the tab never mixes rolls and bonuses.
			boolean rolls = config.showDefenceRolls() && stats.magicDefenceRoll() != null;
			Map<DefenceRolls.Style, ColourRole> roles = rolls ? stats.defenceRollRoles() : Map.of();
			Function<DefenceRolls.Style, Color> tint = style ->
				StatColors.resolve(roles.getOrDefault(style, ColourRole.NEUTRAL), mode);

			// Grouped like the wiki: melee, then magic defence + elemental weakness, then ranged.
			List<String> melee = rolls ? stats.meleeDefenceRoll() : stats.meleeDefence();
			rows.add(Row.stat(icons.stabIcon, "Stab", melee.get(0), tint.apply(DefenceRolls.Style.STAB)));
			rows.add(Row.stat(icons.slashIcon, "Slash", melee.get(1), tint.apply(DefenceRolls.Style.SLASH)));
			rows.add(Row.stat(icons.crushIcon, "Crush", melee.get(2), tint.apply(DefenceRolls.Style.CRUSH)));

			rows.add(Row.stat(icons.magicDefenceIcon, "Magic", rolls ? stats.magicDefenceRoll() : stats.magicDefence(),
				tint.apply(DefenceRolls.Style.MAGIC)));
			addWeakness(rows, stats, white);

			List<String> ranged = rolls ? stats.rangedDefenceRoll() : stats.rangedDefence();
			rows.add(Row.stat(icons.lightIcon, "Light", ranged.get(0), tint.apply(DefenceRolls.Style.LIGHT)));
			rows.add(Row.stat(icons.standardIcon, "Standard", ranged.get(1), tint.apply(DefenceRolls.Style.STANDARD)));
			rows.add(Row.stat(icons.heavyIcon, "Heavy", ranged.get(2), tint.apply(DefenceRolls.Style.HEAVY)));
		}
		else
		{
			addWeakness(rows, stats, white);
		}
	}

	private void addWeakness(List<Row> rows, MonsterStats stats, Color white)
	{
		String element = stats.weaknessElement();
		if (element != null)
		{
			rows.add(Row.stat(icons.getElementalWeaknessIcon(element),
				StatFormat.cap(element), stats.weaknessSeverity(), white));
		}
		else
		{
			rows.add(Row.kv("Weakness", "—", white));
		}
	}

	private void infoTab(List<Row> rows, MonsterStats stats, HighlightMode mode)
	{
		Color white = Color.WHITE;
		String sizeAttr = stats.sizeAttr();
		if (sizeAttr != null)
		{
			rows.add(Row.plain(sizeAttr, white));
		}
		if (stats.slayerMonster())
		{
			MonsterStats.StatField req = stats.slayerRequirement();
			rows.add(Row.stat(icons.slayerIcon, "Slayer level", req.value(), StatColors.resolve(req.role(), mode)));
			String slayerXp = stats.slayerXp();
			if (slayerXp != null)
			{
				rows.add(Row.stat(icons.slayerXpIcon, "Slayer XP", slayerXp, white));
			}
			List<String> categories = stats.slayerCategories();
			if (!categories.isEmpty())
			{
				rows.add(Row.kvWrap("Category", String.join(", ", categories), white));
			}
			List<BufferedImage> heads = new ArrayList<>();
			for (String master : stats.slayerMasters())
			{
				BufferedImage head = icons.masterIcon(master);
				if (head != null)
				{
					heads.add(head);
				}
			}
			if (!heads.isEmpty())
			{
				rows.add(Row.icons("Assigned by", heads));
			}
		}
		// Flat armour: a flat damage adjustment, 0 for most monsters — shown only when non-zero,
		// green when negative (takes extra damage), red when positive (shrugs damage off).
		MonsterStats.StatField flatArmour = stats.flatArmour();
		if (flatArmour != null)
		{
			rows.add(Row.kv("Flat armour", flatArmour.value(), StatColors.resolve(flatArmour.role(), mode)));
		}
		MonsterStats.StatField xp = stats.xpBonus();
		if (xp != null)
		{
			rows.add(Row.kv("XP bonus", xp.value(), StatColors.resolve(xp.role(), mode)));
		}

		String burn = stats.burn();
		if (burn != null)
		{
			rows.add(Row.kv("Burn", burn, white));
		}
		MonsterStats.StatField cannon = stats.cannon();
		if (cannon != null)
		{
			rows.add(Row.kv("Cannon", cannon.value(), StatColors.resolve(cannon.role(), mode)));
		}
		MonsterStats.StatField thrall = stats.thrall();
		if (thrall != null)
		{
			rows.add(Row.kv("Thrall", thrall.value(), StatColors.resolve(thrall.role(), mode)));
		}
	}

	private static String truncate(FontMetrics fm, String s, int maxW)
	{
		if (fm.stringWidth(s) <= maxW)
		{
			return s;
		}
		String ellipsis = "…";
		int ellW = fm.stringWidth(ellipsis);
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < s.length(); i++)
		{
			if (fm.stringWidth(sb.toString() + s.charAt(i)) + ellW > maxW)
			{
				break;
			}
			sb.append(s.charAt(i));
		}
		return sb.append(ellipsis).toString();
	}

	private static List<String> wrap(String text, FontMetrics fm, int maxW)
	{
		return wrap(text, fm, maxW, maxW);
	}

	/** Word-wrap, allowing a narrower first line (e.g. to leave room for an inline label). */
	private static List<String> wrap(String text, FontMetrics fm, int firstW, int restW)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		int maxW = firstW;
		for (String word : text.split(" "))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) > maxW && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
				maxW = restW;
			}
			else
			{
				line = new StringBuilder(candidate);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	/**
	 * One line of tab content. A {@code kv} row is "label … value" on a single line; a {@code stat}
	 * row swaps the text label for an {@code icon} on the left; a {@code kvWrap} row keeps the
	 * label inline but lets the value wrap across several right-aligned lines; a {@code plain} row
	 * is a label-less wrapping value (for long text like the attribute list).
	 */
	private static final class Row
	{
		/** Gap between chatheads in an {@code icons} strip. */
		private static final int STRIP_GAP = 2;

		private final String label;
		private final BufferedImage icon;
		private final String value;
		private final Color color;
		private final boolean wrap;
		/** When wrapping, right-align the value lines and keep the label inline (vs. its own line). */
		private final boolean rightWrap;
		/** A wrapped row of icons drawn under the label (Slayer master chatheads); null otherwise. */
		private final List<BufferedImage> iconStrip;

		private Row(String label, BufferedImage icon, String value, Color color, boolean wrap, boolean rightWrap)
		{
			this.label = label;
			this.icon = icon;
			this.value = value;
			this.color = color;
			this.wrap = wrap;
			this.rightWrap = rightWrap;
			this.iconStrip = null;
		}

		private Row(String label, List<BufferedImage> iconStrip)
		{
			this.label = label;
			this.icon = null;
			this.value = null;
			this.color = Color.WHITE;
			this.wrap = false;
			this.rightWrap = false;
			this.iconStrip = iconStrip;
		}

		static Row kv(String label, String value, Color color)
		{
			return new Row(label, null, value, color, false, false);
		}

		static Row stat(BufferedImage icon, String label, String value, Color color)
		{
			return new Row(label, icon, value, color, false, false);
		}

		static Row kvWrap(String label, String value, Color color)
		{
			return new Row(label, null, value, color, true, true);
		}

		static Row plain(String value, Color color)
		{
			return new Row(null, null, value, color, true, false);
		}

		static Row icons(String label, List<BufferedImage> iconStrip)
		{
			return new Row(label, iconStrip);
		}

		/** Chatheads per row for the width available to an icon strip. */
		private int perRow(int contentW)
		{
			return Math.max(1, (contentW + STRIP_GAP) / (ICON_SIZE + STRIP_GAP));
		}

		int height(FontMetrics fm, int contentW, int lineH)
		{
			if (iconStrip != null)
			{
				int stripRows = (iconStrip.size() + perRow(contentW) - 1) / perRow(contentW);
				return lineH + stripRows * (ICON_SIZE + STRIP_GAP);
			}
			if (icon != null)
			{
				return Math.max(lineH, ICON_SIZE);
			}
			if (!wrap)
			{
				return lineH;
			}
			if (rightWrap)
			{
				int firstW = contentW - (label != null ? fm.stringWidth(label) + LABEL_GAP : 0);
				return wrap(value, fm, firstW, contentW).size() * lineH;
			}
			int lines = label != null ? 1 : 0;
			lines += wrap(value, fm, contentW).size();
			return lines * lineH;
		}

		int draw(Graphics2D g, FontMetrics fm, int x, int y, int contentW, int lineH)
		{
			if (iconStrip != null)
			{
				g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				g.drawString(label, x, y + fm.getAscent());
				int perRow = perRow(contentW);
				int ix = x;
				int iy = y + lineH;
				int col = 0;
				for (BufferedImage head : iconStrip)
				{
					drawIcon(g, head, ix, iy, ICON_SIZE);
					ix += ICON_SIZE + STRIP_GAP;
					if (++col == perRow)
					{
						col = 0;
						ix = x;
						iy += ICON_SIZE + STRIP_GAP;
					}
				}
				int stripRows = (iconStrip.size() + perRow - 1) / perRow;
				return lineH + stripRows * (ICON_SIZE + STRIP_GAP);
			}

			if (icon != null)
			{
				int rowH = Math.max(lineH, ICON_SIZE);
				int baseline = y + (rowH + fm.getAscent() - fm.getDescent()) / 2;
				drawIcon(g, icon, x, y, rowH);
				if (label != null)
				{
					g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
					g.drawString(label, x + ICON_SIZE + 4, baseline);
				}
				g.setColor(color);
				g.drawString(value, x + contentW - fm.stringWidth(value), baseline);
				return rowH;
			}

			if (!wrap)
			{
				g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				g.drawString(label, x, y + fm.getAscent());
				g.setColor(color);
				g.drawString(value, x + contentW - fm.stringWidth(value), y + fm.getAscent());
				return lineH;
			}

			if (rightWrap)
			{
				// Label stays on the first line at the left; the value wraps across right-aligned
				// lines (the first leaving room for the label), keeping a multi-style list tight.
				int firstW = contentW - (label != null ? fm.stringWidth(label) + LABEL_GAP : 0);
				if (label != null)
				{
					g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
					g.drawString(label, x, y + fm.getAscent());
				}
				g.setColor(color);
				int yy = y;
				for (String ln : wrap(value, fm, firstW, contentW))
				{
					g.drawString(ln, x + contentW - fm.stringWidth(ln), yy + fm.getAscent());
					yy += lineH;
				}
				return Math.max(lineH, yy - y);
			}

			int yy = y;
			if (label != null)
			{
				g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				g.drawString(label, x, yy + fm.getAscent());
				yy += lineH;
			}
			g.setColor(color);
			for (String ln : wrap(value, fm, contentW))
			{
				g.drawString(ln, x, yy + fm.getAscent());
				yy += lineH;
			}
			return yy - y;
		}

		/** Draw {@code img} scaled to fit {@link #ICON_SIZE} (preserving aspect), vertically centred. */
		private static void drawIcon(Graphics2D g, BufferedImage img, int x, int y, int rowH)
		{
			double scale = Math.min((double) ICON_SIZE / img.getWidth(), (double) ICON_SIZE / img.getHeight());
			int w = Math.max(1, (int) Math.round(img.getWidth() * scale));
			int h = Math.max(1, (int) Math.round(img.getHeight() * scale));
			g.drawImage(img, x, y + (rowH - h) / 2, w, h, null);
		}
	}
}

package com.bettermonsterexamine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * The neutral view-model behind both renderers ({@link MonsterCard} and
 * {@link MonsterCardOverlay}): given a monster, the highlight mode and the player's Hitpoints
 * level, it resolves <em>which fields to show, their values, and their {@link ColourRole}</em> —
 * with zero rendering. It owns the content/semantics that were previously duplicated across the
 * panel's {@code buildWiki} and the overlay's tab builders; the renderers keep their own labels,
 * icons and layout and read values/roles from here.
 *
 * <p>Pure and immutable — built per render from current state on whichever thread is rendering
 * (panel: EDT; overlay: client thread), so it never shares mutable state across threads. Since the
 * cutover to the single Bucket dataset every field is present synchronously; there is no async
 * "wiki fields land later" path any more.
 */
final class MonsterStats
{
	/** A resolved field: a display value with a semantic colour role and optional tooltip. */
	static final class StatField
	{
		private final String value;
		private final ColourRole role;
		private final String tooltip;

		StatField(String value, ColourRole role, String tooltip)
		{
			this.value = value;
			this.role = role;
			this.tooltip = tooltip;
		}

		String value()
		{
			return value;
		}

		ColourRole role()
		{
			return role;
		}

		/** Tooltip text, or null. */
		String tooltip()
		{
			return tooltip;
		}
	}

	/** One max-hit line plus whether it should be flagged as exceeding the player's HP. */
	static final class MaxHitLine
	{
		private final String text;
		private final boolean overHp;

		MaxHitLine(String text, boolean overHp)
		{
			this.text = text;
			this.overHp = overHp;
		}

		String text()
		{
			return text;
		}

		boolean overHp()
		{
			return overHp;
		}
	}

	private final MonsterData m;
	private final HighlightMode mode;
	private final int playerHpLevel;
	private final int playerSlayerLevel;

	MonsterStats(MonsterData m, HighlightMode mode, int playerHpLevel, int playerSlayerLevel)
	{
		this.m = m;
		this.mode = mode;
		this.playerHpLevel = playerHpLevel;
		this.playerSlayerLevel = playerSlayerLevel;
	}

	// ---- Attributes / Info ---------------------------------------------------

	/** Size and attribute names on one line, e.g. {@code "7x7, Draconic, Undead"}; null if none. */
	String sizeAttr()
	{
		String sizeText = m.getSize() > 0 ? m.getSize() + "x" + m.getSize() : null;
		String attrText = !m.getAttributes().isEmpty() ? StatFormat.attributeNames(m.getAttributes()) : null;
		return StatFormat.join(", ", sizeText, attrText);
	}

	boolean slayerMonster()
	{
		return m.isSlayerMonster();
	}

	/**
	 * Required Slayer level to damage the monster (the wiki shows {@code 1} when there is no real
	 * requirement). Flagged {@link ColourRole#DANGER} when the player's Slayer level is known and
	 * below it — you can't harm it yet. Only meaningful on a Slayer monster.
	 */
	StatField slayerRequirement()
	{
		int req = Math.max(1, m.getSlayerLevel());
		boolean tooLow = playerSlayerLevel > 0 && playerSlayerLevel < req;
		return new StatField(String.valueOf(req), tooLow ? ColourRole.DANGER : ColourRole.NEUTRAL,
			req > 1 ? "Requires Slayer level " + req + " to damage." : null);
	}

	/** Slayer XP awarded per kill, without a trailing {@code .0}; null when absent. */
	String slayerXp()
	{
		double xp = m.getSlayerExperience();
		return xp > 0 ? StatFormat.number(xp) : null;
	}

	/**
	 * The Slayer assignment categories, cleaned of wiki markers and de-junked (Bucket carries a few
	 * {@code "No"}/{@code "None"} placeholders and the odd strip-marker), deduplicated in order.
	 * Empty when none. E.g. {@code ["Blue dragons","Bosses"]}.
	 */
	List<String> slayerCategories()
	{
		List<String> c = m.getSlayerCategory();
		if (c == null)
		{
			return Collections.emptyList();
		}
		List<String> out = new ArrayList<>();
		for (String raw : c)
		{
			String clean = WikiSanitizer.text(raw);
			if (clean == null || clean.isEmpty() || clean.equalsIgnoreCase("no") || clean.equalsIgnoreCase("none"))
			{
				continue;
			}
			if (!out.contains(clean))
			{
				out.add(clean);
			}
		}
		return out;
	}

	/**
	 * The Slayer masters who assign it, as normalised lower-case keys (e.g. {@code ["duradel","nieve"]}),
	 * deduplicated in order — Bucket carries mixed casing and a few junk values. Empty when none.
	 */
	List<String> slayerMasters()
	{
		List<String> a = m.getAssignedBy();
		if (a == null)
		{
			return Collections.emptyList();
		}
		List<String> out = new ArrayList<>();
		for (String raw : a)
		{
			String key = normaliseMaster(raw);
			if (key != null && !out.contains(key))
			{
				out.add(key);
			}
		}
		return out;
	}

	/** Lower-case a raw {@code assigned_by} value to a master key, folding Konar's full name and dropping junk. */
	static String normaliseMaster(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		String key = raw.trim().toLowerCase(Locale.ROOT);
		if (key.isEmpty() || key.equals("no") || key.equals("none"))
		{
			return null;
		}
		return key.startsWith("konar") ? "konar" : key;
	}

	/** Flat-armour adjustment; null when zero. Negative (takes extra damage) is good, positive bad. */
	StatField flatArmour()
	{
		int fa = m.getFlatArmour();
		if (fa == 0)
		{
			return null;
		}
		return new StatField(String.valueOf(fa), fa < 0 ? ColourRole.GOOD : ColourRole.DANGER,
			fa < 0 ? "Takes extra flat damage per hit." : "Reduces damage taken per hit.");
	}

	/** XP bonus, e.g. {@code "+77.5%"} / {@code "-50%"}; null when absent or zero. */
	StatField xpBonus()
	{
		double xp = m.getExperienceBonus();
		if (xp == 0)
		{
			return null;
		}
		boolean penalty = xp < 0;
		return new StatField((penalty ? "" : "+") + StatFormat.number(xp) + "%",
			penalty ? ColourRole.DANGER : ColourRole.GOOD, null);
	}

	/** Poisonous flag; null when the field is absent. */
	StatField poisonous()
	{
		String pois = m.getPoisonous();
		if (pois == null || pois.isEmpty())
		{
			return null;
		}
		boolean yes = StatFormat.affirmative(pois);
		return new StatField(pois, yes ? ColourRole.DANGER : ColourRole.NEUTRAL,
			yes ? "Can poison you." : null);
	}

	/** Examine text, or null. */
	String examine()
	{
		String ex = m.getExamine();
		return ex == null || ex.isEmpty() ? null : ex;
	}

	// ---- Combat info ---------------------------------------------------------

	/** Attack styles joined, or an em dash. */
	String attackStyle()
	{
		List<String> st = m.getAttackStyles();
		return st.isEmpty() ? "—" : String.join(", ", st);
	}

	String attackSpeed()
	{
		return StatFormat.attackSpeed(m);
	}

	// ---- Max hit -------------------------------------------------------------

	/**
	 * The max-hit list, one entry per value (Bucket returns them already split; the sanitizer
	 * cleans each). Each line is flagged when its value exceeds the player's Hitpoints level (and
	 * highlighting is on). An em dash stands in when the monster carries no max-hit data.
	 */
	List<MaxHitLine> maxHits()
	{
		List<String> lines = m.getMaxHitLines();
		boolean flag = mode != HighlightMode.OFF && playerHpLevel > 0;
		List<MaxHitLine> out = new ArrayList<>();
		if (lines.isEmpty())
		{
			out.add(new MaxHitLine("—", false));
			return out;
		}
		for (String line : lines)
		{
			out.add(new MaxHitLine(line, flag && StatFormat.maxValue(line) > playerHpLevel));
		}
		return out;
	}

	// ---- Stat grids (values only; renderers supply icons + labels) -----------

	/** Combat levels in icon order [Hitpoints, Attack, Strength, Defence, Magic, Ranged]. */
	List<StatField> combatLevels()
	{
		List<StatField> v = new ArrayList<>(6);
		v.add(level(m.getHitpoints(), null));
		v.add(level(m.getAttackLevel(), "attack_level"));
		v.add(level(m.getStrengthLevel(), "strength_level"));
		v.add(level(m.getDefenceLevel(), "defence_level"));
		v.add(level(m.getMagicLevel(), "magic_level"));
		v.add(level(m.getRangedLevel(), "ranged_level"));
		return v;
	}

	/**
	 * One combat level. Bucket's INTEGER columns cannot hold a level the wiki writes as a range —
	 * Vardorvis' Strength and Defence scale with his remaining HP ("270-360") — so the service
	 * recovers those from the page wikitext and they arrive here as text instead of a number. The
	 * wiki's own footnote rides along as the tooltip: a Defence that counts <em>down</em> (215-145)
	 * otherwise reads as a bug rather than the mechanic it is.
	 */
	private StatField level(int value, String bucketField)
	{
		InfoboxLevels.LevelText range = bucketField == null ? null : m.getLevelRange(bucketField);
		if (value <= 0 && range != null)
		{
			return new StatField(range.getValue(), ColourRole.NEUTRAL, range.getNote());
		}
		return new StatField(StatFormat.num(value), ColourRole.NEUTRAL, null);
	}

	/** Offensive bonuses in icon order [Attack, Strength, Magic, Magic dmg, Ranged, Ranged str]. */
	List<String> offensiveBonuses()
	{
		List<String> v = new ArrayList<>(6);
		v.add(StatFormat.bonus(m.getAttackBonus()));
		v.add(StatFormat.bonus(m.getStrengthBonus()));
		v.add(StatFormat.bonus(m.getMagicAttackBonus()));
		v.add(StatFormat.bonus(m.getMagicDamageBonus()));
		v.add(StatFormat.bonus(m.getRangeAttackBonus()));
		v.add(StatFormat.bonus(m.getRangeStrengthBonus()));
		return v;
	}

	/** Bucket always carries the defensive bonus fields, so the defence grids always render. */
	boolean hasDefensive()
	{
		return true;
	}

	/** Melee defence bonuses [Stab, Slash, Crush]. */
	List<String> meleeDefence()
	{
		List<String> v = new ArrayList<>(3);
		v.add(StatFormat.bonus(m.getStabDefenceBonus()));
		v.add(StatFormat.bonus(m.getSlashDefenceBonus()));
		v.add(StatFormat.bonus(m.getCrushDefenceBonus()));
		return v;
	}

	/** Magic-defence bonus. */
	String magicDefence()
	{
		return StatFormat.bonus(m.getMagicDefenceBonus());
	}

	/** Ranged defence bonuses [Light, Standard, Heavy]. */
	List<String> rangedDefence()
	{
		List<String> v = new ArrayList<>(3);
		v.add(StatFormat.bonus(m.getLightRangeDefenceBonus()));
		v.add(StatFormat.bonus(m.getStandardRangeDefenceBonus()));
		v.add(StatFormat.bonus(m.getHeavyRangeDefenceBonus()));
		return v;
	}

	/**
	 * Melee defence rolls [Stab, Slash, Crush], or null when the wiki lacks an input — the
	 * renderers then fall back to the bonuses.
	 */
	List<String> meleeDefenceRoll()
	{
		return rolls(DefenceRolls.Style.STAB, DefenceRolls.Style.SLASH, DefenceRolls.Style.CRUSH);
	}

	/** Magic defence roll, or null when the wiki lacks an input. */
	String magicDefenceRoll()
	{
		List<String> v = rolls(DefenceRolls.Style.MAGIC);
		return v == null ? null : v.get(0);
	}

	/** Ranged defence rolls [Light, Standard, Heavy], or null when the wiki lacks an input. */
	List<String> rangedDefenceRoll()
	{
		return rolls(DefenceRolls.Style.LIGHT, DefenceRolls.Style.STANDARD, DefenceRolls.Style.HEAVY);
	}

	/**
	 * Which defence rolls to highlight, by the same ranking as the chat summary's Weakness line:
	 * its first answer {@link ColourRole#GOOD}, the free style it names second {@link ColourRole#NEXT}.
	 * Styles it doesn't name are absent, as is everything when no style stands out.
	 */
	Map<DefenceRolls.Style, ColourRole> defenceRollRoles()
	{
		return DefenceRolls.roles(m);
	}

	private List<String> rolls(DefenceRolls.Style... styles)
	{
		if (!m.hasDefenceRollInputs())
		{
			return null;
		}
		Map<DefenceRolls.Style, Integer> rolls = DefenceRolls.rolls(m);
		List<String> v = new ArrayList<>(styles.length);
		for (DefenceRolls.Style style : styles)
		{
			v.add(StatFormat.roll(rolls.get(style)));
		}
		return v;
	}

	/** The elemental weakness element (e.g. {@code "Fire"}), or null if none. */
	String weaknessElement()
	{
		String e = m.getWeaknessElement();
		return e == null || e.isEmpty() ? null : e;
	}

	/** The weakness severity as {@code "N%"}, or an em dash when there is no weakness. */
	String weaknessSeverity()
	{
		return weaknessElement() != null ? m.getWeaknessPercent() + "%" : "—";
	}

	// ---- Immunities ----------------------------------------------------------

	/** Burn-immunity label (e.g. {@code "Immune (weak)"}), or null. */
	String burn()
	{
		return m.getBurnLabel();
	}

	/** Cannon immunity, as a danger field; null when not immune. */
	StatField cannon()
	{
		return MonsterData.isImmune(m.getCannonImmune()) ? new StatField("Immune", ColourRole.DANGER, null) : null;
	}

	/** Thrall immunity, as a danger field; null when not immune. */
	StatField thrall()
	{
		return MonsterData.isImmune(m.getThrallImmune()) ? new StatField("Immune", ColourRole.DANGER, null) : null;
	}
}

package com.bettermonsterexamine;

import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/**
 * The outbound half of the Not Enough Runes link: hands an item off to that plugin's panel.
 *
 * <p>Plugin-hub plugins each load in their own classloader, parented to the client's, so NER's
 * classes are invisible from here — its plugin type can't be named, and a shared event class would
 * be a different {@code Class} on each side and never dispatch. The only channel is the core
 * {@link PluginMessage} event: a namespace, a name, and a map of core types. NER already subscribes
 * to {@code notenoughrunes}/{@code displayItemById} with an {@code Integer} {@code itemId}.
 *
 * <p>Posting when NER is absent is harmless (the event simply has no subscribers), so
 * {@link #isActive()} exists to decide what the UI should <em>offer</em>, not to make the post safe.
 */
@Slf4j
public class NotEnoughRunesLink
{
	/** Matched by name because the class itself can't be referenced across the classloader boundary. */
	private static final String PLUGIN_CLASS = "com.notenoughrunes.NotEnoughRunesPlugin";
	private static final String NAMESPACE = "notenoughrunes";
	private static final String DISPLAY_ITEM_BY_ID = "displayItemById";
	private static final String ITEM_ID = "itemId";
	/**
	 * Asks NER to land on its Uses tab: arriving from a drop, the question is almost always "what is
	 * this for?". Agreed with NER's author but <strong>not read on her side yet</strong> — an unknown
	 * key is ignored by her handler, so sending it now costs nothing and means the behaviour switches
	 * on with her release instead of needing both plugins to ship together.
	 */
	private static final String OPEN_USES = "openUses";

	private final EventBus eventBus;
	private final PluginManager pluginManager;
	private final BetterMonsterExamineConfig config;

	public NotEnoughRunesLink(EventBus eventBus, PluginManager pluginManager, BetterMonsterExamineConfig config)
	{
		this.eventBus = eventBus;
		this.pluginManager = pluginManager;
		this.config = config;
	}

	/**
	 * True when the link is switched on and NER is running, so a post would actually be received.
	 * Resolved per call rather than cached, so installing or enabling NER mid-session takes effect
	 * without a restart.
	 */
	public boolean isActive()
	{
		return config.notEnoughRunesLink() && isRunning();
	}

	/**
	 * True when the link is switched on but NER isn't there to receive it, so clicks quietly fall back
	 * to the wiki. Worth saying out loud in the UI: covers not installed, disabled, and disabled
	 * mid-session alike, all of which otherwise look like the link is simply broken.
	 */
	public boolean isUnavailable()
	{
		return config.notEnoughRunesLink() && !isRunning();
	}

	/**
	 * Ask NER to show this item. No-op when the link is inactive.
	 *
	 * <p>Call from the EDT: {@link EventBus#post} runs subscribers inline on the calling thread, and
	 * NER's handler touches Swing.
	 */
	public void displayItem(int itemId)
	{
		if (!isActive())
		{
			return;
		}
		log.debug("Handing item {} to Not Enough Runes", itemId);
		Map<String, Object> data = new HashMap<>();
		data.put(ITEM_ID, itemId);
		data.put(OPEN_USES, true);
		eventBus.post(new PluginMessage(NAMESPACE, DISPLAY_ITEM_BY_ID, data));
	}

	/**
	 * Whether NER is loaded <em>and started</em>. Deliberately not {@code isPluginEnabled}, which only
	 * reads the "start this on boot" config flag — a plugin is registered with the event bus in
	 * {@code startPlugin}, so {@code isPluginActive} is what predicts delivery.
	 */
	private boolean isRunning()
	{
		// getPlugins() is a CopyOnWriteArrayList, so iterating it off the client thread is safe.
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (PLUGIN_CLASS.equals(plugin.getClass().getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}
}

package com.bettermonsterexamine.loot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * A monster's drops grouped into the wiki's own drop-table sections, <b>in the order the wiki page
 * lists them</b> — 100% / Weapons and armour / Runes / Herbs / Gem drop table / Rare drop table /
 * Catacombs tertiary / Wilderness Slayer Cave tertiary / Tertiary / … . The labels and their order
 * come straight from the parsed page headings; nothing here is inferred, so the grouping matches what
 * a player sees on the wiki.
 *
 * <p>Sections nest inside a {@link Group}, mirroring the page's two heading levels. Most monsters have
 * a single unlabelled group holding every section, but where the wiki splits a monster's drops by
 * location or combat level — Cyclops (Warriors' Guild top floor vs basement), Abyssal demon (Catacombs
 * vs Wilderness Slayer Cave), Giant frog (level 13 vs 99) — each of those becomes its own group.
 * Keeping them apart is load-bearing: the same section name ({@code "100%"}, {@code "Herbs"}) recurs
 * under each with <b>different</b> drops and rates, so flattening them merges tables that a player
 * never sees together and implies drops a monster doesn't have.
 */
@Getter
public class DropTable
{
	private final List<Group> groups;

	private DropTable(List<Group> groups)
	{
		this.groups = groups;
	}

	public boolean isEmpty()
	{
		return groups.isEmpty();
	}

	/**
	 * Group parsed rows by their group, then their section, preserving the wiki page's order at both
	 * levels (first-seen) and the row order within each section. Sections are only merged within the
	 * same group, so like-named tables under different groups stay distinct. Pure over its argument,
	 * so the grouping is unit-testable.
	 */
	public static DropTable of(List<DropRow> rows)
	{
		Map<String, Map<String, List<DropRow>>> byGroup = new LinkedHashMap<>();
		for (DropRow row : rows)
		{
			String group = row.getGroup() == null ? "" : row.getGroup();
			String section = row.getSection() == null || row.getSection().isEmpty() ? "Other" : row.getSection();
			byGroup.computeIfAbsent(group, k -> new LinkedHashMap<>())
				.computeIfAbsent(section, k -> new ArrayList<>())
				.add(row);
		}

		List<Group> built = new ArrayList<>(byGroup.size());
		for (Map.Entry<String, Map<String, List<DropRow>>> g : byGroup.entrySet())
		{
			List<Section> sections = new ArrayList<>(g.getValue().size());
			for (Map.Entry<String, List<DropRow>> s : g.getValue().entrySet())
			{
				sections.add(new Section(s.getKey(), Collections.unmodifiableList(s.getValue())));
			}
			built.add(new Group(g.getKey(), Collections.unmodifiableList(sections)));
		}
		return new DropTable(Collections.unmodifiableList(built));
	}

	/**
	 * One location/combat-level grouping of drop tables, or the single unlabelled group ({@code ""})
	 * holding every section on a page that doesn't split its drops.
	 */
	@Getter
	@RequiredArgsConstructor
	public static final class Group
	{
		private final String label;
		private final List<Section> sections;
	}

	/** One drop-table section: its wiki heading and the rows under it, in page order. */
	@Getter
	@RequiredArgsConstructor
	public static final class Section
	{
		private final String label;
		private final List<DropRow> rows;
	}
}

package com.bettermonsterexamine.loot;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.UnsupportedEncodingException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Provides a monster's drop tables on demand by parsing its <b>rendered OSRS Wiki page</b> (the
 * MediaWiki {@code action=parse} API), grouping rows under the wiki's own section headings. This is
 * the only source that carries the wiki's editorial drop tables — Herbs, Gem/Rare drop table,
 * <b>Catacombs of Kourend</b> and <b>Wilderness Slayer Cave</b> tables, Tertiary, … — which the
 * structured drop data cannot express (it carries no section field, and can't even see the region
 * tables).
 *
 * <p>Fetched <b>per monster</b> the first time it's looked up and cached under
 * {@code .runelite/better-monster-examine/droppages/}, refreshed weekly ({@link #MAX_AGE}) — the same
 * on-demand-per-page pattern the drops fetch always used, just from the page instead of the bucket.
 * All loading happens off the client thread and EDT; {@link #tableFor} reads the concurrent by-page
 * index without blocking and returns null until a page lands. Item icon / GE price / High Alch are
 * <b>not</b> parsed here — they come from the RuneLite client by item id at render time.
 */
@Slf4j
@Singleton
public class DropPageService
{
	private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT = "better-monster-examine (RuneLite plugin)";
	private static final File CACHE_DIR = new File(RuneLite.RUNELITE_DIR, "better-monster-examine/droppages");
	private static final Duration MAX_AGE = Duration.ofDays(7);

	// Drop-table structure on a rendered monster page (see the Drops section):
	//   <tr> [inventory-image] [item-col: <a href="/w/Item">] [qty] [table-bg-*: rarity] [ge] [alch]
	// Rows inherit the <h3>/<h4> section heading above them; a drops <h2> region runs to the next <h2>.
	private static final Pattern H2 = Pattern.compile("<h2[^>]*>(.*?)</h2>", Pattern.DOTALL);
	private static final Pattern HEADING = Pattern.compile("<h([34])[^>]*\\sid=\"[^\"]+\"[^>]*>(.*?)</h\\1>", Pattern.DOTALL);
	private static final Pattern ROW = Pattern.compile("<tr[^>]*>(.*?)</tr>", Pattern.DOTALL);
	private static final Pattern ITEM = Pattern.compile("class=\"item-col\"[^>]*>.*?<a href=\"/w/([^\"?#]+)\"", Pattern.DOTALL);
	private static final Pattern TD = Pattern.compile("<td([^>]*)>(.*?)</td>", Pattern.DOTALL);
	private static final Pattern TAG = Pattern.compile("<[^>]+>");
	private static final Pattern NUMERIC_ENTITY = Pattern.compile("&#(\\d+);");
	private static final Pattern FOOTNOTE = Pattern.compile("\\[[^\\]]*\\]");
	// Each rarity value is wrapped in a span carrying every form of the odds; the element's own text is
	// the raw source fraction ("16/100") and data-drop-oneover is the 1/x the wiki actually shows.
	private static final Pattern ONE_OVER =
		Pattern.compile("<span[^>]*data-drop-oneover=\"([^\"]*)\"[^>]*>.*?</span>", Pattern.DOTALL);

	private final Gson gson;
	private final OkHttpClient http;
	private final ScheduledExecutorService executor;

	/** lower-case page name -> that page's parsed drop rows; an entry means "loaded". */
	private final Map<String, List<DropRow>> byPage = new ConcurrentHashMap<>();
	/** Pages with a fetch in flight, so concurrent requests coalesce into one network call. */
	private final Set<String> loading = ConcurrentHashMap.newKeySet();

	private volatile Consumer<String> updateListener;

	@Inject
	DropPageService(Gson gson, OkHttpClient http, ScheduledExecutorService executor)
	{
		this.gson = gson;
		this.http = http;
		this.executor = executor;
	}

	/** Set the callback fired (on a background thread) with a page name once its drops are published. */
	public void setUpdateListener(Consumer<String> listener)
	{
		this.updateListener = listener;
	}

	/**
	 * Ensure this page's drops are loaded, fetching them off-thread if needed. Safe to call from the
	 * client thread or EDT; returns immediately. A no-op once the page is loaded or already loading.
	 */
	public void request(String pageName)
	{
		if (pageName == null || pageName.isEmpty())
		{
			return;
		}
		String key = pageName.toLowerCase(Locale.ROOT);
		if (byPage.containsKey(key) || !loading.add(key))
		{
			return;
		}
		executor.execute(() -> load(pageName, key));
	}

	/**
	 * The drop table for a page — the wiki's sections in page order — or null when the page isn't
	 * loaded yet (call {@link #request} first and react via the update listener). A loaded page with no
	 * drops yields an empty table, never null.
	 */
	public DropTable tableFor(String pageName)
	{
		List<DropRow> rows = byPage.get(pageName.toLowerCase(Locale.ROOT));
		return rows == null ? null : DropTable.of(rows);
	}

	/** True once this page's drops have been loaded (from cache or network), so reads return real data. */
	public boolean isLoaded(String pageName)
	{
		return byPage.containsKey(pageName.toLowerCase(Locale.ROOT));
	}

	/**
	 * Load one page: serve a fresh cache immediately, otherwise fetch. A stale cache still publishes
	 * first (so the page stays usable offline) before the refresh lands. Runs on the executor.
	 */
	private void load(String pageName, String key)
	{
		File cacheFile = cacheFileFor(key);
		boolean haveCache = false;
		if (cacheFile.isFile())
		{
			try (Reader r = Files.newBufferedReader(cacheFile.toPath(), StandardCharsets.UTF_8))
			{
				List<DropRow> rows = parse(htmlOf(gson.fromJson(r, ParseResponse.class)));
				if (rows != null)
				{
					publish(key, rows, pageName);
					haveCache = true;
				}
			}
			catch (Exception e)
			{
				log.debug("Failed to read cached drop page for {}", pageName, e);
			}
		}

		boolean fresh = haveCache && (System.currentTimeMillis() - cacheFile.lastModified()) < MAX_AGE.toMillis();
		if (fresh)
		{
			loading.remove(key);
		}
		else
		{
			fetch(pageName, key, cacheFile);
		}
	}

	/**
	 * Fetch and parse the monster's wiki page synchronously on the executor thread — never the client
	 * thread or EDT — then publish and cache it. A failed request leaves any served stale cache in place.
	 */
	private void fetch(String pageName, String key, File cacheFile)
	{
		try
		{
			HttpUrl url = HttpUrl.get(API_URL).newBuilder()
				.addQueryParameter("action", "parse")
				.addQueryParameter("page", pageName)
				.addQueryParameter("prop", "text")
				.addQueryParameter("format", "json")
				// Follow redirects: plenty of monster names are redirect pages ("Hill giant" →
				// "Hill Giant"), and without this we'd parse the redirect stub and show no drops.
				.addQueryParameter("redirects", "1")
				.build();
			Request req = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
			try (Response res = http.newCall(req).execute())
			{
				if (!res.isSuccessful() || res.body() == null)
				{
					log.debug("Drop page fetch for {} returned {}", pageName, res.code());
					return;
				}
				String json = res.body().string();
				String html = htmlOf(gson.fromJson(json, ParseResponse.class));
				List<DropRow> rows = parse(html);
				if (rows == null)
				{
					log.debug("Drop page for {} carried no rendered text", pageName);
					return;
				}
				// Parse (and publish) before caching so a corrupt download never poisons the cache.
				publish(key, rows, pageName);
				writeCache(cacheFile, json);
				log.debug("Parsed and cached {} drop rows for {}", rows.size(), pageName);
			}
		}
		catch (Exception e)
		{
			log.debug("Drop page fetch/parse failed for {}", pageName, e);
		}
		finally
		{
			loading.remove(key);
		}
	}

	private void publish(String key, List<DropRow> rows, String pageName)
	{
		byPage.put(key, rows);
		Consumer<String> listener = updateListener;
		if (listener != null)
		{
			listener.accept(pageName);
		}
	}

	private static String htmlOf(ParseResponse response)
	{
		if (response == null || response.parse == null || response.parse.text == null)
		{
			return null;
		}
		return response.parse.text.star;
	}

	/**
	 * Parse a rendered wiki page's HTML into ordered drop rows, each tagged with the section heading it
	 * sits under. Restricted to the page's <b>drops {@code <h2>} region(s)</b> — a single "Drops"
	 * heading, or, for combat-level variants, several "Level <i>N</i> drops" headings each with their own
	 * 100% / Tertiary / … subsections (e.g. Giant frog). Each region runs to the next {@code <h2>}. Null
	 * when there's no HTML; empty when the page has no drops section. Pure, so it's unit-testable.
	 */
	static List<DropRow> parse(String html)
	{
		if (html == null)
		{
			return null;
		}

		// Locate every <h2> so a drops region can be cut from its heading to the next <h2> of any kind.
		List<Heading2> h2s = new ArrayList<>();
		Matcher h2m = H2.matcher(html);
		while (h2m.find())
		{
			h2s.add(new Heading2(h2m.end(), clean(h2m.group(1))));
		}

		// Drop tables live under an <h2> whose title mentions "drops" — one generic "Drops" heading on
		// most pages, or per-level headings on combat-level variants. Anything else (store, spawns, …) is
		// ignored, so unrelated tables never surface as bogus drops (we fail closed when there are none).
		List<DropRow> out = new ArrayList<>();
		for (int i = 0; i < h2s.size(); i++)
		{
			Heading2 h2 = h2s.get(i);
			if (!h2.title.toLowerCase(Locale.ROOT).contains("drop"))
			{
				continue;
			}
			int end = i + 1 < h2s.size() ? h2s.get(i + 1).start : html.length();
			parseRegion(html.substring(h2.start, end), h2.title, out);
		}
		return out;
	}

	/**
	 * Parse one drops {@code <h2>} region, appending its rows to {@code out}. Rows inherit the headings
	 * above them, and the heading <b>depth</b> decides what is a group and what is a section.
	 *
	 * <p>The depth matters because the wiki uses the extra level to split a monster's drops by location
	 * or combat level. On a Cyclops the {@code <h3>}s are the locations (Warriors' Guild top floor /
	 * basement) and the {@code <h4>}s under each are that location's tables — so an {@code <h3>} with
	 * {@code <h4>}s beneath it is a <i>group</i> and the {@code <h4>} is the section, while an
	 * {@code <h3>} with no {@code <h4>}s (the common case) <i>is</i> the section. A non-generic
	 * {@code <h2>} ("Level 99 drops", "Drop table 2") is itself a group. Collapsing these levels merges
	 * the top floor's and basement's like-named tables — same names, different drops and rates — which
	 * is what made the Dragon defender (basement "Pre-roll" only) look like a drop from every Cyclops.
	 */
	private static void parseRegion(String region, String h2Title, List<DropRow> out)
	{
		// A generic "Drops" heading adds no grouping of its own — the headings under it carry it all.
		boolean generic = h2Title.equalsIgnoreCase("Drops");

		// Merge headings and rows by position, so each row inherits the headings above it.
		List<Event> events = new ArrayList<>();
		Matcher hm = HEADING.matcher(region);
		while (hm.find())
		{
			events.add(new Event(hm.start(), Integer.parseInt(hm.group(1)), clean(hm.group(2)), null));
		}
		Matcher rm = ROW.matcher(region);
		while (rm.find())
		{
			String rowHtml = rm.group(1);
			if (!rowHtml.contains("item-col"))
			{
				continue;
			}
			String[] cells = rowCells(rowHtml);
			if (cells != null)
			{
				events.add(new Event(rm.start(), 0, null, cells));
			}
		}
		events.sort((a, b) -> Integer.compare(a.pos, b.pos));

		String h3 = null;
		String h4 = null;
		for (Event e : events)
		{
			if (e.heading != null)
			{
				if (e.level == 3)
				{
					h3 = e.heading;
					// A new <h3> opens a new group; its rows must not inherit the last group's <h4>.
					h4 = null;
				}
				else
				{
					h4 = e.heading;
				}
				continue;
			}

			// The deepest heading names the table; an <h3> is only a group once an <h4> sits under it.
			String section = h4 != null ? h4 : h3;
			String group = join(generic ? null : h2Title, h4 != null ? h3 : null);
			if (section == null)
			{
				// No subheading at all: a generic region has nothing to attribute the rows to (there
				// should be none); a per-level region falls back to its own <h2> title as the section.
				if (generic)
				{
					continue;
				}
				section = h2Title;
				group = "";
			}
			out.add(new DropRow(e.cells[0], e.cells[1], e.cells[2], group, section));
		}
	}

	/** Join the heading levels scoping a row into one group label, skipping the ones it doesn't have. */
	private static String join(String outer, String inner)
	{
		if (outer == null || outer.isEmpty())
		{
			return inner == null ? "" : inner;
		}
		if (inner == null || inner.isEmpty())
		{
			return outer;
		}
		return outer + ": " + inner;
	}

	/** Pull [item, quantity, rarity] out of one drop-table row, or null when it has no item link. */
	private static String[] rowCells(String rowHtml)
	{
		Matcher im = ITEM.matcher(rowHtml);
		if (!im.find())
		{
			return null;
		}
		String item = decodeSlug(im.group(1));

		List<String> tds = new ArrayList<>();
		String rarity = "";
		Matcher tm = TD.matcher(rowHtml);
		while (tm.find())
		{
			tds.add(tm.group(2));
			// The rarity cell is the one the wiki colours by rarity tier (class contains table-bg).
			if (rarity.isEmpty() && tm.group(1).contains("table-bg"))
			{
				rarity = rarityText(tm.group(2));
			}
		}
		String quantity = tds.size() >= 3 ? clean(tds.get(2)) : "";
		if (rarity.isEmpty() && tds.size() >= 4)
		{
			rarity = rarityText(tds.get(3));
		}
		return new String[]{item, quantity, rarity};
	}

	/**
	 * Read a rarity cell the way the wiki displays it. Each value sits in a span whose <b>text</b> is the
	 * raw source fraction and whose {@code data-drop-oneover} is the same odds as 1/x — the form the wiki
	 * renders, and the only one a player can compare at a glance ({@code 16/100} vs {@code 1/6.25}). So
	 * take the attribute where there is one, and keep everything around it (a multi-roll {@code "2 × "}
	 * prefix, a {@code ';'} joining a per-roll rate to the combined per-kill rate) as written.
	 */
	private static String rarityText(String cellHtml)
	{
		Matcher m = ONE_OVER.matcher(cellHtml);
		StringBuilder sb = new StringBuilder();
		while (m.find())
		{
			m.appendReplacement(sb, Matcher.quoteReplacement(m.group(1)));
		}
		m.appendTail(sb);
		return FOOTNOTE.matcher(clean(sb.toString())).replaceAll("").trim();
	}

	/** A wiki page slug ({@code Grimy_ranarr_weed}) → a display name ({@code Grimy ranarr weed}). */
	private static String decodeSlug(String slug)
	{
		try
		{
			return URLDecoder.decode(slug, "UTF-8").replace('_', ' ');
		}
		catch (UnsupportedEncodingException | IllegalArgumentException e)
		{
			return slug.replace('_', ' ');
		}
	}

	/** Strip tags, unescape the entities the wiki emits, and collapse whitespace. */
	static String clean(String s)
	{
		if (s == null)
		{
			return "";
		}
		String t = TAG.matcher(s).replaceAll(" ");
		t = t.replace("&nbsp;", " ").replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">")
			.replace("&quot;", "\"").replace("&#39;", "'");
		Matcher nm = NUMERIC_ENTITY.matcher(t);
		StringBuilder sb = new StringBuilder();
		while (nm.find())
		{
			int cp = Integer.parseInt(nm.group(1));
			nm.appendReplacement(sb, Matcher.quoteReplacement(new String(Character.toChars(cp))));
		}
		nm.appendTail(sb);
		// Normalise non-breaking spaces (from &nbsp; / &#160;) — Java's \s and trim() ignore them.
		return sb.toString().replace('\u00A0', ' ').replaceAll("\\s+", " ").trim();
	}

	private static File cacheFileFor(String key)
	{
		// Slugify for a safe filename, disambiguated with a hash so distinct names never collide.
		String slug = key.replaceAll("[^a-z0-9]+", "-");
		return new File(CACHE_DIR, slug + "-" + Integer.toHexString(key.hashCode()) + ".json");
	}

	private static void writeCache(File cacheFile, String json)
	{
		try
		{
			Files.createDirectories(CACHE_DIR.toPath());
			Files.write(cacheFile.toPath(), json.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.debug("Failed to cache drop page to {}", cacheFile, e);
		}
	}

	/** An {@code <h2>} heading: where its content starts (just after {@code </h2>}) and its cleaned title. */
	private static final class Heading2
	{
		private final int start;
		private final String title;

		private Heading2(int start, String title)
		{
			this.start = start;
			this.title = title;
		}
	}

	/** A merged heading/row event at a page position: exactly one of {@code heading} / {@code cells}. */
	private static final class Event
	{
		private final int pos;
		/** Heading depth (3 or 4) — what separates a location/level group from a drop table. 0 for a row. */
		private final int level;
		private final String heading;
		private final String[] cells;

		private Event(int pos, int level, String heading, String[] cells)
		{
			this.pos = pos;
			this.level = level;
			this.heading = heading;
			this.cells = cells;
		}
	}

	/** The {@code action=parse} response shape: {@code {"parse":{"text":{"*":"<html>"}}}}. */
	static final class ParseResponse
	{
		private Parse parse;
	}

	static final class Parse
	{
		private Text text;
	}

	static final class Text
	{
		@SerializedName("*")
		private String star;
	}
}

package com.bettermonsterexamine.loot;

import java.util.Locale;

/**
 * Pure display helpers for a {@link DropRow} — the string shaping the drops panel needs, with no
 * Swing dependency so it stays trivially unit-testable (mirrors {@code StatFormat} for stats).
 * Rarity shows as the wiki's compound value, quantity as its display range, and coin values compact.
 */
final class DropFormat
{
	private DropFormat()
	{
	}

	/**
	 * The rarity tier for colour-coding, from the drop probability. {@code Always} (100%) and any
	 * unknown / unparseable rarity are {@code COMMON}; thresholds: uncommon past 1/50, rare past
	 * 1/500, ultra-rare past 1/5000.
	 */
	static RarityTier tierOf(String rarity)
	{
		double p = probability(rarity);
		if (p <= 0 || p >= 1.0 / 50)
		{
			return RarityTier.COMMON;
		}
		if (p >= 1.0 / 500)
		{
			return RarityTier.UNCOMMON;
		}
		if (p >= 1.0 / 5000)
		{
			return RarityTier.RARE;
		}
		return RarityTier.ULTRA_RARE;
	}

	/**
	 * Rarity as a probability in {@code (0, 1]}: {@code "Always"} → 1, an {@code "a/b"} fraction → a/b,
	 * a multi-roll {@code "N × 1/M"} → N/M, or {@code -1} when unparseable. The wiki's compound cells
	 * ({@code "2 × 1/24,576 ; 1/12,480 [d 2]"}) reduce to their combined per-kill rate first.
	 */
	static double probability(String rarity)
	{
		if (rarity == null)
		{
			return -1;
		}
		String r = effective(rarity);
		if (r.equalsIgnoreCase("Always"))
		{
			return 1.0;
		}
		if (r.startsWith("~"))
		{
			r = r.substring(1).trim();
		}
		// "N × 1/M" (N rolls) — approximate the per-kill rate as N × the per-roll fraction.
		int mult = r.indexOf('×');
		if (mult >= 0)
		{
			try
			{
				double rolls = Double.parseDouble(r.substring(0, mult).replace(",", "").trim());
				return rolls * fraction(r.substring(mult + 1));
			}
			catch (NumberFormatException e)
			{
				return -1;
			}
		}
		return fraction(r);
	}

	/** Parse a plain {@code "a/b"} fraction (or a bare number), tolerating commas; {@code -1} on failure. */
	private static double fraction(String s)
	{
		String r = s.replace(",", "").trim();
		int slash = r.indexOf('/');
		try
		{
			if (slash < 0)
			{
				return Double.parseDouble(r);
			}
			double num = Double.parseDouble(r.substring(0, slash).trim());
			double den = Double.parseDouble(r.substring(slash + 1).trim());
			return den == 0 ? -1 : num / den;
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	/**
	 * Reduce a wiki rarity cell to its effective per-kill value: strip any footnote ({@code "[d 2]"})
	 * and, when the cell states a combined rate after a {@code ';'} ({@code "2 × 1/24,576 ; 1/12,480"}),
	 * keep that combined part. Otherwise the cell is returned trimmed.
	 */
	static String effective(String rarity)
	{
		String r = rarity.replaceAll("\\[[^\\]]*\\]", "").trim();
		int semi = r.lastIndexOf(';');
		return semi >= 0 ? r.substring(semi + 1).trim() : r;
	}

	/**
	 * Rarity as the wiki shows it — the <b>full</b> value, including a multi-roll {@code "N × 1/M"} and
	 * any {@code ';'}-separated combined rate; only commas/dashes are tidied. {@code "Always"}, or a
	 * plain dash when unknown. (Colour-coding reduces this to its effective rate; the display keeps it.)
	 */
	static String rarity(DropRow row)
	{
		if (row.isAlways())
		{
			return "Always";
		}
		String r = row.getRarity();
		return r == null || r.trim().isEmpty() ? "-" : display(r.trim());
	}

	/**
	 * Quantity as the wiki rendered it ({@code "1"}, {@code "35-55"}, {@code "60 (noted)"}), trimmed.
	 * Empty when the row carries none — the caller drops the "×N" suffix rather than showing a bare "0".
	 */
	static String quantity(DropRow row)
	{
		String q = row.getQuantity();
		return q == null ? "" : display(q.trim());
	}

	/** Compact coin value: plain digits under a million, else one-decimal {@code M}/{@code B}; blank for ≤0. */
	static String price(long n)
	{
		if (n <= 0)
		{
			return "";
		}
		if (n < 1_000_000)
		{
			return Long.toString(n);
		}
		if (n < 1_000_000_000)
		{
			return trimDecimal(n / 1_000_000.0) + "M";
		}
		return trimDecimal(n / 1_000_000_000.0) + "B";
	}

	/**
	 * Display cleanup for the numbers the wiki hands us: drop thousands commas ({@code "1,000"} →
	 * {@code "1000"}) and turn en/em dashes into a plain hyphen. The RuneScape font <i>has</i> glyphs for
	 * "–"/"—" — they just look bad at panel size, so a range reads better as a plain "4-13".
	 */
	private static String display(String s)
	{
		return s.replace(",", "").replace('–', '-').replace('—', '-');
	}

	private static String trimDecimal(double v)
	{
		String s = String.format(Locale.US, "%.1f", v);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}
}

package com.bettermonsterexamine.loot;

/**
 * How rare a drop is, used to colour-code its odds. Derived purely from the drop probability
 * ({@link DropFormat#tierOf}): {@code Always} and unknown rarities are {@code COMMON}.
 */
enum RarityTier
{
	COMMON,
	UNCOMMON,
	RARE,
	ULTRA_RARE
}

package com.bettermonsterexamine.loot;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Bridges wiki item names to RuneLite client item ids via the OSRS Wiki <b>Bucket</b> {@code item_id}
 * bucket ({@code page_name → id}). The drops layer needs it because the page parse yields item names
 * as wiki page titles, while the client's price/alch/icon lookups key on the numeric item id; once we
 * have the id, {@code ItemManager}/{@code ItemComposition} supply everything else with zero network.
 *
 * <p>Bulk-loaded once (like {@link com.bettermonsterexamine.MonsterDataService}) — the map changes
 * rarely, so it's fetched whole, cached under {@code .runelite/better-monster-examine/item-ids.json},
 * and refreshed in the background past {@link #MAX_AGE}. Loading happens off the client thread and EDT,
 * paginating past the 5000-row cap; accessors return null until it lands.
 */
@Slf4j
@Singleton
public class ItemIdService
{
	private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT = "better-monster-examine (RuneLite plugin)";
	private static final File CACHE_DIR = new File(RuneLite.RUNELITE_DIR, "better-monster-examine");
	private static final File CACHE_FILE = new File(CACHE_DIR, "item-ids.json");
	private static final Duration MAX_AGE = Duration.ofDays(7);
	/** Bucket hard-caps every query at 5000 rows; we paginate with {@code offset} while a batch fills it. */
	private static final int ROW_LIMIT = 5000;

	private final Gson gson;
	private final OkHttpClient http;
	private final ScheduledExecutorService executor;

	/** wiki item page name -> client item id; published atomically once the bulk load lands. */
	private volatile Map<String, Integer> byName = Collections.emptyMap();
	private volatile Runnable updateListener;

	@Inject
	ItemIdService(Gson gson, OkHttpClient http, ScheduledExecutorService executor)
	{
		this.gson = gson;
		this.http = http;
		this.executor = executor;
		executor.execute(this::init);
	}

	/** Set the callback fired (on a background thread) once the id map has been published. */
	public void setUpdateListener(Runnable listener)
	{
		this.updateListener = listener;
	}

	/** True once the id map has been loaded (from cache or network), so lookups return real ids. */
	public boolean isLoaded()
	{
		return !byName.isEmpty();
	}

	/** The client item id for a wiki item page name, or null when unknown (or not loaded yet). */
	public Integer idFor(String itemName)
	{
		return itemName == null ? null : byName.get(itemName);
	}

	private void init()
	{
		boolean haveCache = false;
		if (CACHE_FILE.isFile())
		{
			try (Reader r = Files.newBufferedReader(CACHE_FILE.toPath(), StandardCharsets.UTF_8))
			{
				BucketResponse cached = gson.fromJson(r, BucketResponse.class);
				if (cached != null && cached.bucket != null && !cached.bucket.isEmpty())
				{
					publish(index(cached));
					haveCache = true;
					log.info("Loaded item-id map from cache ({} entries)", byName.size());
				}
			}
			catch (Exception e)
			{
				log.debug("Failed to read cached item-id map", e);
			}
		}

		boolean fresh = haveCache && (System.currentTimeMillis() - CACHE_FILE.lastModified()) < MAX_AGE.toMillis();
		if (!fresh)
		{
			log.debug("{} Fetching item-id map.", haveCache ? "Cache stale." : "Cache miss.");
			fetch();
		}
	}

	/**
	 * Fetch the whole {@code item_id} bucket (paginating past the 5000-row cap) synchronously on the
	 * executor thread — never the client thread or EDT — then publish and cache the merged result.
	 */
	private void fetch()
	{
		try
		{
			List<Row> all = new ArrayList<>();
			int offset = 0;
			while (true)
			{
				HttpUrl url = HttpUrl.get(API_URL).newBuilder()
					.addQueryParameter("action", "bucket")
					.addQueryParameter("format", "json")
					.addQueryParameter("query", buildQuery(offset))
					.build();
				Request req = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
				int batch;
				try (Response res = http.newCall(req).execute())
				{
					if (!res.isSuccessful() || res.body() == null)
					{
						log.debug("Item-id fetch returned {}", res.code());
						return;
					}
					BucketResponse parsed = gson.fromJson(res.body().string(), BucketResponse.class);
					if (parsed == null || parsed.bucket == null)
					{
						log.debug("Item-id response carried no bucket");
						return;
					}
					batch = parsed.bucket.size();
					all.addAll(parsed.bucket);
				}
				if (batch < ROW_LIMIT)
				{
					break;
				}
				offset += ROW_LIMIT;
			}

			Map<String, Integer> map = index(new BucketResponse(all));
			if (map.isEmpty())
			{
				return;
			}
			// Parse (and publish) before caching so a corrupt download never poisons the cache.
			publish(map);
			writeCache(gson.toJson(new BucketResponse(all)));
			log.info("Fetched and cached item-id map ({} entries)", map.size());
		}
		catch (Exception e)
		{
			log.debug("Item-id fetch/parse failed", e);
		}
	}

	private void publish(Map<String, Integer> map)
	{
		this.byName = map;
		Runnable listener = updateListener;
		if (listener != null)
		{
			listener.run();
		}
	}

	/** Build the paginated bulk {@code select('page_name','id')} Bucket query over {@code item_id}. */
	private static String buildQuery(int offset)
	{
		return "bucket('item_id').select('page_name','id')"
			+ ".offset(" + offset + ").limit(" + ROW_LIMIT + ").run()";
	}

	/**
	 * Build the name → id map from a parsed Bucket response (first row wins for a repeated name). Pure
	 * over its argument, so the {@code id}-array shape stays unit-testable. Empty when the response
	 * carried no {@code bucket}.
	 */
	static Map<String, Integer> index(BucketResponse response)
	{
		Map<String, Integer> map = new HashMap<>();
		if (response == null || response.bucket == null)
		{
			return map;
		}
		for (Row r : response.bucket)
		{
			if (r == null || r.pageName == null || r.id == null || r.id.isEmpty())
			{
				continue;
			}
			Integer id = parseId(r.id.get(0));
			if (id != null)
			{
				map.putIfAbsent(r.pageName, id);
			}
		}
		return map;
	}

	/** Parse a Bucket id string (repeated fields arrive as string arrays, e.g. {@code ["383"]}). */
	static Integer parseId(String s)
	{
		if (s == null)
		{
			return null;
		}
		try
		{
			return Integer.parseInt(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static void writeCache(String json)
	{
		try
		{
			Files.createDirectories(CACHE_DIR.toPath());
			Files.write(CACHE_FILE.toPath(), json.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.debug("Failed to cache item-id map", e);
		}
	}

	/** The wrapper the Bucket API returns: {@code {"bucketQuery": …, "bucket": [ rows ]}}. */
	static final class BucketResponse
	{
		private List<Row> bucket;

		BucketResponse()
		{
		}

		BucketResponse(List<Row> bucket)
		{
			this.bucket = bucket;
		}
	}

	/** One {@code item_id} row: the item page name and its id (a Bucket repeated field → string array). */
	static final class Row
	{
		@SerializedName("page_name")
		private String pageName;
		@SerializedName("id")
		private List<String> id;
	}
}

package com.bettermonsterexamine.loot;

