/**
 * The searchable monster side panel. Owns the search field, the Recent/Favorites views, and the
 * selection state machine. A shared {@link MonsterHeader} sits above a {@code Stats | Drops} tab
 * strip whose body swaps between the stats {@link MonsterCard} and the {@link DropsCard}, so the
 * selected monster + variant stay put across both tabs. The Recent/Favorites model lives in
 * {@link LookupHistory}. One of four sibling regions shows at a time: live search results, the card
 * area, a list view, or the empty-state hint.
 */
public class BetterMonsterExaminePanel extends PluginPanel
{
	/** Config group the persisted Recent/Favorites JSON lives under (alongside the typed config). */
	private static final String CONFIG_GROUP = "bettermonsterexamine";
	private static final String HISTORY_KEY = "historyData";
	private static final String HINT = "Search a monster, right-click → Stats, or Examine one in game.";
	/** Where the footer link and the nav button's right-click entry both send a reporter. */
	static final String ISSUES_URL = "https://github.com/prettyrocket/better-monster-examine/issues";

	private final MonsterDataService data;
	private final BetterMonsterExamineConfig config;
	private final ConfigManager configManager;
	private final Gson gson;
	private final DropPageService drops;

	private final IconTextField searchField = new IconTextField();
	private final JPanel resultsPanel = new JPanel();
	/** Shared monster-identity header (name, variant selector, links), above the tab strip. */
	private final MonsterHeader header;
	/** The Stats tab body: the wiki-style stat blocks. */
	private final MonsterCard card;
	/** The Drops tab body: the current monster's drop list. */
	private final DropsCard dropsCard;
	/** header + Stats|Drops tab strip + swappable body; shown once a monster is selected. */
	private final JPanel cardArea = new JPanel();
	/** The body region the tab strip swaps between {@link #card} and {@link #dropsCard}. */
	private final JPanel tabDisplay = new JPanel(new BorderLayout());
	/** The Stats | Drops tab strip and its two tabs, so a menu action can open straight to one. */
	private MaterialTabGroup contentTabs;
	private MaterialTab statsTab;
	private MaterialTab dropsTab;
	/** Empty-state hint, shown in place of {@link #cardArea} when nothing is selected. */
	private final JPanel hintPanel = new JPanel();
	private final JLabel hintLabel = new JLabel();
	/** True while the Drops tab is the active one, so async drop loads know to re-render it. */
	private boolean dropsTabActive;
	/** Recent/Favorites list view, shown in place of the card area while a mode is active. */
	private final JPanel listPanel = new JPanel();

	/** Which view the panel is showing: normal search/card, or one of the two list modes. */
	private enum Mode
	{
		NORMAL, RECENT, FAVORITES
	}

	private final LookupHistory history;
	private Mode mode = Mode.NORMAL;
	private final JButton recentTabButton;
	private final JButton favoritesTabButton;

	private List<MonsterData> currentVariants;
	private MonsterData currentSelection;

	/**
	 * Notified with the monster whenever a card renders, so the in-game overlay can mirror what
	 * the side panel is showing. The plugin sets this; left null when there's no overlay to feed.
	 */
	private Consumer<MonsterData> selectionListener;

	public BetterMonsterExaminePanel(MonsterIcons icons, MonsterDataService data, DropPageService drops, ItemIdService itemIds, DropsCard dropsCard, BetterMonsterExamineConfig config, ConfigManager configManager, Gson gson, IntSupplier playerCombatLevel, IntSupplier playerHpLevel, IntSupplier playerSlayerLevel, BufferedImage titleIcon)
	{
		super(false);
		this.data = data;
		this.drops = drops;
		this.dropsCard = dropsCard;
		this.config = config;
		this.configManager = configManager;
		this.gson = gson;
		this.history = LookupHistory.fromJson(gson, configManager.getConfiguration(CONFIG_GROUP, HISTORY_KEY));
		this.header = new MonsterHeader(config, playerCombatLevel,
			m -> history.isFavorite(m.getName(), m.getVersion()),
			this::toggleFavorite,
			this::selectVariant);
		this.card = new MonsterCard(icons, config, playerHpLevel, playerSlayerLevel);

		// Re-render the Drops tab when a page's drops — or the bulk item-id map that supplies its
		// icons/prices — land in the background (background thread → EDT).
		drops.setUpdateListener(page -> SwingUtilities.invokeLater(() -> onDropsLoaded(page)));
		itemIds.setUpdateListener(() -> SwingUtilities.invokeLater(this::onItemIdsLoaded));

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBorder(new EmptyBorder(8, 8, 8, 8));

		// Search bar (clearly a search bar: magnifier icon)
		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setPreferredSize(new Dimension(100, 30));
		searchField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		searchField.setMinimumSize(new Dimension(0, 30));
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent e)
			{
				onSearchTextChanged();
			}

			public void removeUpdate(DocumentEvent e)
			{
				onSearchTextChanged();
			}

			public void changedUpdate(DocumentEvent e)
			{
				onSearchTextChanged();
			}
		});

		// The two mode buttons sit in the search row: ↺ Recent and ★ Favorites. Glyph text with a
		// tooltip (no bundled icons yet); the active mode is flagged in brand orange.
		recentTabButton = makeTabButton("↺", "Recent", () -> onTabClicked(Mode.RECENT));
		favoritesTabButton = makeTabButton("★", "Favorites", () -> onTabClicked(Mode.FAVORITES));

		JPanel searchRow = new JPanel();
		searchRow.setLayout(new BoxLayout(searchRow, BoxLayout.X_AXIS));
		searchRow.setAlignmentX(LEFT_ALIGNMENT);
		searchRow.add(searchField);
		searchRow.add(Box.createRigidArea(new Dimension(4, 0)));
		searchRow.add(recentTabButton);
		searchRow.add(Box.createRigidArea(new Dimension(2, 0)));
		searchRow.add(favoritesTabButton);
		searchRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		add(searchRow);
		add(Box.createRigidArea(new Dimension(0, 6)));

		// Single scroll holding results + the card area, plus the list view (one shown at a time)
		resultsPanel.setLayout(new BoxLayout(resultsPanel, BoxLayout.Y_AXIS));
		resultsPanel.setAlignmentX(LEFT_ALIGNMENT);
		listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
		listPanel.setAlignmentX(LEFT_ALIGNMENT);
		listPanel.setVisible(false);

		buildCardArea();

		hintPanel.setLayout(new BoxLayout(hintPanel, BoxLayout.Y_AXIS));
		hintPanel.setAlignmentX(LEFT_ALIGNMENT);
		hintLabel.setFont(FontManager.getRunescapeSmallFont());
		hintLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		hintLabel.setAlignmentX(LEFT_ALIGNMENT);
		hintPanel.add(hintLabel);
		hintPanel.setVisible(false);

		JPanel scrollContent = new WidthTrackingPanel();
		scrollContent.setLayout(new BoxLayout(scrollContent, BoxLayout.Y_AXIS));
		scrollContent.add(resultsPanel);
		scrollContent.add(Box.createRigidArea(new Dimension(0, 6)));
		scrollContent.add(cardArea);
		scrollContent.add(hintPanel);
		scrollContent.add(listPanel);
		scrollContent.add(Box.createVerticalGlue());

		JScrollPane scroll = new JScrollPane(scrollContent,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(null);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.setAlignmentX(LEFT_ALIGNMENT);
		add(scroll);

		// Outside the scroll pane, so it stays put rather than scrolling away under a long drop list:
		// a player who hits a wrong stat or a missing drop should never have to hunt for where to say so.
		add(Box.createRigidArea(new Dimension(0, 6)));
		add(issuesLink());

		// Fresh panel opens into Recent by default (or the plain hint when history is disabled).
		showDefaultView();
	}

	/**
	 * The panel's footer: a quiet link to the issue tracker. Kept deliberately understated — it should
	 * be findable the moment someone wants it and ignorable the rest of the time.
	 */
	private static JComponent issuesLink()
	{
		// A flag, not a bug: the RuneScape font has no bug glyph — 🐛 rasterises to a scribble and 🪲 to
		// a tofu box (verified, as with the disclosure triangles, by rendering them). ⚑ reads as "flag
		// this" and covers a feature request too, where ⚠ would look like the panel warning you.
		JLabel link = new JLabel("⚑ Report a bug or request a feature");
		link.setFont(FontManager.getRunescapeSmallFont());
		link.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		link.setToolTipText(ISSUES_URL);
		link.setCursor(new Cursor(Cursor.HAND_CURSOR));
		link.setAlignmentX(LEFT_ALIGNMENT);
		link.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				LinkBrowser.browse(ISSUES_URL);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				link.setForeground(ColorScheme.BRAND_ORANGE);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				link.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			}
		});
		return link;
	}

	// ------------------------------------------------------------------ search

	public void search(String query, boolean selectFirst, String preferredVersion)
	{
		resultsPanel.removeAll();

		// An empty/cleared field shows no results (don't dump the whole bestiary).
		if (query == null || query.trim().isEmpty())
		{
			revalidate();
			repaint();
			return;
		}

		List<String> names = data.searchNames(query, 40);

		for (String name : names)
		{
			JButton b = new JButton(name);
			b.setAlignmentX(LEFT_ALIGNMENT);
			b.setHorizontalAlignment(JButton.LEFT);
			b.setFont(FontManager.getRunescapeSmallFont());
			b.setMaximumSize(new Dimension(Integer.MAX_VALUE, b.getPreferredSize().height));
			b.addActionListener(e -> select(name, null));
			resultsPanel.add(b);
		}

		if (selectFirst && !names.isEmpty())
		{
			select(names.get(0), preferredVersion);
		}
		else
		{
			showSearchResults();
		}

		revalidate();
		repaint();
	}

	private void select(String name, String preferredVersion)
	{
		currentVariants = data.variantsForName(name);
		if (currentVariants.isEmpty())
		{
			// A stored entry whose monster no longer resolves: drop it quietly (once the dataset
			// has actually loaded — an async-empty index isn't proof the monster is gone).
			if (data.isLoaded())
			{
				pruneDead(name);
			}
			return;
		}

		// Picking a monster collapses the result list so only its card remains on screen.
		resultsPanel.removeAll();

		// A real selection always lands in the normal card view, even from an open list mode.
		if (mode != Mode.NORMAL)
		{
			mode = Mode.NORMAL;
			updateTabButtons();
		}

		currentSelection = data.variant(name, preferredVersion);
		recordSelection(currentSelection);
		renderCard();
	}

	/** The variant dropdown picked a form: switch to it, record it, and re-render. */
	private void selectVariant(MonsterData m)
	{
		currentSelection = m;
		recordSelection(m);
		renderCard();
	}

	// ------------------------------------------------------------------ render

	/** Re-render the current card in place (e.g. after the highlight mode changes). */
	public void refresh()
	{
		if (currentSelection != null)
		{
			renderCard();
		}
	}

	private void renderCard()
	{
		MonsterData m = currentSelection;
		if (m == null)
		{
			return;
		}
		header.show(m, currentVariants);
		card.show(m);
		// Warm this monster's drops so the Drops tab is ready; render now if it's the active tab.
		drops.request(m.getName());
		if (dropsTabActive)
		{
			renderDrops();
		}
		showCardArea();
		revalidate();
		repaint();

		// Let the overlay mirror the panel's current monster.
		if (selectionListener != null)
		{
			selectionListener.accept(m);
		}
	}

	// --------------------------------------------------------------------- drops

	/** Build the card area: shared header + the Stats|Drops tab strip over the swappable body. */
	private void buildCardArea()
	{
		cardArea.setLayout(new BoxLayout(cardArea, BoxLayout.Y_AXIS));
		cardArea.setAlignmentX(LEFT_ALIGNMENT);
		cardArea.setVisible(false);
		tabDisplay.setAlignmentX(LEFT_ALIGNMENT);

		contentTabs = new MaterialTabGroup(tabDisplay);
		contentTabs.setAlignmentX(LEFT_ALIGNMENT);
		statsTab = new MaterialTab("Stats", contentTabs, card);
		dropsTab = new MaterialTab("Drops", contentTabs, dropsCard);
		statsTab.setOnSelectEvent(() ->
		{
			dropsTabActive = false;
			header.setVariantSelectorVisible(true);
			return true;
		});
		dropsTab.setOnSelectEvent(() ->
		{
			dropsTabActive = true;
			header.setVariantSelectorVisible(false);
			renderDrops();
			return true;
		});
		contentTabs.addTab(statsTab);
		contentTabs.addTab(dropsTab);

		cardArea.add(header);
		cardArea.add(Box.createRigidArea(new Dimension(0, 6)));
		cardArea.add(contentTabs);
		cardArea.add(Box.createRigidArea(new Dimension(0, 6)));
		cardArea.add(tabDisplay);

		contentTabs.select(statsTab);
	}

	/**
	 * Open a monster's card to a specific tab — the entry point for the in-game right-click Stats /
	 * Drops menu options. Searches + selects the monster, then switches to the requested tab.
	 */
	public void openMonster(String name, String version, boolean drops)
	{
		search(name, true, version);
		if (currentSelection != null)
		{
			contentTabs.select(drops ? dropsTab : statsTab);
		}
	}

	/**
	 * Open a monster asked for by another plugin. Deliberately stricter than {@link #openMonster}: that
	 * one auto-selects the best fuzzy hit, which is right for a name read off the game but wrong for one
	 * that crossed a plugin boundary, where a near-miss would silently show the wrong monster. Only an
	 * exact name opens a card; anything else goes in the search box so the user picks from the results.
	 *
	 * @return true when the name resolved and a card is showing
	 */
	public boolean openMonsterRequested(String name, String version, boolean drops)
	{
		if (data.variantsForName(name).isEmpty())
		{
			// Setting the text fires the document listener, which shows live results without selecting
			// anything — and leaves the name visible, so a miss reads as "no match" rather than a no-op.
			searchField.setText(name);
			return false;
		}
		openMonster(name, version, drops);
		return currentSelection != null;
	}

	/** Render the Drops tab for the current selection — the wiki's sections, or a loading hint. */
	private void renderDrops()
	{
		MonsterData m = currentSelection;
		if (m == null)
		{
			dropsCard.showMessage("Select a monster to see its drops.");
			return;
		}
		// Ensure the page is loading, then show whatever's parsed so far. A null table means the
		// page hasn't landed yet; the update listener re-renders when it does.
		drops.request(m.getName());
		dropsCard.show(drops.tableFor(m.getName()));
	}

	/** A page's drops landed async: re-render the Drops tab if it's showing this monster. */
	private void onDropsLoaded(String page)
	{
		MonsterData m = currentSelection;
		if (dropsTabActive && m != null && m.getName().equalsIgnoreCase(page))
		{
			renderDrops();
		}
	}

	/** The bulk item-id map landed: re-render the Drops tab so icons and prices resolve. */
	private void onItemIdsLoaded()
	{
		if (dropsTabActive && currentSelection != null)
		{
			renderDrops();
		}
	}

	/** Register a listener fed the current monster on each render, for the in-game overlay. */
	public void setSelectionListener(Consumer<MonsterData> listener)
	{
		this.selectionListener = listener;
	}

	// ------------------------------------------------ recent / favorites views

	/** Search-field document changes: empty returns to the default view; text shows live results. */
	private void onSearchTextChanged()
	{
		String text = searchField.getText();
		if (text == null || text.trim().isEmpty())
		{
			showDefaultView();
			return;
		}
		// Typing leaves any active list mode and shows live results.
		if (mode != Mode.NORMAL)
		{
			mode = Mode.NORMAL;
			updateTabButtons();
		}
		// Don't trail the previously-viewed card beneath the live results — a fresh query is a
		// clean slate until the user picks a result.
		header.clear();
		card.clear();
		dropsCard.clear();
		currentSelection = null;
		search(text, false, null);
	}

	/** The view for an empty search field: Recent by default, or the plain hint when history is off. */
	private void showDefaultView()
	{
		resultsPanel.removeAll();
		if (config.enableHistory())
		{
			enterMode(Mode.RECENT);
			return;
		}
		mode = Mode.NORMAL;
		// Keep whatever card is showing; only fall back to the hint when there's nothing at all.
		ensureNormalContent();
		updateTabButtons();
		revalidate();
		repaint();
	}

	/** A mode button: toggles its list view off if already active, else switches to it. */
	private void onTabClicked(Mode target)
	{
		if (mode == target)
		{
			exitListMode();
		}
		else
		{
			enterMode(target);
		}
	}

	private void enterMode(Mode target)
	{
		mode = target;
		showList();
		renderList();
		updateTabButtons();
		revalidate();
		repaint();
	}

	private void exitListMode()
	{
		mode = Mode.NORMAL;
		ensureNormalContent();
		updateTabButtons();
		revalidate();
		repaint();
	}

	// One of four sibling regions shows at a time: the list, live results, the card area, or the hint.

	private void showList()
	{
		showOnly(listPanel);
	}

	private void showSearchResults()
	{
		showOnly(resultsPanel);
	}

	private void showCardArea()
	{
		showOnly(cardArea);
	}

	private void showHint(String msg)
	{
		hintLabel.setText("<html><body style='width:180px'>" + msg + "</body></html>");
		showOnly(hintPanel);
	}

	/** Show exactly one of the four sibling regions, hiding the other three. */
	private void showOnly(JPanel region)
	{
		listPanel.setVisible(region == listPanel);
		resultsPanel.setVisible(region == resultsPanel);
		cardArea.setVisible(region == cardArea);
		hintPanel.setVisible(region == hintPanel);
	}

	/** In normal mode, show exactly one body: live results while searching, the card, else the hint. */
	private void ensureNormalContent()
	{
		String text = searchField.getText();
		boolean searching = text != null && !text.trim().isEmpty();
		if (searching)
		{
			showSearchResults();
		}
		else if (currentSelection != null)
		{
			showCardArea();
		}
		else
		{
			showHint(HINT);
		}
	}

	private void updateTabButtons()
	{
		boolean on = config.enableHistory();
		recentTabButton.setVisible(on);
		favoritesTabButton.setVisible(on);
		recentTabButton.setForeground(mode == Mode.RECENT ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
		favoritesTabButton.setForeground(mode == Mode.FAVORITES ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
	}

	private void renderList()
	{
		listPanel.removeAll();
		boolean fav = mode == Mode.FAVORITES;
		listPanel.add(listHeader(fav));
		listPanel.add(Box.createRigidArea(new Dimension(0, 4)));

		int shown = 0;
		for (LookupHistory.Entry e : (fav ? history.favorites() : history.recent()))
		{
			// Skip rows whose monster no longer resolves — but only once the dataset has loaded,
			// since an async-empty index would otherwise hide everything on a cold start.
			if (data.isLoaded() && data.variantsForName(e.name).isEmpty())
			{
				continue;
			}
			listPanel.add(listRow(e));
			shown++;
		}
		if (shown == 0)
		{
			listPanel.add(listEmptyHint(fav));
		}
		revalidate();
		repaint();
	}

	/** The list view's title row, with a Clear control on the right when the list is non-empty. */
	private JComponent listHeader(boolean fav)
	{
		JPanel r = new JPanel();
		r.setLayout(new BoxLayout(r, BoxLayout.X_AXIS));
		r.setAlignmentX(LEFT_ALIGNMENT);

		JLabel title = new JLabel((fav ? "Favorites" : "Recent").toUpperCase(Locale.ROOT));
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		r.add(title);
		r.add(Box.createHorizontalGlue());

		boolean any = !(fav ? history.favorites() : history.recent()).isEmpty();
		if (any)
		{
			JButton clear = new JButton(fav ? "Clear favorites" : "Clear history");
			clear.setFont(FontManager.getRunescapeSmallFont());
			clear.setFocusable(false);
			clear.setMargin(new Insets(0, 6, 0, 6));
			clear.addActionListener(e ->
			{
				if (fav)
				{
					history.clearFavorites();
				}
				else
				{
					history.clearRecent();
				}
				persist();
				renderList();
			});
			r.add(clear);
		}
		capHeight(r);
		return r;
	}

	private JComponent listRow(LookupHistory.Entry e)
	{
		JButton b = new JButton(rowLabel(e));
		b.setAlignmentX(LEFT_ALIGNMENT);
		b.setHorizontalAlignment(JButton.LEFT);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setMaximumSize(new Dimension(Integer.MAX_VALUE, b.getPreferredSize().height));
		b.addActionListener(ev -> select(e.name, e.version));
		return b;
	}

	/** Row label: name + version when the monster has variants, plain name otherwise. */
	private String rowLabel(LookupHistory.Entry e)
	{
		if (!e.version.isEmpty() && data.variantsForName(e.name).size() > 1)
		{
			return e.name + " (" + e.version + ")";
		}
		return e.name;
	}

	private JComponent listEmptyHint(boolean fav)
	{
		String msg = fav
			? "No favorites yet. Open a monster and tap ★ to pin it here."
			: "Nothing here yet. Search a monster, right-click → Stats, or Examine one in game.";
		JLabel l = new JLabel("<html><body style='width:180px'>" + msg + "</body></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setAlignmentX(LEFT_ALIGNMENT);
		return l;
	}

	private JButton makeTabButton(String glyph, String tooltip, Runnable onClick)
	{
		JButton b = new JButton(glyph);
		b.setToolTipText(tooltip);
		b.setFocusable(false);
		b.setMargin(new Insets(0, 4, 0, 4));
		Dimension d = new Dimension(30, 30);
		b.setPreferredSize(d);
		b.setMinimumSize(d);
		b.setMaximumSize(d);
		b.addActionListener(e -> onClick.run());
		return b;
	}

	// ---------------------------------------------------- history bookkeeping

	/** Toggle the favourite state of the card's monster (card callback), persisting + refreshing. */
	private void toggleFavorite(MonsterData m)
	{
		history.toggleFavorite(m.getName(), m.getVersion());
		persist();
		renderCard();
		if (mode == Mode.FAVORITES)
		{
			renderList();
		}
	}

	/**
	 * Record a user-initiated lookup. Called from {@link #select} and the variant dropdown, plus
	 * {@link #recordLookup} for overlay-only in-game lookups; never from programmatic re-renders.
	 */
	private void recordSelection(MonsterData m)
	{
		if (!config.enableHistory() || m == null)
		{
			return;
		}
		history.record(m.getName(), m.getVersion());
		persist();
		// Keep an open Recent view in sync (e.g. an in-game lookup while it's on screen).
		if (mode == Mode.RECENT)
		{
			renderList();
		}
	}

	/**
	 * Record an in-game lookup that didn't open the panel (an overlay-only Stats action or a normal
	 * Examine), so it still lands in Recent. Resolves the variant the same way the overlay does.
	 * Called on the EDT.
	 */
	public void recordLookup(String name, String version)
	{
		if (!config.enableHistory() || name == null)
		{
			return;
		}
		recordSelection(data.variant(name, version));
	}

	/** Drop a stored entry whose monster no longer resolves, refreshing an open list view. */
	private void pruneDead(String name)
	{
		if (history.removeAllByName(name))
		{
			persist();
			if (mode != Mode.NORMAL)
			{
				renderList();
			}
		}
	}

	private void persist()
	{
		configManager.setConfiguration(CONFIG_GROUP, HISTORY_KEY, history.toJson(gson));
	}

	/** React to the enableHistory config toggle: hide/show the buttons and any open list view. */
	public void onHistoryConfigChanged()
	{
		if (!config.enableHistory() && mode != Mode.NORMAL)
		{
			mode = Mode.NORMAL;
			ensureNormalContent();
		}
		updateTabButtons();
		// A card on screen may need its star shown/hidden to match the new setting.
		if (currentSelection != null && mode == Mode.NORMAL)
		{
			renderCard();
		}
		revalidate();
		repaint();
	}

	// --------------------------------------------------------------- utilities

	/** A vertical content panel that fills the scroll viewport width (no horizontal clipping). */
	private static class WidthTrackingPanel extends JPanel implements Scrollable
	{
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 60;
		}

		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private void capHeight(JComponent c)
	{
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		c.setAlignmentX(LEFT_ALIGNMENT);
	}
}

package com.bettermonsterexamine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;

/**
 * Recovers the monster levels the Bucket API <b>cannot</b> carry, by parsing the wiki page's
 * {@code Infobox Monster} wikitext.
 *
 * <p>The wiki's {@code Module:Infobox Monster} writes each level to Bucket as
 * {@code tonumber_norefs(str)}, so a level that isn't a plain integer becomes {@code nil} and the
 * field is <b>omitted from the row entirely</b> — there is nothing in Bucket to widen or clean.
 * The only monster this currently hits is Vardorvis, whose Strength and Defence are HP-scaling
 * ranges ({@code |str1 = 270-<br />360}), which is why they rendered as a dash. Every other
 * Bucket-missing level really is blank on the wiki, and must keep rendering as a dash.
 *
 * <p>Pure and static, so it stays unit-testable without the network ({@link WikiSanitizer} does the
 * same for Bucket's TEXT fields). {@link MonsterDataService} fetches the handful of affected pages
 * in bulk and feeds their wikitext through here.
 */
final class InfoboxLevels
{
	/** Bucket field name -> the {@code Infobox Monster} wikitext parameter that feeds it. */
	private static final Map<String, String> PARAMS;

	static
	{
		Map<String, String> p = new LinkedHashMap<>();
		p.put("attack_level", "att");
		p.put("strength_level", "str");
		p.put("defence_level", "def");
		p.put("magic_level", "mage");
		p.put("ranged_level", "range");
		PARAMS = Collections.unmodifiableMap(p);
	}

	private static final Pattern INFOBOX = Pattern.compile("(?i)\\{\\{\\s*Infobox[ _]+Monster\\b");
	/** A version parameter, e.g. {@code version2}. */
	private static final Pattern VERSION_PARAM = Pattern.compile("(?i)^version(\\d*)$");
	/** A plain integer level — already in Bucket, so nothing was dropped. */
	private static final Pattern PLAIN_INT = Pattern.compile("-?\\d+");
	private static final Pattern BR = Pattern.compile("(?i)<br\\s*/?>");

	private InfoboxLevels()
	{
	}

	/** One level the wiki carries but Bucket dropped: the value as displayed, plus its footnote. */
	@Getter
	static final class LevelText
	{
		private final String value;
		/** The wiki's own {@code {{efn}}} footnote for this value (why it's a range), or null. */
		private final String note;

		LevelText(String value, String note)
		{
			this.value = value;
			this.note = note;
		}
	}

	/**
	 * Parse a monster page's wikitext into <em>version anchor</em> (lower-case; {@code ""} when the
	 * page has no versions) -> <em>Bucket field name</em> -> the dropped level. Levels that are
	 * plain integers are skipped: Bucket already carries those. A page with nothing dropped yields
	 * an empty map.
	 */
	static Map<String, Map<String, LevelText>> parse(String wikitext)
	{
		Map<String, Map<String, LevelText>> out = new LinkedHashMap<>();
		if (wikitext == null)
		{
			return out;
		}

		// Footnotes are defined once and referenced by name from anywhere on the page — Vardorvis
		// defines the "scales with HP" note on its max hit and re-references it from str/def.
		Map<String, String> footnotes = footnotes(wikitext);

		// A page can host more than one Infobox Monster; merge them all.
		Matcher start = INFOBOX.matcher(wikitext);
		int from = 0;
		while (start.find(from))
		{
			String block = template(wikitext, start.start());
			if (block == null)
			{
				from = start.end();
				continue;
			}
			readInfobox(block, footnotes, out);
			from = start.start() + block.length();
		}
		return out;
	}

	/** Pull one infobox's dropped levels into {@code out}, keyed by the version each belongs to. */
	private static void readInfobox(String block, Map<String, String> footnotes,
		Map<String, Map<String, LevelText>> out)
	{
		Map<String, String> params = params(block);

		// version1 = Post-quest, version2 = Awakened, … — the anchors Bucket keys its rows by. A
		// suffix-less "version" (or no version at all) means the page has a single, unnamed form.
		Map<String, String> anchors = new LinkedHashMap<>();
		for (Map.Entry<String, String> e : params.entrySet())
		{
			Matcher v = VERSION_PARAM.matcher(e.getKey());
			if (v.matches())
			{
				anchors.put(v.group(1), anchor(e.getValue()));
			}
		}
		if (anchors.isEmpty())
		{
			anchors.put("", "");
		}

		for (Map.Entry<String, String> field : PARAMS.entrySet())
		{
			for (Map.Entry<String, String> anchor : anchors.entrySet())
			{
				// "str2" belongs to version2; a suffix-less "str" applies to every version.
				String value = params.get(field.getValue() + anchor.getKey());
				if (value == null)
				{
					value = params.get(field.getValue());
				}
				LevelText level = value == null ? null : clean(value, footnotes);
				if (level == null)
				{
					continue;
				}
				out.computeIfAbsent(anchor.getValue(), k -> new LinkedHashMap<>())
					.put(field.getKey(), level);
			}
		}
	}

	/**
	 * Clean one raw level parameter to what the wiki displays, and resolve any footnote it
	 * references: {@code "270-<br />360{{efn|name=def}}"} -> value {@code "270-360"} + the "def"
	 * note. Null when the parameter is blank (genuinely unknown on the wiki — it must stay a dash)
	 * or a plain integer (Bucket already carries it, so nothing was dropped).
	 *
	 * <p>The {@code <br>} the wiki uses to wrap a range across a narrow infobox cell is dropped
	 * rather than kept as a line break, and en/em dashes become a plain hyphen — they look bad at
	 * panel size, the same reason {@code DropFormat} normalises them.
	 */
	private static LevelText clean(String raw, Map<String, String> footnotes)
	{
		String note = null;
		StringBuilder text = new StringBuilder();
		int i = 0;
		while (i < raw.length())
		{
			if (raw.startsWith("{{", i))
			{
				String tpl = template(raw, i);
				if (tpl != null)
				{
					List<String> parts = split(tpl.substring(2, tpl.length() - 2));
					if (!parts.isEmpty() && parts.get(0).trim().equalsIgnoreCase("efn"))
					{
						String resolved = footnote(parts, footnotes);
						if (resolved != null && note == null)
						{
							note = resolved;
						}
					}
					i += tpl.length();
					continue;
				}
			}
			text.append(raw.charAt(i++));
		}

		String value = plain(text.toString()).replaceAll("\\s+", "");
		// Test before dropping thousands commas: "1,000" is a value Bucket dropped (Lua's tonumber
		// rejects the comma), so it has to survive the plain-integer check that "280" is caught by.
		if (value.isEmpty() || PLAIN_INT.matcher(value).matches())
		{
			return null;
		}
		return new LevelText(value.replace(",", ""), note);
	}

	/** A version anchor as Bucket keys it, e.g. {@code "Post-quest"} -> {@code "post-quest"}. */
	private static String anchor(String raw)
	{
		return plain(raw).replaceAll("\\s+", " ").trim().toLowerCase(Locale.ROOT);
	}

	/** Shared text cleanup: drop {@code <br>}s and wiki markup, and normalise en/em dashes. */
	private static String plain(String raw)
	{
		String out = BR.matcher(raw).replaceAll("");
		out = WikiSanitizer.text(out);
		return out.replace('–', '-').replace('—', '-');
	}

	/**
	 * The text an {@code {{efn}}} carries, or — when it's a bare {@code {{efn|name=def}}} reference —
	 * the text of the definition it points at. Null when it resolves to neither.
	 */
	private static String footnote(List<String> parts, Map<String, String> footnotes)
	{
		Efn efn = new Efn(parts);
		if (efn.text != null)
		{
			return efn.text;
		}
		return efn.name == null ? null : footnotes.get(efn.name);
	}

	/** Every named {@code {{efn|name=x|text}}} definition on the page, keyed by lower-case name. */
	private static Map<String, String> footnotes(String wikitext)
	{
		Map<String, String> out = new HashMap<>();
		for (int i = wikitext.indexOf("{{"); i >= 0; i = wikitext.indexOf("{{", i + 2))
		{
			String tpl = template(wikitext, i);
			if (tpl == null)
			{
				continue;
			}
			List<String> parts = split(tpl.substring(2, tpl.length() - 2));
			if (parts.isEmpty() || !parts.get(0).trim().equalsIgnoreCase("efn"))
			{
				continue;
			}
			Efn efn = new Efn(parts);
			if (efn.name != null && efn.text != null)
			{
				out.put(efn.name, efn.text);
			}
		}
		return out;
	}

	/** An {@code {{efn}}}'s two parts of interest: its {@code name=}, and its positional text. */
	private static final class Efn
	{
		private String name;
		private String text;

		Efn(List<String> parts)
		{
			for (String part : parts.subList(1, parts.size()))
			{
				String p = part.trim();
				if (p.toLowerCase(Locale.ROOT).startsWith("name="))
				{
					name = p.substring("name=".length()).trim().toLowerCase(Locale.ROOT);
				}
				else if (!p.isEmpty() && p.indexOf('=') < 0)
				{
					text = WikiSanitizer.text(p);
				}
			}
		}
	}

	/** A template's top-level {@code |name = value} parameters, keyed by lower-case name. */
	private static Map<String, String> params(String block)
	{
		Map<String, String> out = new LinkedHashMap<>();
		List<String> parts = split(block.substring(2, block.length() - 2));
		for (String part : parts.subList(Math.min(1, parts.size()), parts.size()))
		{
			int eq = part.indexOf('=');
			if (eq < 0)
			{
				continue;
			}
			out.put(part.substring(0, eq).trim().toLowerCase(Locale.ROOT), part.substring(eq + 1));
		}
		return out;
	}

	/**
	 * Split a template body on its <b>top-level</b> {@code |} separators — a {@code |} nested inside
	 * a wikilink or another template (the {@code {{efn|name=def}}} hanging off a level) belongs to
	 * that nested thing, not to the infobox.
	 */
	private static List<String> split(String body)
	{
		List<String> out = new ArrayList<>();
		int depth = 0;
		int from = 0;
		for (int i = 0; i < body.length(); i++)
		{
			if (body.startsWith("{{", i) || body.startsWith("[[", i))
			{
				depth++;
				i++;
			}
			else if (body.startsWith("}}", i) || body.startsWith("]]", i))
			{
				depth--;
				i++;
			}
			else if (depth == 0 && body.charAt(i) == '|')
			{
				out.add(body.substring(from, i));
				from = i + 1;
			}
		}
		out.add(body.substring(from));
		return out;
	}

	/**
	 * The whole {@code {{…}}} template starting at {@code from}, brace-matched so nested templates
	 * don't end it early. Null when it never closes.
	 */
	private static String template(String s, int from)
	{
		int depth = 0;
		for (int i = from; i < s.length() - 1; i++)
		{
			if (s.startsWith("{{", i))
			{
				depth++;
				i++;
			}
			else if (s.startsWith("}}", i))
			{
				if (--depth == 0)
				{
					return s.substring(from, i + 2);
				}
				i++;
			}
		}
		return null;
	}
}

package com.bettermonsterexamine;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Cleans the few non-uniform shapes the OSRS Wiki Bucket API leaves in TEXT fields, so the rest
 * of the data layer sees plain strings. Bucket regularises the old wikitext-template garbage
 * (issue #24) into four bounded forms: MediaWiki strip-markers (bounded by the U+007F control
 * char), {@code <div class="plainlist">} bullet wrappers, {@code <br>} line breaks, and
 * {@code [[wikilinks]]}. Pure and static, so it stays trivially unit-testable without the network.
 */
final class WikiSanitizer
{
	/** The U+007F control char that delimits a MediaWiki strip-marker on both ends. */
	private static final String DEL = String.valueOf((char) 0x7f);
	/** MediaWiki strip-marker (e.g. a {@code <ref>} footnote), e.g. {@code UNIQ--ref-…-QINU}. */
	private static final Pattern STRIP_MARKER = Pattern.compile(DEL + "[^" + DEL + "]*" + DEL);
	/** {@code [[Magic]]} -> Magic, {@code [[a|b]]} -> b. */
	private static final Pattern LINK = Pattern.compile("\\[\\[(?:[^\\]|]*\\|)?([^\\]]*)\\]\\]");
	private static final Pattern BR = Pattern.compile("(?i)<br\\s*/?>");
	private static final Pattern DIV = Pattern.compile("(?i)</?div[^>]*>");

	private WikiSanitizer()
	{
	}

	/** Clean a single TEXT value: drop strip-markers, unwrap wikilinks, collapse outer whitespace. */
	static String text(String s)
	{
		if (s == null)
		{
			return null;
		}
		String out = STRIP_MARKER.matcher(s).replaceAll("");
		out = LINK.matcher(out).replaceAll("$1");
		return out.replace("[[", "").replace("]]", "").trim();
	}

	/**
	 * Expand a Bucket {@code max_hit} array into clean per-value lines: unwrap plainlist
	 * {@code <div>} + {@code *} bullet wrappers, split on {@code <br>}, drop strip-markers and
	 * wikilinks, and discard empties. Each remaining line is one max-hit value, e.g.
	 * {@code "45 (special)"}.
	 */
	static List<String> maxHitLines(List<String> raw)
	{
		List<String> out = new ArrayList<>();
		if (raw == null)
		{
			return out;
		}
		for (String element : raw)
		{
			if (element == null)
			{
				continue;
			}
			String expanded = DIV.matcher(element).replaceAll("\n");
			expanded = BR.matcher(expanded).replaceAll("\n");
			for (String part : expanded.split("\n"))
			{
				String line = part.trim();
				if (line.startsWith("*"))
				{
					line = line.substring(1).trim();
				}
				line = text(line);
				if (!line.isEmpty())
				{
					out.add(line);
				}
			}
		}
		return out;
	}
}

package com.bettermonsterexamine;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.util.Locale;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Shared Swing building blocks for the side-panel cards, so {@link MonsterCard}, {@link MonsterHeader}
 * and the drops card assemble their blocks, rows and headers from one place and stay visually in
 * lock-step (same dark theme, padding and alignment). All helpers are stateless.
 */
public final class PanelStyle
{
	/** Fixed body width (px) used by the wrapping value labels, so their HTML lays out consistently. */
	private static final int WRAP_WIDTH = 200;

	private PanelStyle()
	{
	}

	/** A vertical, dark-theme block with the standard card padding. */
	public static JPanel block()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(6, 8, 6, 8));
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/** A horizontal, dark-theme row (typically label + glue + value). */
	public static JPanel rowX()
	{
		JPanel r = new JPanel();
		r.setLayout(new BoxLayout(r, BoxLayout.X_AXIS));
		r.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		r.setAlignmentX(Component.LEFT_ALIGNMENT);
		r.setBorder(new EmptyBorder(1, 0, 1, 0));
		return r;
	}

	/** The orange uppercase section-title label, with the trailing gap under it. */
	public static JLabel sectionHeader(String text)
	{
		JLabel h = headerLabel(text);
		h.setBorder(new EmptyBorder(0, 0, 3, 0));
		return h;
	}

	/** The orange uppercase section-title label, without the trailing gap (for inline header rows). */
	public static JLabel headerLabel(String text)
	{
		JLabel h = new JLabel(text.toUpperCase(Locale.ROOT));
		h.setFont(FontManager.getRunescapeSmallFont());
		h.setForeground(ColorScheme.BRAND_ORANGE);
		h.setAlignmentX(Component.LEFT_ALIGNMENT);
		return h;
	}

	/** A full-width, wrapping value label (used for examine text and the attribute list). */
	public static JLabel wrappedLabel(String text, Color color, boolean italic)
	{
		return wrappedLabel(text, color, italic, WRAP_WIDTH);
	}

	/** A wrapping label at a given width, for rows that share their line with something else. */
	public static JLabel wrappedLabel(String text, Color color, boolean italic, int width)
	{
		JLabel l = new JLabel("<html><body style='width:" + width + "px'>"
			+ StatFormat.esc(text).replace("\n", "<br>") + "</body></html>");
		Font f = FontManager.getRunescapeSmallFont();
		l.setFont(italic ? f.deriveFont(Font.ITALIC) : f);
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	/** Pin a component's max height to its preferred height, so a Y-axis BoxLayout won't stretch it. */
	public static void capHeight(JComponent c)
	{
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
	}
}

