import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import static com.bettermonsterexamine.PanelStyle.block;
import static com.bettermonsterexamine.PanelStyle.capHeight;
import static com.bettermonsterexamine.PanelStyle.headerLabel;
import static com.bettermonsterexamine.PanelStyle.rowX;
import static com.bettermonsterexamine.PanelStyle.sectionHeader;
import static com.bettermonsterexamine.PanelStyle.wrappedLabel;

/**
 * The wiki-style stats infobox body, as a self-contained Swing component: the attribute / combat /
 * max-hit / stat / immunity / slayer blocks, colour-coding player-relevant values via
 * {@link StatColors}. The monster-identity header (name, variant selector, links) is drawn
 * separately by {@link MonsterHeader}, which sits above the Stats|Drops tab strip so it stays put
 * while this body swaps with the drops list.
 */
class MonsterCard extends JPanel
{
	/** Uniform on-screen size every stat-grid icon is scaled to. */
	private static final int ICON_BOX = 22;

	private final MonsterIcons icons;
	private final BetterMonsterExamineConfig config;
	private final IntSupplier playerHpLevel;
	private final IntSupplier playerSlayerLevel;

	MonsterCard(MonsterIcons icons, BetterMonsterExamineConfig config,
		IntSupplier playerHpLevel, IntSupplier playerSlayerLevel)
	{
		this.icons = icons;
		this.config = config;
		this.playerHpLevel = playerHpLevel;
		this.playerSlayerLevel = playerSlayerLevel;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	/** Render the stat blocks for {@code m} (the header is drawn separately by {@link MonsterHeader}). */
	void show(MonsterData m)
	{
		removeAll();
		MonsterStats stats = new MonsterStats(m, config.statHighlighting(), playerHpLevel.getAsInt(), playerSlayerLevel.getAsInt());
		buildWiki(stats);
		revalidate();
		repaint();
	}

	/** Replace the card with a plain wrapping message (e.g. the empty-state hint). */
	void showMessage(String text)
	{
		removeAll();
		JLabel l = new JLabel("<html><body style='width:180px'>" + text + "</body></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setAlignmentX(LEFT_ALIGNMENT);
		add(l);
		revalidate();
		repaint();
	}

	void clear()
	{
		removeAll();
		revalidate();
		repaint();
	}

	// ---- Wiki: faithful to the OSRS Wiki monster infobox --------------------

	private void buildWiki(MonsterStats stats)
	{
		// ATTRIBUTES — size/attributes/slayer/flat armour/XP bonus/poisonous.
		JPanel props = block();
		props.add(sectionHeader("Attributes"));
		boolean anyProp = false;
		// Size and attributes share one line, size first: e.g. "7x7, Draconic, Undead, Fiery".
		// The box header already says "Attributes", so the names need no label of their own.
		String sizeAttr = stats.sizeAttr();
		if (sizeAttr != null)
		{
			props.add(wrappedLabel(sizeAttr, Color.WHITE, false));
			anyProp = true;
		}
		MonsterStats.StatField flatArmour = stats.flatArmour();
		if (flatArmour != null)
		{
			props.add(kv("Flat armour", flatArmour.value(), resolve(flatArmour.role()), flatArmour.tooltip()));
			anyProp = true;
		}
		MonsterStats.StatField xp = stats.xpBonus();
		if (xp != null)
		{
			props.add(kv("XP bonus", xp.value(), resolve(xp.role())));
			anyProp = true;
		}
		MonsterStats.StatField pois = stats.poisonous();
		if (pois != null)
		{
			props.add(kv("Poisonous", pois.value(), resolve(pois.role()), pois.tooltip()));
			anyProp = true;
		}
		if (anyProp)
		{
			capHeight(props);
			add(props);
			add(Box.createRigidArea(new Dimension(0, 6)));
		}

		// COMBAT INFO — attack style + speed (dataset).
		JPanel combatInfo = block();
		combatInfo.add(sectionHeader("Combat info"));
		combatInfo.add(kvWrappedRight("Attack style", stats.attackStyle()));
		combatInfo.add(kv("Attack speed", stats.attackSpeed(), Color.WHITE));
		capHeight(combatInfo);
		add(combatInfo);
		add(Box.createRigidArea(new Dimension(0, 6)));

		// MAX HIT — its own box; multi-hit monsters list several values, one per line. Values
		// above the player's Hitpoints level are flagged red (it could take more than your level).
		JPanel maxHit = block();
		maxHit.add(sectionHeader("Max hit"));
		maxHit.add(maxHitLabel(stats.maxHits()));
		capHeight(maxHit);
		add(maxHit);
		add(Box.createRigidArea(new Dimension(0, 6)));

		// Combat stats: the monster's six levels as an icon-over-value row
		List<MonsterStats.StatField> combat = stats.combatLevels();
		if (!combat.isEmpty())
		{
			add(levelBlock("Combat stats",
				new BufferedImage[]{icons.hitpointsIcon, icons.attackIcon, icons.strengthIcon, icons.defenceIcon, icons.magicIcon, icons.rangedIcon},
				combat,
				new String[]{"Hitpoints", "Attack", "Strength", "Defence", "Magic", "Ranged"}));
			add(Box.createRigidArea(new Dimension(0, 6)));
		}

		// Aggressive stats (order: Attack, Strength, Magic, Magic str, Ranged, Ranged str)
		List<String> off = stats.offensiveBonuses();
		if (!off.isEmpty())
		{
			add(gridBlock("Aggressive stats",
				new BufferedImage[]{icons.attackIcon, icons.strengthIcon, icons.magicIcon, icons.magicDamageIcon, icons.rangedIcon, icons.rangedStrengthIcon},
				off.toArray(new String[0]),
				new String[]{"Attack", "Strength", "Magic", "Magic damage", "Ranged", "Ranged strength"}));
			add(Box.createRigidArea(new Dimension(0, 6)));
		}

		// Defensive bonuses, grouped like the wiki
		if (stats.hasDefensive())
		{
			// Rolls only when every input is there, so the three blocks never mix rolls and bonuses.
			boolean rolls = config.showDefenceRolls() && stats.magicDefenceRoll() != null;
			String suffix = rolls ? " roll" : "";
			Map<DefenceRolls.Style, ColourRole> roles = rolls ? stats.defenceRollRoles() : Map.of();

			List<String> meleeBonus = stats.meleeDefence();
			add(gridBlock("Melee defence" + suffix,
				new BufferedImage[]{icons.stabIcon, icons.slashIcon, icons.crushIcon},
				(rolls ? stats.meleeDefenceRoll() : meleeBonus).toArray(new String[0]),
				rollColors(roles, DefenceRolls.Style.STAB, DefenceRolls.Style.SLASH, DefenceRolls.Style.CRUSH),
				defenceTips(rolls, new String[]{"Stab", "Slash", "Crush"}, meleeBonus)));
			add(Box.createRigidArea(new Dimension(0, 6)));

			String element = stats.weaknessElement();
			String weakLabel = element != null ? StatFormat.cap(element) + " weakness" : "Elemental weakness";
			String magicTip = defenceTips(rolls, new String[]{"Magic defence"}, List.of(stats.magicDefence()))[0];
			add(gridBlock("Magic defence" + suffix,
				new BufferedImage[]{icons.magicDefenceIcon, weaknessIcon(element)},
				new String[]{rolls ? stats.magicDefenceRoll() : stats.magicDefence(), stats.weaknessSeverity()},
				new Color[]{rollColors(roles, DefenceRolls.Style.MAGIC)[0], Color.WHITE},
				new String[]{magicTip, weakLabel}));
			add(Box.createRigidArea(new Dimension(0, 6)));

			List<String> rangedBonus = stats.rangedDefence();
			add(gridBlock("Ranged defence" + suffix,
				new BufferedImage[]{icons.lightIcon, icons.standardIcon, icons.heavyIcon},
				(rolls ? stats.rangedDefenceRoll() : rangedBonus).toArray(new String[0]),
				rollColors(roles, DefenceRolls.Style.LIGHT, DefenceRolls.Style.STANDARD, DefenceRolls.Style.HEAVY),
				defenceTips(rolls, new String[]{"Light", "Standard", "Heavy"}, rangedBonus)));
		}

		// Immunities — burn / cannon / thrall, all from Bucket.
		JPanel imm = block();
		imm.add(sectionHeader("Immunities"));
		boolean anyImm = false;
		String burn = stats.burn();
		if (burn != null)
		{
			imm.add(kv("Burn", burn, Color.WHITE));
			anyImm = true;
		}
		MonsterStats.StatField cannon = stats.cannon();
		if (cannon != null)
		{
			imm.add(kv("Cannon", cannon.value(), resolve(cannon.role())));
			anyImm = true;
		}
		MonsterStats.StatField thrall = stats.thrall();
		if (thrall != null)
		{
			imm.add(kv("Thrall", thrall.value(), resolve(thrall.role())));
			anyImm = true;
		}
		if (anyImm)
		{
			add(Box.createRigidArea(new Dimension(0, 6)));
			capHeight(imm);
			add(imm);
		}

		// SLAYER — last block, only for Slayer targets: the required level (red when above your
		// Slayer level) sits inline on the header row next to the Slayer icon; XP is its own line;
		// the assignment categories are plain text and the masters show as chatheads.
		if (stats.slayerMonster())
		{
			JPanel slayer = block();

			MonsterStats.StatField req = stats.slayerRequirement();
			String reqTip = req.tooltip() != null ? req.tooltip() : "Slayer level";
			JPanel head = rowX();
			head.add(headerLabel("Slayer"));
			head.add(Box.createHorizontalGlue());
			JLabel slayerLvlIcon = new JLabel(uniformIcon(icons.slayerIcon, 16));
			slayerLvlIcon.setToolTipText(reqTip);
			JLabel lvl = new JLabel(req.value());
			lvl.setFont(FontManager.getRunescapeSmallFont());
			lvl.setForeground(resolve(req.role()));
			lvl.setToolTipText(reqTip);
			head.add(slayerLvlIcon);
			head.add(Box.createRigidArea(new Dimension(3, 0)));
			head.add(lvl);
			capHeight(head);
			slayer.add(head);
			slayer.add(Box.createRigidArea(new Dimension(0, 3)));

			String slayerXp = stats.slayerXp();
			if (slayerXp != null)
			{
				slayer.add(kv("Slayer XP", slayerXp, Color.WHITE));
			}

			List<String> categories = stats.slayerCategories();
			if (!categories.isEmpty())
			{
				slayer.add(kvWrappedRight("Category", String.join(", ", categories)));
			}

			List<String> masters = stats.slayerMasters();
			if (!masters.isEmpty())
			{
				slayer.add(Box.createRigidArea(new Dimension(0, 4)));
				slayer.add(caption("Assigned by"));
				slayer.add(masterIconStrip(masters));
			}

			capHeight(slayer);
			add(Box.createRigidArea(new Dimension(0, 6)));
			add(slayer);
		}
	}

	/**
	 * The combat-levels grid. Same cells as {@link #gridBlock}, but a level can carry a footnote:
	 * the few Bucket can't hold render as the wiki's range ("270-360"), and the hover then explains
	 * why — Vardorvis' Defence counting down as he loses HP is a mechanic, not a typo.
	 */
	private JPanel levelBlock(String title, BufferedImage[] cellIcons, List<MonsterStats.StatField> levels,
		String[] labels)
	{
		String[] values = new String[levels.size()];
		String[] tips = new String[levels.size()];
		for (int i = 0; i < levels.size(); i++)
		{
			MonsterStats.StatField level = levels.get(i);
			values[i] = level.value();
			tips[i] = level.tooltip() == null ? labels[i] : labels[i] + " — " + level.tooltip();
		}
		return gridBlock(title, cellIcons, values, tips);
	}

	/** With rolls shown, the bonus they hide moves to the tooltip. */
	private static String[] defenceTips(boolean rolls, String[] labels, List<String> bonuses)
	{
		if (!rolls)
		{
			return labels;
		}
		String[] tips = new String[labels.length];
		for (int i = 0; i < labels.length; i++)
		{
			tips[i] = labels[i] + " — bonus " + bonuses.get(i);
		}
		return tips;
	}

	/** Each style's highlight, white where the ranking doesn't name it. */
	private Color[] rollColors(Map<DefenceRolls.Style, ColourRole> roles, DefenceRolls.Style... styles)
	{
		Color[] colors = new Color[styles.length];
		for (int i = 0; i < styles.length; i++)
		{
			colors[i] = resolve(roles.getOrDefault(styles[i], ColourRole.NEUTRAL));
		}
		return colors;
	}

	private JPanel gridBlock(String title, BufferedImage[] cellIcons, String[] values, String[] labels)
	{
		Color[] colors = new Color[values.length];
		Arrays.fill(colors, Color.WHITE);
		return gridBlock(title, cellIcons, values, colors, labels);
	}

	/** A titled block whose stats are laid out as icon-over-value cells (wiki style). */
	private JPanel gridBlock(String title, BufferedImage[] cellIcons, String[] values, Color[] colors, String[] labels)
	{
		JPanel b = block();
		b.add(sectionHeader(title));

		// GridLayout gives every cell an equal column and centres its content, so groups
		// with few values (melee/magic defence) spread evenly across the width (space-around).
		JPanel grid = new JPanel(new GridLayout(1, cellIcons.length, 4, 0));
		grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		grid.setAlignmentX(LEFT_ALIGNMENT);
		for (int i = 0; i < cellIcons.length; i++)
		{
			grid.add(statCell(cellIcons[i], values[i], colors[i], labels[i]));
		}
		capHeight(grid);
		b.add(grid);
		b.setAlignmentX(LEFT_ALIGNMENT);
		return b;
	}

	private JComponent statCell(BufferedImage icon, String value, String tooltip)
	{
		return statCell(icon, value, Color.WHITE, tooltip);
	}

	private JComponent statCell(BufferedImage icon, String value, Color valueColor, String tooltip)
	{
		JPanel cell = new JPanel();
		cell.setLayout(new BoxLayout(cell, BoxLayout.Y_AXIS));
		cell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Hovering the cell just names the stat ("Strength", "Stab", "Light").
		cell.setToolTipText(tooltip);

		// Every icon is normalised to the same box, so cells share an icon height and the
		// values below them line up on a common baseline regardless of native icon size.
		JLabel ic = new JLabel(uniformIcon(icon, ICON_BOX));
		ic.setAlignmentX(CENTER_ALIGNMENT);

		JLabel vl = new JLabel(value);
		vl.setFont(FontManager.getRunescapeSmallFont());
		vl.setForeground(valueColor);
		vl.setAlignmentX(CENTER_ALIGNMENT);

		cell.add(ic);
		cell.add(Box.createRigidArea(new Dimension(0, 3)));
		cell.add(vl);
		return cell;
	}

	/** A small left-aligned caption label (the light-grey key style used for sub-labels). */
	private JLabel caption(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setAlignmentX(LEFT_ALIGNMENT);
		return l;
	}

	/** The Slayer masters as a left-flowing row of chatheads (name on hover); text fallback if unbundled. */
	private JPanel masterIconStrip(List<String> masters)
	{
		JPanel strip = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 2));
		strip.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		strip.setAlignmentX(LEFT_ALIGNMENT);
		for (String master : masters)
		{
			String name = StatFormat.masterName(master);
			BufferedImage icon = icons.masterIcon(master);
			JLabel l = icon != null ? new JLabel(uniformIcon(icon, ICON_BOX)) : new JLabel(name);
			if (icon == null)
			{
				l.setFont(FontManager.getRunescapeSmallFont());
				l.setForeground(Color.WHITE);
			}
			l.setToolTipText(name);
			strip.add(l);
		}
		capHeight(strip);
		return strip;
	}

	/** Scale to fit a fixed square (preserving aspect) and centre it, so all icons match. */
	private static ImageIcon uniformIcon(BufferedImage img, int box)
	{
		double scale = Math.min((double) box / img.getWidth(), (double) box / img.getHeight());
		int w = Math.max(1, (int) Math.round(img.getWidth() * scale));
		int h = Math.max(1, (int) Math.round(img.getHeight() * scale));
		Image scaled = img.getScaledInstance(w, h, Image.SCALE_SMOOTH);
		BufferedImage canvas = new BufferedImage(box, box, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		g.drawImage(scaled, (box - w) / 2, (box - h) / 2, null);
		g.dispose();
		return new ImageIcon(canvas);
	}

	private BufferedImage weaknessIcon(String element)
	{
		if (element == null)
		{
			return icons.elementalIcon;
		}
		return icons.getElementalWeaknessIcon(StatFormat.cap(element));
	}

	// --------------------------------------------------------------- layout helpers

	private JPanel kv(String k, String v, Color valueColor)
	{
		return kv(k, v, valueColor, null);
	}

	private JPanel kv(String k, String v, Color valueColor, String tooltip)
	{
		JPanel r = rowX();
		JLabel kl = new JLabel(k);
		kl.setFont(FontManager.getRunescapeSmallFont());
		kl.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		JLabel vl = new JLabel(v);
		vl.setFont(FontManager.getRunescapeSmallFont());
		vl.setForeground(valueColor);
		// Tooltip on both labels (not just the row) so it shows wherever you hover the line.
		if (tooltip != null)
		{
			r.setToolTipText(tooltip);
			kl.setToolTipText(tooltip);
			vl.setToolTipText(tooltip);
		}
		r.add(kl);
		r.add(Box.createHorizontalGlue());
		r.add(vl);
		capHeight(r);
		return r;
	}

	/**
	 * Label on the left with a right-aligned value that wraps across as many lines as needed,
	 * kept tight (used for the attack-style list). The value fills the width left by the label.
	 */
	private JPanel kvWrappedRight(String k, String v)
	{
		JPanel r = new JPanel(new BorderLayout());
		r.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		r.setBorder(new EmptyBorder(1, 0, 1, 0));
		r.setAlignmentX(LEFT_ALIGNMENT);

		JLabel kl = new JLabel(k);
		kl.setFont(FontManager.getRunescapeSmallFont());
		kl.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		kl.setVerticalAlignment(JLabel.TOP);

		// The value takes a fixed body width on the right (BorderLayout.EAST honours it), so it
		// wraps and right-aligns within the space left by the label. A fixed width avoids relying
		// on the label's off-screen preferred size, which can measure short before it's realised.
		int valueW = 112;
		JLabel vl = new JLabel("<html><body style='width:" + valueW + "px; text-align: right'>"
			+ StatFormat.esc(v).replace("\n", "<br>") + "</body></html>");
		vl.setFont(FontManager.getRunescapeSmallFont());
		vl.setForeground(Color.WHITE);
		vl.setVerticalAlignment(JLabel.TOP);

		r.add(kl, BorderLayout.WEST);
		r.add(vl, BorderLayout.EAST);
		capHeight(r);
		return r;
	}

	/**
	 * The max-hit list as a wrapping label, with any line whose value exceeds the player's
	 * Hitpoints level flagged (red in Standard, orange + a warning sign in colour-blind mode).
	 * {@code hpLevel <= 0} (unknown) or the Off mode disables the highlight.
	 */
	private JLabel maxHitLabel(List<MonsterStats.MaxHitLine> lines)
	{
		boolean cb = config.statHighlighting() == HighlightMode.COLOUR_BLIND;
		String hex = cb ? "#e69f00" : "#ff4040";

		StringBuilder sb = new StringBuilder("<html><body style='width:200px'>");
		boolean anyOver = false;
		for (int i = 0; i < lines.size(); i++)
		{
			if (i > 0)
			{
				sb.append("<br>");
			}
			MonsterStats.MaxHitLine line = lines.get(i);
			if (line.overHp())
			{
				anyOver = true;
				// In colour-blind mode add a warning sign so the cue survives without colour.
				String text = StatFormat.esc(line.text()) + (cb ? " ⚠" : "");
				sb.append("<span style='color:").append(hex).append("'>").append(text).append("</span>");
			}
			else
			{
				sb.append(StatFormat.esc(line.text()));
			}
		}
		sb.append("</body></html>");

		JLabel l = new JLabel(sb.toString());
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(Color.WHITE);
		l.setAlignmentX(LEFT_ALIGNMENT);
		// The highlight marks a hit larger than your Hitpoints level.
		if (anyOver)
		{
			l.setToolTipText("Max hit exceeds your hitpoints level (" + playerHpLevel.getAsInt() + ").");
		}
		return l;
	}

	// ---- player-relevant colours (delegate to the shared palette) -----------

	/** Resolve a view-model {@link ColourRole} to a concrete colour for the active mode. */
	private Color resolve(ColourRole role)
	{
		return StatColors.resolve(role, config.statHighlighting());
	}
}

package com.bettermonsterexamine;

/**
 * Where the right-click "Stats" action renders a monster's card: the searchable side panel,
 * an in-game overlay drawn in the game viewport, or both.
 */
public enum RenderTarget
{
	/** Open the searchable side panel (the original behaviour). */
	PANEL("Side panel"),
	/** Draw the card as an in-game overlay; clicking Stats again on the same monster hides it. */
	OVERLAY("Overlay"),
	/** Both the side panel and the overlay. */
	BOTH("Both");

	private final String label;

	RenderTarget(String label)
	{
		this.label = label;
	}

	boolean showsPanel()
	{
		return this == PANEL || this == BOTH;
	}

	boolean showsOverlay()
	{
		return this == OVERLAY || this == BOTH;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.bettermonsterexamine;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;

/**
 * Correlates native NPC Examine responses with summary snapshots captured when each NPC was
 * clicked. It also recognises the messages it asks RuneLite to inject: those use the same
 * {@code NPC_EXAMINE} type and must not consume the next native response.
 */
final class ExamineSummaryQueue
{
	private static final int MAX_PENDING_AGE_TICKS = 5;
	private static final int MAX_INJECTED_MESSAGES = 32;
	private final Deque<PendingSummary> pending = new ArrayDeque<>();
	private final Deque<String> injected = new ArrayDeque<>();

	void add(String monsterName, List<String> summary, int tick)
	{
		discardExpired(tick);
		pending.addLast(new PendingSummary(monsterName, summary, tick));
	}

	/**
	 * Consume one NPC_EXAMINE message. Returns what to render against a native response, or null
	 * when this is one of our own messages, nothing is pending, or the clicked NPC was unknown.
	 */
	Examined onNpcExamine(String message, int tick)
	{
		if (injected.removeFirstOccurrence(message))
		{
			return null;
		}

		discardExpired(tick);
		PendingSummary next = pending.pollFirst();
		if (next == null || next.lines.isEmpty())
		{
			return null;
		}

		String block = String.join("<br>", next.lines);
		if (injected.size() >= MAX_INJECTED_MESSAGES)
		{
			// RuneLite deliberately drops queued chat on Tutorial Island; bound markers that never
			// get their matching event so repeated examines there cannot grow this deque forever.
			injected.removeFirst();
		}
		injected.addLast(block);
		return new Examined(next.monsterName, block);
	}

	/** A consumed/dropped click must not shift every later Examine response indefinitely. */
	private void discardExpired(int tick)
	{
		while (!pending.isEmpty() && tick - pending.peekFirst().tick > MAX_PENDING_AGE_TICKS)
		{
			pending.removeFirst();
		}
	}

	void clearPending()
	{
		pending.clear();
	}

	void clear()
	{
		pending.clear();
		injected.clear();
	}

	/** A matched Examine: the name to prepend to the game's own line, and the block to inject. */
	static final class Examined
	{
		private final String monsterName;
		private final String block;

		private Examined(String monsterName, String block)
		{
			this.monsterName = monsterName;
			this.block = block;
		}

		String getMonsterName()
		{
			return monsterName;
		}

		String getBlock()
		{
			return block;
		}
	}

	private static final class PendingSummary
	{
		private final String monsterName;
		private final List<String> lines;
		private final int tick;

		private PendingSummary(String monsterName, List<String> lines, int tick)
		{
			this.monsterName = monsterName;
			this.lines = lines;
			this.tick = tick;
		}
	}
}

package com.bettermonsterexamine;

import java.math.BigDecimal;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure formatting and parsing helpers for monster stats — the string/number shaping shared by
 * the side panel ({@link MonsterCard}) and the in-game {@link MonsterCardOverlay}. No Swing or
 * drawing dependencies, so it stays trivially unit-testable.
 */
final class StatFormat
{
	private static final Pattern DIGITS = Pattern.compile("\\d+");

	private StatFormat()
	{
	}

	/** Signed bonus, e.g. {@code +5} / {@code -3}. */
	static String bonus(int v)
	{
		return (v >= 0 ? "+" : "") + v;
	}

	/** A defence roll, grouped for reading, e.g. {@code 12,345}. */
	static String roll(int v)
	{
		return String.format(Locale.ROOT, "%,d", v);
	}

	/** A skill level, or an em dash when absent/zero. */
	static String num(int v)
	{
		return v <= 0 ? "—" : String.valueOf(v);
	}

	/** Format a number without a trailing {@code .0} (e.g. {@code 77.5} → "77.5", {@code 50.0} → "50"). */
	static String number(double v)
	{
		if (v == Math.rint(v) && !Double.isInfinite(v))
		{
			return String.valueOf((long) v);
		}
		return BigDecimal.valueOf(v).stripTrailingZeros().toPlainString();
	}

	static String cap(String s)
	{
		return s == null || s.isEmpty() ? s : s.substring(0, 1).toUpperCase(Locale.ROOT) + s.substring(1);
	}

	/** "5 ticks (3.0 seconds)". */
	static String attackSpeed(MonsterData m)
	{
		int t = m.getAttackSpeed();
		return t + (t == 1 ? " tick" : " ticks") + " (" + String.format("%.1f", t * 0.6) + " seconds)";
	}

	/**
	 * A looser affirmative for wiki yes/no fields that may carry a qualifier, e.g.
	 * {@code "Yes (venom)"} or {@code "Yes (on login)"} — true when the value starts with "yes".
	 * Used for poisonous/aggressive, where the qualifier still means the flag is set.
	 */
	static boolean affirmative(String v)
	{
		return v != null && v.trim().toLowerCase(Locale.ROOT).startsWith("yes");
	}

	/** Map dataset attribute keys to their wiki display names (e.g. dragon → Draconic). */
	static String attributeNames(List<String> attrs)
	{
		StringBuilder sb = new StringBuilder();
		for (String a : attrs)
		{
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(attributeName(a));
		}
		return sb.toString();
	}

	private static String attributeName(String a)
	{
		switch (a)
		{
			case "dragon":
				return "Draconic";
			case "vampyre1":
				return "Vampyre (tier 1)";
			case "vampyre2":
				return "Vampyre (tier 2)";
			case "vampyre3":
				return "Vampyre (tier 3)";
			default:
				return cap(a);
		}
	}

	/** Display name for a Slayer master key (e.g. {@code "konar"} → "Konar quo Maten"). */
	static String masterName(String key)
	{
		return "konar".equals(key) ? "Konar quo Maten" : cap(key);
	}

	/** Join the non-null, non-empty parts with {@code sep}; null when nothing remains. */
	static String join(String sep, String... parts)
	{
		StringBuilder sb = new StringBuilder();
		for (String p : parts)
		{
			if (p == null || p.isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(sep);
			}
			sb.append(p);
		}
		return sb.length() == 0 ? null : sb.toString();
	}

	/** HTML-escape for the panel's wrapping labels. */
	static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** The largest number in a max-hit line's value (the part before any "(label)"), or -1. */
	static int maxValue(String line)
	{
		int paren = line.indexOf('(');
		String value = paren >= 0 ? line.substring(0, paren) : line;
		Matcher m = DIGITS.matcher(value);
		int max = -1;
		while (m.find())
		{
			max = Math.max(max, Integer.parseInt(m.group()));
		}
		return max;
	}
}

package com.bettermonsterexamine;

/**
 * The player-relevant meaning of a stat value, independent of any concrete colour. The
 * {@link MonsterStats} view-model decides the role (e.g. positive flat armour is bad for the
 * player → {@link #DANGER}); each renderer maps it to a colour via
 * {@link StatColors#resolve(ColourRole, HighlightMode)}, so the colour-blind palette stays in
 * one place.
 */
enum ColourRole
{
	/** No player-relevant meaning — plain white text. */
	NEUTRAL,
	/** Bad for the player (aggressive, positive flat armour, over-HP max hit, immunities). */
	DANGER,
	/** In the player's favour (negative flat armour, an XP bonus). */
	GOOD,
	/** The runner-up to a {@link #GOOD} choice (the easiest free style when magic wins alone). */
	NEXT
}

package com.bettermonsterexamine;

import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;

/**
 * One monster variant from the OSRS Wiki Bucket {@code infobox_monster} dataset — the single
 * source behind the plugin. Flat, mirroring the Bucket row; a single name can carry several
 * variants distinguished by {@link #versionAnchor}. TEXT and {@code max_hit} fields keep their raw
 * Bucket values and are cleaned on access via {@link WikiSanitizer}.
 *
 * <p>{@link #version} is not a Bucket field: it is the unique display label
 * {@link MonsterDataService} assigns per variant (the {@code version_anchor}, disambiguated with the
 * combat level when blank or colliding), so the rest of the app keeps treating a variant as
 * "name + version".
 */
@Getter
public class MonsterData
{
	private String name;
	/** Repeated NPC spawn ids (Bucket returns them as strings); see {@link #getId()}. */
	@SerializedName("id")
	private List<String> ids;
	@SerializedName("version_anchor")
	private String versionAnchor;
	/** Bucket serialises this as {@code ""} (this is a/the default form) or {@code null}; not a boolean. */
	@Getter(AccessLevel.NONE)
	@SerializedName("default_version")
	private String defaultVersion;
	/**
	 * The wiki page this row came from. Distinct from {@link #name}: an infobox can set a name that
	 * isn't its page title, so two pages (a boss article and its quest fight) can emit rows sharing
	 * one name. Used to tell the monster's own article from a page that merely mentions it.
	 */
	@SerializedName("page_name")
	private String pageName;

	/** Unique display label among a name's variants; assigned by the service after indexing. */
	@Setter
	private String version = "";

	@SerializedName("combat_level")
	private int level;
	private int hitpoints;
	private int size;

	// Boxed, unlike every other number here: Bucket types these as INTEGER, so a level the wiki
	// writes as a range (Vardorvis' HP-scaling Strength/Defence) fails the module's tonumber() and
	// the field is omitted from the row altogether. Null therefore means "Bucket dropped or lacks
	// it" — distinct from a real 0 (a monster that genuinely cannot use the skill) — which is what
	// lets the service tell the two apart and gap-fill only the former. See InfoboxLevels.
	@Getter(AccessLevel.NONE)
	@SerializedName("attack_level")
	private Integer attackLevel;
	@Getter(AccessLevel.NONE)
	@SerializedName("strength_level")
	private Integer strengthLevel;
	@Getter(AccessLevel.NONE)
	@SerializedName("defence_level")
	private Integer defenceLevel;
	@Getter(AccessLevel.NONE)
	@SerializedName("magic_level")
	private Integer magicLevel;
	@Getter(AccessLevel.NONE)
	@SerializedName("ranged_level")
	private Integer rangedLevel;

	/** The levels the wiki carries but Bucket dropped, by Bucket field name; filled by the service. */
	@Getter(AccessLevel.NONE)
	@Setter
	private Map<String, InfoboxLevels.LevelText> levelRanges = Collections.emptyMap();

	@SerializedName("attack_bonus")
	private int attackBonus;
	@SerializedName("strength_bonus")
	private int strengthBonus;
	@SerializedName("magic_attack_bonus")
	private int magicAttackBonus;
	@SerializedName("magic_damage_bonus")
	private int magicDamageBonus;
	@SerializedName("range_attack_bonus")
	private int rangeAttackBonus;
	@SerializedName("range_strength_bonus")
	private int rangeStrengthBonus;
	// Per-style melee attack bonuses; usually unset on the wiki (it carries the single attack_bonus).
	@SerializedName("stab_attack_bonus")
	private int stabAttackBonus;
	@SerializedName("slash_attack_bonus")
	private int slashAttackBonus;
	@SerializedName("crush_attack_bonus")
	private int crushAttackBonus;

	/**
	 * The seven defence bonuses are <b>boxed</b> for the same reason the levels are: null means
	 * "Bucket carries no value", which is distinct from a real {@code 0}. ~160 rows bestiary-wide
	 * are blank, and reading them as zero produces a confident seven-way tie built from nothing.
	 * The getters still collapse null to 0 so callers that only render a number are unaffected;
	 * {@link #hasDefenceRollInputs()} is how you ask whether there is anything to rank.
	 */
	@Getter(AccessLevel.NONE)
	@SerializedName("stab_defence_bonus")
	private Integer stabDefenceBonus;
	@Getter(AccessLevel.NONE)
	@SerializedName("slash_defence_bonus")
	private Integer slashDefenceBonus;
	@Getter(AccessLevel.NONE)
	@SerializedName("crush_defence_bonus")
	private Integer crushDefenceBonus;
	@Getter(AccessLevel.NONE)
	@SerializedName("magic_defence_bonus")
	private Integer magicDefenceBonus;
	@SerializedName("range_defence_bonus")
	private int rangeDefenceBonus;
	@Getter(AccessLevel.NONE)
	@SerializedName("light_range_defence_bonus")
	private Integer lightRangeDefenceBonus;
	@Getter(AccessLevel.NONE)
	@SerializedName("standard_range_defence_bonus")
	private Integer standardRangeDefenceBonus;
	@Getter(AccessLevel.NONE)
	@SerializedName("heavy_range_defence_bonus")
	private Integer heavyRangeDefenceBonus;
	@SerializedName("flat_armour")
	private int flatArmour;

	@SerializedName("attack_style")
	private List<String> attackStyles;
	@SerializedName("attack_speed")
	private int attackSpeed;
	@Getter(AccessLevel.NONE)
	@SerializedName("max_hit")
	private List<String> maxHit;
	@SerializedName("experience_bonus")
	private double experienceBonus;

	@SerializedName("attribute")
	private List<String> attributes;
	@SerializedName("elemental_weakness")
	private String weaknessElement;
	@SerializedName("elemental_weakness_percent")
	private int weaknessPercent;

	@Getter(AccessLevel.NONE)
	private String examine;
	@Getter(AccessLevel.NONE)
	private String poisonous;

	@SerializedName("cannon_immune")
	private String cannonImmune;
	@SerializedName("thrall_immune")
	private String thrallImmune;
	@SerializedName("burn_immune")
	private String burnImmune;
	@SerializedName("freeze_resistance")
	private String freezeResistance;

	// --- Captured for completeness (not yet rendered — see #31) ---
	@SerializedName("slayer_level")
	private int slayerLevel;
	@SerializedName("slayer_experience")
	private double slayerExperience;
	@SerializedName("slayer_category")
	private List<String> slayerCategory;
	@SerializedName("assigned_by")
	private List<String> assignedBy;
	@SerializedName("uses_skill")
	private List<String> usesSkill;
	private List<String> image;
	@SerializedName("league_region")
	private String leagueRegion;
	@SerializedName("release_date")
	private String releaseDate;
	@Getter(AccessLevel.NONE)
	@SerializedName("is_members_only")
	private String membersOnly;

	// ---- derived accessors -------------------------------------------------

	public int getAttackLevel()
	{
		return attackLevel == null ? 0 : attackLevel;
	}

	public int getStrengthLevel()
	{
		return strengthLevel == null ? 0 : strengthLevel;
	}

	public int getDefenceLevel()
	{
		return defenceLevel == null ? 0 : defenceLevel;
	}

	public int getMagicLevel()
	{
		return magicLevel == null ? 0 : magicLevel;
	}

	public int getRangedLevel()
	{
		return rangedLevel == null ? 0 : rangedLevel;
	}

	public int getStabDefenceBonus()
	{
		return stabDefenceBonus == null ? 0 : stabDefenceBonus;
	}

	public int getSlashDefenceBonus()
	{
		return slashDefenceBonus == null ? 0 : slashDefenceBonus;
	}

	public int getCrushDefenceBonus()
	{
		return crushDefenceBonus == null ? 0 : crushDefenceBonus;
	}

	public int getMagicDefenceBonus()
	{
		return magicDefenceBonus == null ? 0 : magicDefenceBonus;
	}

	public int getStandardRangeDefenceBonus()
	{
		return standardRangeDefenceBonus == null ? 0 : standardRangeDefenceBonus;
	}

	public int getHeavyRangeDefenceBonus()
	{
		return heavyRangeDefenceBonus == null ? 0 : heavyRangeDefenceBonus;
	}

	public int getLightRangeDefenceBonus()
	{
		return lightRangeDefenceBonus == null ? 0 : lightRangeDefenceBonus;
	}

	/**
	 * True when the wiki carries everything {@link DefenceRolls} needs. The Defence and Magic
	 * levels are checked as boxed values on purpose — a Defence level of 0 is real (a Tombs of
	 * Amascut Egg has one) and must not read as missing.
	 */
	boolean hasDefenceRollInputs()
	{
		return defenceLevel != null && magicLevel != null
			&& stabDefenceBonus != null && slashDefenceBonus != null && crushDefenceBonus != null
			&& magicDefenceBonus != null && standardRangeDefenceBonus != null
			&& heavyRangeDefenceBonus != null && lightRangeDefenceBonus != null;
	}

	/**
	 * True when Bucket carries no value at all for one of the five combat levels — either the wiki
	 * leaves it blank, or (Vardorvis) its value is a range Bucket's INTEGER column can't hold. Only
	 * these few monsters are worth fetching a page for; see {@link InfoboxLevels}.
	 */
	boolean hasMissingLevel()
	{
		return attackLevel == null || strengthLevel == null || defenceLevel == null
			|| magicLevel == null || rangedLevel == null;
	}

	/** The wiki's value for a level Bucket dropped (e.g. {@code "270-360"}), or null if none. */
	InfoboxLevels.LevelText getLevelRange(String bucketField)
	{
		return levelRanges.get(bucketField);
	}

	/** The first (primary) NPC id, or 0 when the row carries none — used for the DPS-calc deep link. */
	public int getId()
	{
		if (ids != null)
		{
			for (String s : ids)
			{
				Integer v = parseId(s);
				if (v != null)
				{
					return v;
				}
			}
		}
		return 0;
	}

	/** Parse a Bucket id string to an int, or null when it isn't numeric. */
	static Integer parseId(String s)
	{
		try
		{
			return s == null ? null : Integer.valueOf(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** True when Bucket flags this as a default form ({@code default_version} present). */
	public boolean isDefaultVersion()
	{
		return defaultVersion != null;
	}

	/**
	 * True when this row comes from the monster's own article rather than a page that reuses its
	 * name (a quest fight, an instance). Such a row is the one a player means by the bare name.
	 */
	boolean isOwnPage()
	{
		return pageName != null && name != null && pageName.equalsIgnoreCase(name);
	}

	/**
	 * True when this row's page marks it as a form removed from the game — the wiki keeps
	 * {@code (historical)} pages for old sprites and stats no player can meet.
	 *
	 * <p>Deliberately narrow. It keys on the specific marker rather than on merely having a
	 * parenthetical, because most parentheses mean a live location: {@code Goblin (Vault of War)} and
	 * {@code Goblin (God Wars Dungeon)} are distinct, fightable monsters. {@code Realm of Memories} is
	 * <b>not</b> counted either — despite reading like a flashback it is live quest content, and those
	 * 19 rows carry real hitpoints and real spawn ids, so a player can fight and right-click them (#63).
	 */
	boolean isNonLive()
	{
		if (pageName == null)
		{
			return false;
		}
		String p = pageName.toLowerCase(Locale.ROOT);
		return p.endsWith("(historical)") || p.endsWith("(removed)");
	}

	/**
	 * A fingerprint of everything the plugin actually renders, so variants differing only in
	 * appearance collapse together. The wiki carries a row per sprite — thirteen Hill Giants at level
	 * 28 with identical stats, 124 Guards — and picking between them changes nothing a player can act
	 * on (#62). Deliberately excludes the display label, ids and source page: those are what differ
	 * between rows that are otherwise the same monster.
	 */
	String statKey()
	{
		return new StringBuilder(160)
			.append(level).append('|').append(hitpoints).append('|').append(size).append('|')
			.append(attackLevel).append('|').append(strengthLevel).append('|').append(defenceLevel)
			.append('|').append(magicLevel).append('|').append(rangedLevel).append('|')
			.append(attackBonus).append('|').append(strengthBonus).append('|')
			.append(magicAttackBonus).append('|').append(magicDamageBonus).append('|')
			.append(rangeAttackBonus).append('|').append(rangeStrengthBonus).append('|')
			.append(stabAttackBonus).append('|').append(slashAttackBonus).append('|')
			.append(crushAttackBonus).append('|')
			.append(stabDefenceBonus).append('|').append(slashDefenceBonus).append('|')
			.append(crushDefenceBonus).append('|').append(magicDefenceBonus).append('|')
			.append(rangeDefenceBonus).append('|').append(lightRangeDefenceBonus).append('|')
			.append(standardRangeDefenceBonus).append('|').append(heavyRangeDefenceBonus).append('|')
			.append(flatArmour).append('|').append(attackSpeed).append('|')
			.append(experienceBonus).append('|').append(weaknessElement).append('|')
			.append(weaknessPercent).append('|').append(poisonous).append('|')
			.append(cannonImmune).append('|').append(thrallImmune).append('|').append(burnImmune)
			.append('|').append(freezeResistance).append('|').append(slayerLevel).append('|')
			.append(attackStyles).append('|').append(maxHit).append('|').append(attributes)
			.toString();
	}

	/**
	 * Absorb another row's spawn ids when it collapses into this one. Without this, dropping a
	 * duplicate would strand its ids (1,005 of them bestiary-wide) and right-clicking those spawns
	 * would miss the id index entirely and fall back to the far weaker name+level match.
	 */
	void absorbIds(List<String> more)
	{
		if (more == null || more.isEmpty())
		{
			return;
		}
		List<String> merged = ids == null ? new ArrayList<>() : new ArrayList<>(ids);
		for (String s : more)
		{
			if (!merged.contains(s))
			{
				merged.add(s);
			}
		}
		ids = merged;
	}

	/**
	 * How the wiki tells this row's page apart from the monster's own article — a title's
	 * parenthetical ({@code "Shellbane gryphon (Troubled Tortugans)"} → {@code "Troubled
	 * Tortugans"}), else the whole title. Empty when the page is the monster's own article, or
	 * when Bucket gave no page.
	 */
	String pageQualifier()
	{
		if (pageName == null || isOwnPage())
		{
			return "";
		}
		int open = pageName.lastIndexOf('(');
		int close = pageName.lastIndexOf(')');
		if (open >= 0 && close > open)
		{
			return pageName.substring(open + 1, close).trim();
		}
		return pageName.trim();
	}

	public boolean isMembersOnly()
	{
		return membersOnly != null;
	}

	/** A monster is a Slayer target when the wiki lists a Slayer category for it. */
	public boolean isSlayerMonster()
	{
		return slayerCategory != null && !slayerCategory.isEmpty();
	}

	/** Examine text, cleaned of wiki markup; null when absent. */
	public String getExamine()
	{
		return WikiSanitizer.text(examine);
	}

	/** Poisonous flag (e.g. {@code "Yes (venom)"}), cleaned of wiki markup; null when absent. */
	public String getPoisonous()
	{
		return WikiSanitizer.text(poisonous);
	}

	/** The max-hit values, one clean line each (plainlist/strip-markers/&lt;br&gt;/links removed). */
	public List<String> getMaxHitLines()
	{
		return WikiSanitizer.maxHitLines(maxHit);
	}

	public List<String> getAttackStyles()
	{
		return attackStyles != null ? attackStyles : Collections.emptyList();
	}

	public List<String> getAttributes()
	{
		return attributes != null ? attributes : Collections.emptyList();
	}

	/** Burn-immunity label (e.g. {@code "Immune (weak)"}) when immune, else null. */
	public String getBurnLabel()
	{
		return burnImmune != null && burnImmune.toLowerCase(Locale.ROOT).startsWith("immune") ? burnImmune : null;
	}

	/** True when this immunity field carries the wiki's {@code "Immune"} value. */
	static boolean isImmune(String field)
	{
		return field != null && field.trim().equalsIgnoreCase("Immune");
	}
}

package com.bettermonsterexamine;

/**
 * How the panel colour-codes player-relevant stats (combat level, flat armour, aggressive,
 * poisonous, over-HP max hits).
 */
public enum HighlightMode
{
	/** No colour coding — plain white text. */
	OFF("Off"),
	/** The default red/green palette. */
	STANDARD("Standard"),
	/** An orange/blue palette plus non-colour symbols, for colour-blind players. */
	COLOUR_BLIND("Colour-blind friendly");

	private final String label;

	HighlightMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}
